INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C1','math',5,1,'u3',2,'크기가 같은 분수의 뜻 — 띠·수직선에서 ⟨1/2⟩, ⟨2/4⟩, ⟨3/6⟩처럼 이름은 달라도 나타내는 양이 같은 분수가 있음을 알고, 칸을 잘게 나누거나 다시 묶어도 양이 그대로인 까닭을 알기',ARRAY['6수01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C2','math',5,1,'u3',2,'크기가 같은 분수 만들기 — 분모와 분자에 0이 아닌 같은 수를 곱하거나 0이 아닌 같은 수로 나누어 크기가 같은 분수를 만들고, 더하기·빼기로는 만들 수 없음을 알기',ARRAY['6수01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C3','math',5,1,'u3',3,'약분과 기약분수 — 분모와 분자를 1이 아닌 공약수로 나누어 약분하고, 공약수가 1뿐인 기약분수를 알며 최대공약수로 나누어 한 번에 기약분수로 나타내기',ARRAY['6수01-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C4','math',5,1,'u3',4,'통분과 공통분모 — 분모가 다른 분수의 분모를 같게 통분하고, 두 분모의 곱이나 최소공배수를 공통분모로 쓰며 분자도 같은 수만큼 곱해야 함을 알기',ARRAY['6수01-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C5','math',5,1,'u3',5,'분수의 크기 비교 — 분모가 다른 분수는 통분하여 분자를 견주고, 단위분수·분자가 같은 분수는 분모가 작을수록 크며 ⟨1/2⟩을 기준으로 갈라 볼 수 있음을 알기',ARRAY['6수01-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C6','math',5,1,'u3',6,'분수와 소수의 크기 비교 — 분모를 10·100으로 만들어 분수를 소수로, 소수점 아래 자리 수만큼 분모를 정해 소수를 분수로 바꾸고 같은 꼴로 만들어 크기를 견주기',ARRAY['6수01-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u3-C7','math',5,1,'u3',7,'문제 해결 — 여러 분수를 견줄 때 ⟨1/2⟩ 기준·같은 분자·같은 분모처럼 기댈 곳을 먼저 찾고, 기댈 곳이 없을 때 통분하여 가장 많은 것·가장 적은 것을 찾기',ARRAY['6수01-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X01','math',5,'u3',ARRAY['M5-1-u3-C1','M5-1-u3-C2']::text[],'분모와 분자에 같은 수를 더하거나 빼서 크기가 같은 분수를 만든다(⟨2/3⟩의 분모와 분자에 3을 더해 ⟨5/6⟩)','크기가 같은 분수는 곱하기·나누기로만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X02','math',5,'u3',ARRAY['M5-1-u3-C2','M5-1-u3-C3','M5-1-u3-C4']::text[],'분모나 분자 한쪽에만 곱하거나 한쪽만 나눈다(분자만 3으로 나누어 ⟨3/12⟩)','분모와 분자에 똑같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X03','math',5,'u3',ARRAY['M5-1-u3-C2']::text[],'0을 곱하거나 0으로 나누어도 크기가 같은 분수가 된다고 여긴다','0이 아닌 같은 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X04','math',5,'u3',ARRAY['M5-1-u3-C1','M5-1-u3-C2','M5-1-u3-C3']::text[],'이름이 바뀌면 양도 바뀐다고 여긴다 — 크기가 같은 분수인데 분모·분자가 큰 쪽(또는 작은 쪽)이 더 크다고 본다','잘게 나눈 만큼 개수가 늘어 양은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X05','math',5,'u3',ARRAY['M5-1-u3-C3','M5-1-u3-C6']::text[],'약분을 덜 하고 멈추어 기약분수가 아닌 것을 기약분수라고 여긴다','공약수가 1뿐인지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X06','math',5,'u3',ARRAY['M5-1-u3-C3']::text[],'공약수가 아닌 수로 약분하거나, 한쪽만 나누어떨어지는 수로 약분할 수 있다고 여긴다','분모와 분자를 모두 나누어떨어지게 하는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X07','math',5,'u3',ARRAY['M5-1-u3-C4']::text[],'통분할 때 분모만 공통분모로 바꾸고 분자는 그대로 둔다(⟨1/6⟩을 ⟨1/30⟩으로)','분모를 몇 배 했으면 분자도 몇 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X08','math',5,'u3',ARRAY['M5-1-u3-C4','M5-1-u3-C5','M5-1-u3-C6','M5-1-u3-C7']::text[],'공통분모를 잘못 안다 — 공배수가 아닌 수를 공통분모로 쓰거나, 공통분모는 하나뿐이라고 여기거나, 분모가 다르면 견줄 수 없다고 여긴다','두 분모의 공배수는 모두 공통분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X09','math',5,'u3',ARRAY['M5-1-u3-C5','M5-1-u3-C7']::text[],'분모와 분자를 따로 견주거나 분모와 분자의 차로 크기를 판단한다(분자가 크면 큰 분수, 차가 같으면 같은 분수)','통분하여 같은 조각으로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X10','math',5,'u3',ARRAY['M5-1-u3-C5','M5-1-u3-C7']::text[],'⟨1/2⟩을 기준으로 잘못 가른다 — 분자가 분모의 절반보다 큰지 판단을 잘못하거나, 같은 쪽에 있는 두 분수를 기준만으로 가리려 한다','분자 × 2와 분모를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X11','math',5,'u3',ARRAY['M5-1-u3-C5','M5-1-u3-C7']::text[],'단위분수·분자가 같은 분수에서 분모가 클수록 크다고 여긴다(⟨1/8⟩ > ⟨1/5⟩)','분모가 클수록 조각은 작다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X12','math',5,'u3',ARRAY['M5-1-u3-C6']::text[],'분수와 소수를 바꿀 때 분자·분모를 그대로 소수점 뒤에 붙이거나(⟨3/5⟩ = 0.35), 소수점 아래 자리 수와 분모 10·100을 맞추지 못한다(0.25를 ⟨25/10⟩)','분모를 10·100으로 만들기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X13','math',5,'u3',ARRAY['M5-1-u3-C1','M5-1-u3-C2','M5-1-u3-C3','M5-1-u3-C4','M5-1-u3-C5','M5-1-u3-C6','M5-1-u3-C7']::text[],'한 걸음의 셈(곱셈·나눗셈·통분한 분자)을 잘못하거나 곱할 수를 뒤바꾼다','곱한 수를 다시 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u3-X14','math',5,'u3',ARRAY['M5-1-u3-C1','M5-1-u3-C2','M5-1-u3-C3','M5-1-u3-C4','M5-1-u3-C5','M5-1-u3-C6','M5-1-u3-C7']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 잘못↔바르게, 큰 것부터↔작은 것부터, 가장 큰↔가장 작은','물음의 「아닌·잘못·차례·가장」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#1','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C1',1,'mc','auto','같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":1,"concept":"M5-1-u3-C1","difficulty":1,"kind":"mc","stem":"같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/3⟩ = ⟨2/6⟩","correct":true},{"t":"⟨1/3⟩ < ⟨2/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨1/3⟩ > ⟨2/6⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 3칸 중 1칸, 아래 띠는 6칸 중 2칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨1/3⟩ = ⟨2/6⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"⟨1/3⟩"},{"den":6,"num":2,"label":"⟨2/6⟩"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/2⟩ = ⟨3/6⟩","correct":true},{"t":"⟨1/2⟩ < ⟨3/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨1/2⟩ > ⟨3/6⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 2칸 중 1칸, 아래 띠는 6칸 중 3칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 3배로 잘게 나누었을 뿐이에요.","그래서 ⟨1/2⟩ = ⟨3/6⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"label":"⟨1/2⟩"},{"den":6,"num":3,"label":"⟨3/6⟩"}]}},{"stem":"이번에는 다른 보기예요. 같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ = ⟨6/8⟩","correct":true},{"t":"⟨3/4⟩ < ⟨6/8⟩","mis":"M5-1-u3-X04"},{"t":"⟨3/4⟩ > ⟨6/8⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 4칸 중 3칸, 아래 띠는 8칸 중 6칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨3/4⟩ = ⟨6/8⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"⟨3/4⟩"},{"den":8,"num":6,"label":"⟨6/8⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#2','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',1,'sa','auto','⟨1/3⟩ = ⟨□/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C2","difficulty":1,"kind":"sa","stem":"⟨1/3⟩ = ⟨□/6⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 3에 2를 곱해 6이 되었어요 — 3 × 2 = 6.","분자에도 같은 수 2를 곱해요 — 1 × 2 = 2.","⟨1/3⟩ = ⟨2/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ = ⟨□/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 4에 3을 곱해 12가 되었어요 — 4 × 3 = 12.","분자에도 같은 수 3을 곱해요 — 1 × 3 = 3.","⟨1/4⟩ = ⟨3/12⟩이에요."]},{"stem":"⟨2/5⟩ = ⟨□/15⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 5에 3을 곱해 15가 되었어요 — 5 × 3 = 15.","분자에도 같은 수 3을 곱해요 — 2 × 3 = 6.","⟨2/5⟩ = ⟨6/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#3','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',1,'mc','auto','⟨2/3⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],true,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨2/3⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨6/9⟩","correct":true},{"t":"⟨5/6⟩","mis":"M5-1-u3-X01"},{"t":"⟨6/3⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/9⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 3 × 3 = 9, 분자 2 × 3 = 6이에요.","⟨2/3⟩ = ⟨6/9⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨3/12⟩","correct":true},{"t":"⟨4/7⟩","mis":"M5-1-u3-X01"},{"t":"⟨3/4⟩","mis":"M5-1-u3-X02"},{"t":"⟨1/12⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 4 × 3 = 12, 분자 1 × 3 = 3이에요.","⟨1/4⟩ = ⟨3/12⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."]},{"stem":"⟨3/5⟩의 분모와 분자에 각각 2를 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨6/10⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u3-X01"},{"t":"⟨6/5⟩","mis":"M5-1-u3-X02"},{"t":"⟨3/10⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 5 × 2 = 10, 분자 3 × 2 = 6이에요.","⟨3/5⟩ = ⟨6/10⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#4','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',1,'mc','auto','⟨8/12⟩의 분모와 분자를 각각 4로 나누면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],true,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨8/12⟩의 분모와 분자를 각각 4로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨4/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨8/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 12 ÷ 4 = 3, 분자 8 ÷ 4 = 2예요.","⟨8/12⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."],"variant_rule":{"alt":[{"stem":"⟨6/9⟩의 분모와 분자를 각각 3으로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/6⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/9⟩","mis":"M5-1-u3-X02"},{"t":"⟨6/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 9 ÷ 3 = 3, 분자 6 ÷ 3 = 2예요.","⟨6/9⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."]},{"stem":"⟨10/15⟩의 분모와 분자를 각각 5로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨5/10⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/15⟩","mis":"M5-1-u3-X02"},{"t":"⟨10/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 15 ÷ 5 = 3, 분자 10 ÷ 5 = 2예요.","⟨10/15⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#5','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'ox','auto','⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩는 ⟨2/3⟩와 크기가 같아요.',ARRAY['M5-1-u3-X01']::text[],true,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":2,"kind":"ox","stem":"⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩는 ⟨2/3⟩와 크기가 같아요.","answer":"X","reason_options":[{"t":"⟨2/3⟩ = ⟨4/6⟩라 ⟨5/6⟩과는 색칠한 칸 수가 달라지므로","correct":true},{"t":"분모와 분자에 똑같이 3을 더했으니 크기가 같으므로","mis":"M5-1-u3-X01"}],"mis":"M5-1-u3-X01","explanation":["⟨2/3⟩를 6칸으로 나누면 ⟨4/6⟩ — 색칠한 칸이 4칸이에요.","⟨5/6⟩는 5칸을 색칠해 양이 더 많아요.","크기가 같은 분수는 곱하기·나누기로만 만들어요. 더하기로는 안 돼요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩의 분모와 분자에 각각 2를 곱한 ⟨6/8⟩은 ⟨3/4⟩과 크기가 같아요.","answer":"O","reason_options":[{"t":"분모와 분자에 0이 아닌 같은 수를 곱했으므로","correct":true},{"t":"분모와 분자가 커졌으니 더 큰 분수이므로","mis":"M5-1-u3-X04"}],"explanation":["분모 4 × 2 = 8, 분자 3 × 2 = 6이에요.","칸을 2배로 잘게 나누면 색칠한 칸도 2배가 돼요.","⟨3/4⟩ = ⟨6/8⟩ — 크기는 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#6','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'mc','auto','크기가 같은 분수를 만들 때 분모와 분자에 곱할 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X03']::text[],true,'{"seq":6,"concept":"M5-1-u3-C2","difficulty":2,"kind":"mc","stem":"크기가 같은 분수를 만들 때 분모와 분자에 곱할 수 없는 수는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M5-1-u3-X03"},{"t":"5","mis":"M5-1-u3-X03"},{"t":"10","mis":"M5-1-u3-X03"}],"explanation":["0을 곱하면 분모도 분자도 0이 되어 분수가 되지 않아요.","1을 곱하면 처음 분수 그대로이고, 5나 10을 곱하면 크기가 같은 분수가 돼요.","그래서 「0이 아닌 같은 수」라는 말이 꼭 붙어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 분수를 만드는 방법으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"분모와 분자에 각각 0을 곱한다","correct":true},{"t":"분모와 분자에 같은 수를 곱한다","mis":"M5-1-u3-X14"},{"t":"분모와 분자를 같은 수로 나눈다","mis":"M5-1-u3-X14"},{"t":"분모와 분자를 공약수로 나눈다","mis":"M5-1-u3-X14"}],"explanation":["0을 곱하면 분모가 0이 되어 분수가 되지 않아요.","0이 아닌 같은 수를 곱하거나 같은 수로 나누면 크기가 같은 분수가 돼요.","그래서 옳지 않은 것은 「0을 곱한다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#7','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'sa','auto','⟨3/7⟩과 크기가 같고 분모가 49인 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C2","difficulty":2,"kind":"sa","stem":"⟨3/7⟩과 크기가 같고 분모가 49인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["분모 7을 49로 만들려면 7을 곱해요 — 7 × 7 = 49.","분자에도 7을 곱해요 — 3 × 7 = 21.","⟨3/7⟩ = ⟨21/49⟩ — 분자는 21이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같고 분모가 12인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모 4를 12로 만들려면 3을 곱해요 — 4 × 3 = 12.","분자에도 3을 곱해요 — 3 × 3 = 9.","⟨3/4⟩ = ⟨9/12⟩ — 분자는 9예요."]},{"stem":"⟨5/6⟩와 크기가 같고 분모가 36인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["분모 6을 36으로 만들려면 6을 곱해요 — 6 × 6 = 36.","분자에도 6을 곱해요 — 5 × 6 = 30.","⟨5/6⟩ = ⟨30/36⟩ — 분자는 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#8','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C1',2,'mc','auto','⟨4/6⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":8,"concept":"M5-1-u3-C1","difficulty":2,"kind":"mc","stem":"⟨4/6⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"},{"t":"⟨8/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨12/18⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨4/6⟩ = ⟨2/3⟩ = ⟨8/12⟩ = ⟨12/18⟩예요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨3/5⟩은 ⟨4/6⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨3/5⟩ ≠ ⟨4/6⟩ — 크기가 같은 분수가 아닌 것은 ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨6/8⟩","mis":"M5-1-u3-X04"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨15/20⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨3/4⟩ = ⟨6/8⟩ = ⟨9/12⟩ = ⟨15/20⟩예요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨4/5⟩는 ⟨3/4⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨4/5⟩ ≠ ⟨3/4⟩ — 크기가 같은 분수가 아닌 것은 ⟨4/5⟩예요."]},{"stem":"⟨2/5⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/6⟩","correct":true},{"t":"⟨4/10⟩","mis":"M5-1-u3-X04"},{"t":"⟨6/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨8/20⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨2/5⟩ = ⟨4/10⟩ = ⟨6/15⟩ = ⟨8/20⟩이에요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨3/6⟩은 ⟨2/5⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨3/6⟩ ≠ ⟨2/5⟩ — 크기가 같은 분수가 아닌 것은 ⟨3/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#9','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C2',2,'mc','auto','어떤 분수의 분모와 분자에 각각 5를 곱했더니 ⟨15/20⟩가 되었어요. 처음 분수는 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X01','M5-1-u3-X02']::text[],true,'{"seq":9,"concept":"M5-1-u3-C2","difficulty":2,"kind":"mc","stem":"어떤 분수의 분모와 분자에 각각 5를 곱했더니 ⟨15/20⟩가 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨75/100⟩","mis":"M5-1-u3-X14"},{"t":"⟨10/15⟩","mis":"M5-1-u3-X01"},{"t":"⟨3/20⟩","mis":"M5-1-u3-X02"}],"explanation":["곱한 것을 되돌리려면 같은 수로 나누어요.","분모 20 ÷ 5 = 4, 분자 15 ÷ 5 = 3이에요.","처음 분수는 ⟨3/4⟩이고 ⟨3/4⟩ = ⟨15/20⟩예요."],"variant_rule":{"alt":[{"stem":"어떤 분수의 분모와 분자에 각각 4를 곱했더니 ⟨8/12⟩이 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨32/48⟩","mis":"M5-1-u3-X14"},{"t":"⟨4/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/12⟩","mis":"M5-1-u3-X02"}],"explanation":["곱한 것을 되돌리려면 같은 수로 나누어요.","분모 12 ÷ 4 = 3, 분자 8 ÷ 4 = 2예요.","처음 분수는 ⟨2/3⟩이고 ⟨2/3⟩ = ⟨8/12⟩이에요."]},{"stem":"어떤 분수의 분모와 분자에 각각 3을 곱했더니 ⟨12/15⟩가 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨36/45⟩","mis":"M5-1-u3-X14"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X01"},{"t":"⟨4/15⟩","mis":"M5-1-u3-X02"}],"explanation":["곱한 것을 되돌리려면 같은 수로 나누어요.","분모 15 ÷ 3 = 5, 분자 12 ÷ 3 = 4예요.","처음 분수는 ⟨4/5⟩이고 ⟨4/5⟩ = ⟨12/15⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_basic#10','math',5,1,'u3','L02','g5_1_math_u3_L02_basic','lesson_basic','M5-1-u3-C1',3,'mc','auto','수직선에서 ⟨1/3⟩과 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02','M5-1-u3-X13']::text[],true,'{"seq":10,"concept":"M5-1-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 ⟨1/3⟩과 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨2/6⟩, ⟨3/9⟩, ⟨4/12⟩","correct":true},{"t":"⟨2/4⟩, ⟨3/5⟩, ⟨4/6⟩","mis":"M5-1-u3-X01"},{"t":"⟨1/6⟩, ⟨1/9⟩, ⟨1/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/6⟩, ⟨3/9⟩, ⟨4/9⟩","mis":"M5-1-u3-X13"}],"explanation":["분모와 분자에 2, 3, 4를 차례로 곱해요.","⟨1/3⟩ = ⟨2/6⟩ = ⟨3/9⟩ = ⟨4/12⟩예요.","모두 수직선의 같은 자리를 가리켜요."],"variant_rule":{"alt":[{"stem":"수직선에서 ⟨1/4⟩과 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨2/8⟩, ⟨3/12⟩, ⟨4/16⟩","correct":true},{"t":"⟨2/5⟩, ⟨3/6⟩, ⟨4/7⟩","mis":"M5-1-u3-X01"},{"t":"⟨1/8⟩, ⟨1/12⟩, ⟨1/16⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/8⟩, ⟨3/12⟩, ⟨4/12⟩","mis":"M5-1-u3-X13"}],"explanation":["분모와 분자에 2, 3, 4를 차례로 곱해요.","⟨1/4⟩ = ⟨2/8⟩ = ⟨3/12⟩ = ⟨4/16⟩예요.","모두 수직선의 같은 자리를 가리켜요."]},{"stem":"수직선에서 ⟨2/5⟩와 같은 자리를 가리키는 분수를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨4/10⟩, ⟨6/15⟩, ⟨8/20⟩","correct":true},{"t":"⟨3/6⟩, ⟨4/7⟩, ⟨5/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/10⟩, ⟨2/15⟩, ⟨2/20⟩","mis":"M5-1-u3-X02"},{"t":"⟨4/10⟩, ⟨6/15⟩, ⟨8/15⟩","mis":"M5-1-u3-X13"}],"explanation":["분모와 분자에 2, 3, 4를 차례로 곱해요.","⟨2/5⟩ = ⟨4/10⟩ = ⟨6/15⟩ = ⟨8/20⟩이에요.","모두 수직선의 같은 자리를 가리켜요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#1','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',2,'error','auto','⟨2/3⟩와 크기가 같은 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X01','M5-1-u3-X14']::text[],true,'{"seq":1,"concept":"M5-1-u3-C2","difficulty":2,"kind":"error","stem":"⟨2/3⟩와 크기가 같은 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「분모와 분자에 3을 더하면 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-1-u3-X01"},{"t":"도현 — 「분모와 분자에 2를 곱하면 ⟨4/6⟩야.」","mis":"M5-1-u3-X14"},{"t":"하은 — 「⟨8/12⟩의 분모와 분자를 4로 나누면 ⟨2/3⟩가 돼.」","mis":"M5-1-u3-X14"}],"explanation":["⟨2/3⟩ = ⟨4/6⟩이고, ⟨8/12⟩을 4로 나누면 ⟨2/3⟩예요 — 둘은 맞아요.","⟨5/6⟩는 ⟨2/3⟩와 크기가 달라요.","서윤은 더하기로 만들어 잘못 말했어요. 크기가 같은 분수는 곱하기·나누기로만 만들어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같은 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「분모와 분자에 2를 더하면 ⟨5/6⟩야.」","correct":true,"mis_target":"M5-1-u3-X01"},{"t":"라온 — 「분모와 분자에 2를 곱하면 ⟨6/8⟩이야.」","mis":"M5-1-u3-X14"},{"t":"예준 — 「⟨12/16⟩의 분모와 분자를 4로 나누면 ⟨3/4⟩이 돼.」","mis":"M5-1-u3-X14"}],"explanation":["⟨3/4⟩ = ⟨6/8⟩이고, ⟨12/16⟩를 4로 나누면 ⟨3/4⟩이에요 — 둘은 맞아요.","⟨5/6⟩는 ⟨3/4⟩과 크기가 달라요.","지민은 더하기로 만들어 잘못 말했어요. 크기가 같은 분수는 곱하기·나누기로만 만들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#2','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',2,'sa','auto','⟨9/15⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C2","difficulty":2,"kind":"sa","stem":"⟨9/15⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 작게 하려면 분모와 분자를 같은 수로 나누어요.","9와 15의 최대공약수 3으로 나누면 9 ÷ 3 = 3, 15 ÷ 3 = 5예요.","⟨9/15⟩ = ⟨3/5⟩ — 더 나눌 수 없으니 분모는 5예요."],"variant_rule":{"alt":[{"stem":"⟨12/16⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모를 작게 하려면 분모와 분자를 같은 수로 나누어요.","12와 16의 최대공약수 4로 나누면 12 ÷ 4 = 3, 16 ÷ 4 = 4예요.","⟨12/16⟩ = ⟨3/4⟩ — 더 나눌 수 없으니 분모는 4예요."]},{"stem":"⟨14/35⟩와 크기가 같은 분수 중 분모가 가장 작은 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모를 작게 하려면 분모와 분자를 같은 수로 나누어요.","14와 35의 최대공약수 7로 나누면 14 ÷ 7 = 2, 35 ÷ 7 = 5예요.","⟨14/35⟩ = ⟨2/5⟩ — 더 나눌 수 없으니 분모는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#3','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'sa','auto','⟨2/5⟩와 크기가 같은 분수 중 분모가 10보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨2/5⟩와 크기가 같은 분수 중 분모가 10보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["⟨2/5⟩와 크기가 같은 분수의 분모는 5의 배수예요.","10보다 크고 30보다 작은 5의 배수는 15, 20, 25예요.","⟨6/15⟩, ⟨8/20⟩, ⟨10/25⟩ — 모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 크기가 같은 분수 중 분모가 10보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["⟨3/4⟩과 크기가 같은 분수의 분모는 4의 배수예요.","10보다 크고 30보다 작은 4의 배수는 12, 16, 20, 24, 28이에요.","⟨9/12⟩, ⟨12/16⟩, ⟨15/20⟩, ⟨18/24⟩, ⟨21/28⟩ — 모두 5개예요."]},{"stem":"⟨1/6⟩과 크기가 같은 분수 중 분모가 10보다 크고 40보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["⟨1/6⟩과 크기가 같은 분수의 분모는 6의 배수예요.","10보다 크고 40보다 작은 6의 배수는 12, 18, 24, 30, 36이에요.","⟨2/12⟩, ⟨3/18⟩, ⟨4/24⟩, ⟨5/30⟩, ⟨6/36⟩ — 모두 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#4','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'sa','auto','⟨3/8⟩과 크기가 같은 분수 중 분모와 분자의 합이 44인 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨3/8⟩과 크기가 같은 분수 중 분모와 분자의 합이 44인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨3/8⟩의 분모와 분자의 합은 3 + 8 = 11이에요.","분모와 분자에 같은 수를 곱하면 합도 그만큼 커져요 — 44 ÷ 11 = 4배.","분자는 3 × 4 = 12 — ⟨12/32⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩와 크기가 같은 분수 중 분모와 분자의 합이 35인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["⟨2/5⟩의 분모와 분자의 합은 2 + 5 = 7이에요.","분모와 분자에 같은 수를 곱하면 합도 그만큼 커져요 — 35 ÷ 7 = 5배.","분자는 2 × 5 = 10 — ⟨10/25⟩이에요."]},{"stem":"⟨4/7⟩와 크기가 같은 분수 중 분모와 분자의 합이 55인 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["⟨4/7⟩의 분모와 분자의 합은 4 + 7 = 11이에요.","분모와 분자에 같은 수를 곱하면 합도 그만큼 커져요 — 55 ÷ 11 = 5배.","분자는 4 × 5 = 20 — ⟨20/35⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#5','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'mc','auto','⟨12/18⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":3,"kind":"mc","stem":"⟨12/18⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨6/9⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"}],"explanation":["12와 18을 함께 나누는 수는 공약수 2, 3, 6이에요.","⟨6/9⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 ⟨12/18⟩와 크기가 같아요.","⟨3/4⟩은 ⟨12/18⟩와 크기가 달라 만들 수 없어요."],"variant_rule":{"alt":[{"stem":"⟨16/24⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨4/8⟩","correct":true},{"t":"⟨8/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"}],"explanation":["16과 24를 함께 나누는 수는 공약수 2, 4, 8이에요.","⟨8/12⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 ⟨16/24⟩과 크기가 같아요.","⟨4/8⟩는 ⟨16/24⟩과 크기가 달라 만들 수 없어요."]},{"stem":"⟨20/30⟩의 분모와 분자를 같은 수로 나누어 만들 수 있는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩","mis":"M5-1-u3-X04"}],"explanation":["20과 30을 함께 나누는 수는 공약수 2, 5, 10이에요.","⟨10/15⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 ⟨20/30⟩과 크기가 같아요.","⟨5/6⟩는 ⟨20/30⟩과 크기가 달라 만들 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#6','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C1',3,'ox','auto','⟨1/3⟩의 한 칸을 2등분 하면 ⟨2/6⟩가 돼요. 칸이 잘아졌으니 색칠한 양은 줄었어요.',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":6,"concept":"M5-1-u3-C1","difficulty":3,"kind":"ox","stem":"⟨1/3⟩의 한 칸을 2등분 하면 ⟨2/6⟩가 돼요. 칸이 잘아졌으니 색칠한 양은 줄었어요.","answer":"X","reason_options":[{"t":"조각이 2배 작아진 만큼 조각 개수가 2배 많아져 양은 그대로이므로","correct":true},{"t":"분모가 커지면 분수는 작아지므로","mis":"M5-1-u3-X04"}],"mis":"M5-1-u3-X04","explanation":["한 칸을 2등분 하면 칸은 6개, 색칠한 칸은 2개가 돼요.","작아진 만큼 많아지니 전체 양은 그대로예요.","⟨1/3⟩ = ⟨2/6⟩ — 이름만 바뀌었어요."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩의 칸을 2개씩 묶으면 ⟨2/4⟩가 되고, 색칠한 양은 변하지 않아요.","answer":"O","reason_options":[{"t":"조각이 2배 커진 만큼 조각 개수가 절반이 되어 양은 그대로이므로","correct":true},{"t":"분모와 분자가 작아지면 분수도 작아지므로","mis":"M5-1-u3-X04"}],"explanation":["8칸을 2개씩 묶으면 4칸, 색칠한 4칸은 2칸이 돼요.","분모와 분자를 똑같이 2로 나눈 셈이에요.","⟨4/8⟩ = ⟨2/4⟩ — 양은 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#7','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',3,'match','auto','크기가 같은 분수끼리 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C2","difficulty":3,"kind":"match","stem":"크기가 같은 분수끼리 이으세요.","pairs":[{"l":"⟨1/2⟩","r":"⟨5/10⟩"},{"l":"⟨2/3⟩","r":"⟨8/12⟩"},{"l":"⟨3/4⟩","r":"⟨9/12⟩"}],"mis":"M5-1-u3-X13","explanation":["⟨1/2⟩의 분모와 분자에 5를 곱하면 ⟨5/10⟩예요.","⟨2/3⟩ = ⟨8/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요 — 둘 다 분모가 12라 헷갈리기 쉬워요.","분모에 곱한 수만큼 분자에도 곱했는지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 크기가 같은 분수끼리 이으세요.","pairs":[{"l":"⟨1/3⟩","r":"⟨4/12⟩"},{"l":"⟨2/5⟩","r":"⟨6/15⟩"},{"l":"⟨3/5⟩","r":"⟨9/15⟩"}],"explanation":["⟨1/3⟩ = ⟨4/12⟩ — 분모와 분자에 4를 곱했어요.","⟨2/5⟩ = ⟨6/15⟩, ⟨3/5⟩ = ⟨9/15⟩ — 분모와 분자에 3을 곱했어요.","분모가 15로 같아도 분자가 다르면 다른 분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#8','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',4,'sa','auto','⟨□/24⟩ = ⟨3/8⟩ = ⟨15/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u3-C2","difficulty":4,"kind":"sa","stem":"⟨□/24⟩ = ⟨3/8⟩ = ⟨15/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["분모 24는 8 × 3 — □ = 3 × 3 = 9예요.","분자 15는 3 × 5 — ○ = 8 × 5 = 40이에요.","□ + ○ = 9 + 40 = 49예요."],"variant_rule":{"alt":[{"stem":"⟨□/20⟩ = ⟨2/5⟩ = ⟨14/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["분모 20은 5 × 4 — □ = 2 × 4 = 8이에요.","분자 14는 2 × 7 — ○ = 5 × 7 = 35예요.","□ + ○ = 8 + 35 = 43이에요."]},{"stem":"⟨□/18⟩ = ⟨5/6⟩ = ⟨20/○⟩에서 □와 ○에 알맞은 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["분모 18은 6 × 3 — □ = 5 × 3 = 15예요.","분자 20은 5 × 4 — ○ = 6 × 4 = 24예요.","□ + ○ = 15 + 24 = 39예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#9','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C1',4,'essay','teacher','⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩가 ⟨2/3⟩와 크기가 같지 않은 까닭을 띠 그림으로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C1","difficulty":4,"kind":"essay","stem":"⟨2/3⟩의 분모와 분자에 각각 3을 더한 ⟨5/6⟩가 ⟨2/3⟩와 크기가 같지 않은 까닭을 띠 그림으로 설명하세요.","answer_guide":{"answer":"예: ⟨2/3⟩를 6칸으로 나누면 ⟨4/6⟩로 6칸 중 4칸을 색칠한 것과 같다. ⟨5/6⟩는 6칸 중 5칸이라 색칠한 양이 더 많다. 그래서 두 분수는 크기가 다르고, 크기가 같은 분수는 더하기가 아니라 곱하기·나누기로 만들어야 한다.","scoring_points":["⟨2/3⟩ = ⟨4/6⟩임을 띠로 나타냈는가","⟨5/6⟩는 색칠한 칸이 하나 더 많음을 썼는가","더하기로는 크기가 같은 분수를 만들 수 없다고 맺었는가"]},"explanation":["⟨2/3⟩ = ⟨4/6⟩예요.","⟨5/6⟩는 6칸 중 5칸 — 4칸보다 많아요.","잘게 나누는 일은 곱셈이지 덧셈이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L02_challenge#10','math',5,1,'u3','L02','g5_1_math_u3_L02_challenge','lesson_challenge','M5-1-u3-C2',4,'essay','teacher','크기가 같은 분수를 만들 때 「0이 아닌 같은 수」를 곱하거나 나누어야 하는 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C2","difficulty":4,"kind":"essay","stem":"크기가 같은 분수를 만들 때 「0이 아닌 같은 수」를 곱하거나 나누어야 하는 까닭을 설명하세요.","answer_guide":{"answer":"예: 분모와 분자에 0을 곱하면 분모가 0이 되어 분수가 되지 않고, 0으로 나누는 것은 할 수 없다. 분모와 분자 중 한쪽에만 곱하거나 나누면 조각의 크기와 개수가 맞물려 바뀌지 않아 양이 달라진다. 그래서 0이 아닌 같은 수를 분모와 분자에 함께 써야 한다.","scoring_points":["0을 곱하거나 0으로 나눌 수 없는 까닭을 썼는가","분모와 분자에 「같은 수」를 써야 하는 까닭을 썼는가","조각의 크기와 개수가 함께 바뀌어 양이 지켜진다고 썼는가"]},"explanation":["0을 곱하면 분모가 0 — 분수가 되지 않아요.","한쪽에만 곱하면 조각 크기와 개수가 따로 바뀌어요.","0이 아닌 같은 수를 함께 써야 양이 지켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#1','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'mc','auto','⟨18/24⟩을 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X06']::text[],true,'{"seq":1,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨18/24⟩을 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"2","mis":"M5-1-u3-X06"},{"t":"3","mis":"M5-1-u3-X06"},{"t":"6","mis":"M5-1-u3-X06"}],"explanation":["18과 24의 공약수는 1, 2, 3, 6이에요.","약분은 1이 아닌 공약수 2, 3, 6으로 나누는 거예요.","4는 24의 약수이지만 18의 약수는 아니에요 — 그래서 4로는 약분할 수 없어요."],"variant_rule":{"alt":[{"stem":"⟨12/30⟩를 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?","options":[{"t":"5","correct":true},{"t":"2","mis":"M5-1-u3-X06"},{"t":"3","mis":"M5-1-u3-X06"},{"t":"6","mis":"M5-1-u3-X06"}],"explanation":["12와 30의 공약수는 1, 2, 3, 6이에요.","약분은 1이 아닌 공약수 2, 3, 6으로 나누는 거예요.","5는 30의 약수이지만 12의 약수는 아니에요 — 그래서 5로는 약분할 수 없어요."]},{"stem":"⟨20/30⟩을 약분할 때 분모와 분자를 나눌 수 있는 수가 아닌 것은 어느 것인가요?","options":[{"t":"3","correct":true},{"t":"2","mis":"M5-1-u3-X06"},{"t":"5","mis":"M5-1-u3-X06"},{"t":"10","mis":"M5-1-u3-X06"}],"explanation":["20과 30의 공약수는 1, 2, 5, 10이에요.","약분은 1이 아닌 공약수 2, 5, 10으로 나누는 거예요.","3은 30의 약수이지만 20의 약수는 아니에요 — 그래서 3로는 약분할 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#2','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'sa','auto','⟨12/16⟩를 4로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C3","difficulty":1,"kind":"sa","stem":"⟨12/16⟩를 4로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모와 분자를 같은 수 4로 나누어요.","분자 12 ÷ 4 = 3, 분모 16 ÷ 4 = 4예요.","⟨12/16⟩ = ⟨3/4⟩ — 분자는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨14/21⟩를 7로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모와 분자를 같은 수 7로 나누어요.","분자 14 ÷ 7 = 2, 분모 21 ÷ 7 = 3이에요.","⟨14/21⟩ = ⟨2/3⟩ — 분자는 2예요."]},{"stem":"⟨24/30⟩를 6으로 약분하면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모와 분자를 같은 수 6으로 나누어요.","분자 24 ÷ 6 = 4, 분모 30 ÷ 6 = 5예요.","⟨24/30⟩ = ⟨4/5⟩ — 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#3','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'mc','auto','⟨24/36⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],true,'{"seq":3,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨24/36⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨12/18⟩","mis":"M5-1-u3-X05"},{"t":"⟨8/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"}],"explanation":["24와 36의 공약수는 1, 2, 3, 4, 6, 12, 최대공약수는 12예요.","최대공약수로 나누면 한 번에 끝나요 — 24 ÷ 12 = 2, 36 ÷ 12 = 3.","⟨24/36⟩ = ⟨2/3⟩ — 공약수가 1뿐이라 기약분수예요."],"variant_rule":{"alt":[{"stem":"⟨30/45⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/45⟩","mis":"M5-1-u3-X02"}],"explanation":["30과 45의 공약수는 1, 3, 5, 15, 최대공약수는 15예요.","최대공약수로 나누면 한 번에 끝나요 — 30 ÷ 15 = 2, 45 ÷ 15 = 3.","⟨30/45⟩ = ⟨2/3⟩ — 공약수가 1뿐이라 기약분수예요."]},{"stem":"⟨16/40⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨8/20⟩","mis":"M5-1-u3-X05"},{"t":"⟨4/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/40⟩","mis":"M5-1-u3-X02"}],"explanation":["16과 40의 공약수는 1, 2, 4, 8, 최대공약수는 8이에요.","최대공약수로 나누면 한 번에 끝나요 — 16 ÷ 8 = 2, 40 ÷ 8 = 5.","⟨16/40⟩ = ⟨2/5⟩ — 공약수가 1뿐이라 기약분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#4','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',1,'mc','auto','기약분수인 것은 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],true,'{"seq":4,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"기약분수인 것은 어느 것인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨6/8⟩","mis":"M5-1-u3-X05"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨10/15⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨6/8⟩은 2로 약분돼요 · ⟨9/12⟩는 3으로 약분돼요 · ⟨10/15⟩은 5로 약분돼요.","7과 9의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨7/9⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 기약분수인 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨4/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"},{"t":"⟨14/21⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨4/10⟩는 2로 약분돼요 · ⟨6/9⟩은 3으로 약분돼요 · ⟨14/21⟩는 7로 약분돼요.","5와 8의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨5/8⟩예요."]},{"stem":"이번에는 다른 보기예요. 기약분수인 것은 어느 것인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨9/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨8/14⟩","mis":"M5-1-u3-X05"},{"t":"⟨12/20⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨9/15⟩는 3으로 약분돼요 · ⟨8/14⟩은 2로 약분돼요 · ⟨12/20⟩는 4로 약분돼요.","8과 15의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨8/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#5','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'sa','auto','⟨35/56⟩를 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u3-C3","difficulty":2,"kind":"sa","stem":"⟨35/56⟩를 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["35와 56의 최대공약수는 7이에요.","35 ÷ 7 = 5, 56 ÷ 7 = 8이에요.","⟨35/56⟩ = ⟨5/8⟩ — 분자는 5예요."],"variant_rule":{"alt":[{"stem":"⟨28/42⟩을 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["28과 42의 최대공약수는 14예요.","28 ÷ 14 = 2, 42 ÷ 14 = 3이에요.","⟨28/42⟩ = ⟨2/3⟩ — 분자는 2예요."]},{"stem":"⟨45/60⟩를 기약분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["45와 60의 최대공약수는 15예요.","45 ÷ 15 = 3, 60 ÷ 15 = 4예요.","⟨45/60⟩ = ⟨3/4⟩ — 분자는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#6','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'error','auto','⟨9/12⟩를 약분한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X02','M5-1-u3-X14']::text[],true,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":2,"kind":"error","stem":"⟨9/12⟩를 약분한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「분자만 3으로 나누어 ⟨3/12⟩이야.」","correct":true,"mis_target":"M5-1-u3-X02"},{"t":"수아 — 「9 ÷ 3 = 3, 12 ÷ 3 = 4 — ⟨3/4⟩이야.」","mis":"M5-1-u3-X14"},{"t":"민재 — 「공약수 3으로 분모와 분자를 함께 나누었으니 약분이야.」","mis":"M5-1-u3-X14"}],"explanation":["약분은 분모와 분자를 같은 공약수로 함께 나누는 거예요.","⟨9/12⟩ = ⟨3/4⟩ — 바르게 약분했어요.","지호의 말처럼 분자만 나누면 조각 개수만 줄어 양이 작아져요."],"variant_rule":{"alt":[{"stem":"⟨10/15⟩을 약분한 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「분자만 5로 나누어 ⟨2/15⟩야.」","correct":true,"mis_target":"M5-1-u3-X02"},{"t":"세빈 — 「10 ÷ 5 = 2, 15 ÷ 5 = 3 — ⟨2/3⟩야.」","mis":"M5-1-u3-X14"},{"t":"도율 — 「공약수 5로 분모와 분자를 함께 나누었으니 약분이야.」","mis":"M5-1-u3-X14"}],"explanation":["약분은 분모와 분자를 같은 공약수로 함께 나누는 거예요.","⟨10/15⟩ = ⟨2/3⟩ — 바르게 약분했어요.","하랑의 말처럼 분자만 나누면 조각 개수만 줄어 양이 작아져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#7','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'sa','auto','분모가 56인 분수를 약분했더니 ⟨4/7⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":2,"kind":"sa","stem":"분모가 56인 분수를 약분했더니 ⟨4/7⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 7을 56으로 만들려면 7 × 8 = 56 — 8을 곱해요.","분자도 4 × 8 = 32 — 처음 분수는 ⟨32/56⟩예요."],"variant_rule":{"alt":[{"stem":"분모가 42인 분수를 약분했더니 ⟨5/6⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 6을 42로 만들려면 6 × 7 = 42 — 7을 곱해요.","분자도 5 × 7 = 35 — 처음 분수는 ⟨35/42⟩예요."]},{"stem":"분모가 45인 분수를 약분했더니 ⟨2/9⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 9를 45로 만들려면 9 × 5 = 45 — 5를 곱해요.","분자도 2 × 5 = 10 — 처음 분수는 ⟨10/45⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#8','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'mc','auto','하루 24시간 중 3시간을 분수로 나타내고 기약분수로 고치면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02','M5-1-u3-X13']::text[],true,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"하루 24시간 중 3시간을 분수로 나타내고 기약분수로 고치면 어느 것인가요?","options":[{"t":"⟨1/8⟩","correct":true},{"t":"⟨3/24⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/24⟩","mis":"M5-1-u3-X02"},{"t":"⟨8/24⟩","mis":"M5-1-u3-X13"}],"explanation":["24시간 중 3시간은 ⟨3/24⟩이에요.","3과 24의 최대공약수 3으로 약분해요 — 3 ÷ 3 = 1, 24 ÷ 3 = 8.","⟨3/24⟩ = ⟨1/8⟩이에요."],"variant_rule":{"alt":[{"stem":"한 시간 60분 중 15분을 분수로 나타내고 기약분수로 고치면 어느 것인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨15/60⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/60⟩","mis":"M5-1-u3-X02"},{"t":"⟨4/60⟩","mis":"M5-1-u3-X13"}],"explanation":["60분 중 15분은 ⟨15/60⟩예요.","15와 60의 최대공약수 15로 약분해요 — 15 ÷ 15 = 1, 60 ÷ 15 = 4.","⟨15/60⟩ = ⟨1/4⟩이에요."]},{"stem":"1년 12달 중 4달을 분수로 나타내고 기약분수로 고치면 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨4/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨3/12⟩","mis":"M5-1-u3-X13"}],"explanation":["12달 중 4달은 ⟨4/12⟩예요.","4와 12의 최대공약수 4로 약분해요 — 4 ÷ 4 = 1, 12 ÷ 4 = 3.","⟨4/12⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#9','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',2,'ox','auto','⟨18/24⟩을 2로 약분한 ⟨9/12⟩는 기약분수예요.',ARRAY['M5-1-u3-X05']::text[],true,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":2,"kind":"ox","stem":"⟨18/24⟩을 2로 약분한 ⟨9/12⟩는 기약분수예요.","answer":"X","reason_options":[{"t":"9와 12의 공약수에 3이 남아 있어 더 약분할 수 있으므로","correct":true},{"t":"한 번 약분했으니 기약분수이므로","mis":"M5-1-u3-X05"}],"mis":"M5-1-u3-X05","explanation":["9와 12의 공약수는 1, 3이에요.","3으로 한 번 더 약분하면 ⟨9/12⟩ = ⟨3/4⟩이에요.","공약수가 1뿐이어야 기약분수 — ⟨3/4⟩이 기약분수예요."],"variant_rule":{"alt":[{"stem":"⟨12/18⟩를 최대공약수 6으로 약분하면 한 번에 기약분수 ⟨2/3⟩가 돼요.","answer":"O","reason_options":[{"t":"최대공약수로 나누면 남는 공약수가 1뿐이므로","correct":true},{"t":"최대공약수로 나누면 분수의 크기가 작아지므로","mis":"M5-1-u3-X04"}],"explanation":["12와 18의 최대공약수는 6이에요.","12 ÷ 6 = 2, 18 ÷ 6 = 3 — ⟨12/18⟩ = ⟨2/3⟩.","2와 3의 공약수는 1뿐이라 기약분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_basic#10','math',5,1,'u3','L03','g5_1_math_u3_L03_basic','lesson_basic','M5-1-u3-C3',3,'mc','auto','약분하여 ⟨2/3⟩가 되는 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],true,'{"seq":10,"concept":"M5-1-u3-C3","difficulty":3,"kind":"mc","stem":"약분하여 ⟨2/3⟩가 되는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨12/16⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨14/21⟩","mis":"M5-1-u3-X04"},{"t":"⟨18/27⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨10/15⟩ = ⟨2/3⟩ · ⟨14/21⟩ = ⟨2/3⟩ · ⟨18/27⟩ = ⟨2/3⟩예요.","⟨12/16⟩를 기약분수로 나타내면 ⟨3/4⟩이에요.","그래서 ⟨2/3⟩가 되지 않는 것은 ⟨12/16⟩예요."],"variant_rule":{"alt":[{"stem":"약분하여 ⟨3/4⟩이 되는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨15/25⟩","correct":true},{"t":"⟨9/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨15/20⟩","mis":"M5-1-u3-X04"},{"t":"⟨21/28⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨9/12⟩ = ⟨3/4⟩ · ⟨15/20⟩ = ⟨3/4⟩ · ⟨21/28⟩ = ⟨3/4⟩이에요.","⟨15/25⟩를 기약분수로 나타내면 ⟨3/5⟩이에요.","그래서 ⟨3/4⟩이 되지 않는 것은 ⟨15/25⟩예요."]},{"stem":"약분하여 ⟨3/5⟩이 되는 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨12/18⟩","correct":true},{"t":"⟨9/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨12/20⟩","mis":"M5-1-u3-X04"},{"t":"⟨18/30⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨9/15⟩ = ⟨3/5⟩ · ⟨12/20⟩ = ⟨3/5⟩ · ⟨18/30⟩ = ⟨3/5⟩이에요.","⟨12/18⟩를 기약분수로 나타내면 ⟨2/3⟩예요.","그래서 ⟨3/5⟩이 되지 않는 것은 ⟨12/18⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#1','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',2,'mc','auto','⟨18/24⟩을 2로 약분하고, 다시 3으로 약분했어요. 한 번에 같은 결과를 얻으려면 어떤 수로 약분하면 되나요?',ARRAY['M5-1-u3-X13','M5-1-u3-X05']::text[],true,'{"seq":1,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"⟨18/24⟩을 2로 약분하고, 다시 3으로 약분했어요. 한 번에 같은 결과를 얻으려면 어떤 수로 약분하면 되나요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M5-1-u3-X13"},{"t":"3","mis":"M5-1-u3-X05"},{"t":"2","mis":"M5-1-u3-X05"}],"explanation":["⟨18/24⟩ → ⟨9/12⟩ → ⟨3/4⟩이에요.","2로 나누고 다시 3으로 나누면 2 × 3 = 6으로 나눈 것과 같아요.","그래서 6으로 한 번에 약분하면 ⟨18/24⟩ = ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨30/45⟩을 3으로 약분하고, 다시 5로 약분했어요. 한 번에 같은 결과를 얻으려면 어떤 수로 약분하면 되나요?","options":[{"t":"15","correct":true},{"t":"8","mis":"M5-1-u3-X13"},{"t":"5","mis":"M5-1-u3-X05"},{"t":"3","mis":"M5-1-u3-X05"}],"explanation":["⟨30/45⟩ → ⟨10/15⟩ → ⟨2/3⟩예요.","3으로 나누고 다시 5로 나누면 3 × 5 = 15로 나눈 것과 같아요.","그래서 15로 한 번에 약분하면 ⟨30/45⟩ = ⟨2/3⟩예요."]},{"stem":"⟨24/40⟩를 2로 약분하고, 다시 4로 약분했어요. 한 번에 같은 결과를 얻으려면 어떤 수로 약분하면 되나요?","options":[{"t":"8","correct":true},{"t":"6","mis":"M5-1-u3-X13"},{"t":"4","mis":"M5-1-u3-X05"},{"t":"2","mis":"M5-1-u3-X05"}],"explanation":["⟨24/40⟩ → ⟨12/20⟩ → ⟨3/5⟩이에요.","2로 나누고 다시 4로 나누면 2 × 4 = 8로 나눈 것과 같아요.","그래서 8로 한 번에 약분하면 ⟨24/40⟩ = ⟨3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#2','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',2,'sa','auto','⟨24/36⟩를 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C3","difficulty":2,"kind":"sa","stem":"⟨24/36⟩를 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["24와 36의 공약수는 1, 2, 3, 4, 6, 12예요.","1이 아닌 공약수 2, 3, 4, 6, 12로 한 번씩 나누어요.","⟨12/18⟩, ⟨8/12⟩, ⟨6/9⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 5개예요."],"variant_rule":{"alt":[{"stem":"⟨18/30⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["18과 30의 공약수는 1, 2, 3, 6이에요.","1이 아닌 공약수 2, 3, 6으로 한 번씩 나누어요.","⟨9/15⟩, ⟨6/10⟩, ⟨3/5⟩ — 모두 3개예요."]},{"stem":"⟨32/48⟩를 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["32와 48의 공약수는 1, 2, 4, 8, 16이에요.","1이 아닌 공약수 2, 4, 8, 16으로 한 번씩 나누어요.","⟨16/24⟩, ⟨8/12⟩, ⟨4/6⟩, ⟨2/3⟩ — 모두 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#3','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',3,'mc','auto','분모와 분자의 차가 15이고, 기약분수로 나타내면 ⟨3/8⟩인 분수는 어느 것인가요?',ARRAY['M5-1-u3-X02','M5-1-u3-X13']::text[],true,'{"seq":3,"concept":"M5-1-u3-C3","difficulty":3,"kind":"mc","stem":"분모와 분자의 차가 15이고, 기약분수로 나타내면 ⟨3/8⟩인 분수는 어느 것인가요?","options":[{"t":"⟨9/24⟩","correct":true},{"t":"⟨3/18⟩","mis":"M5-1-u3-X02"},{"t":"⟨15/40⟩","mis":"M5-1-u3-X13"},{"t":"⟨6/16⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨3/8⟩의 분모와 분자의 차는 8 − 3 = 5예요.","분모와 분자에 같은 수를 곱하면 차도 그만큼 커져요 — 15 ÷ 5 = 3배.","⟨3/8⟩ = ⟨9/24⟩ — 차는 24 − 9 = 15예요."],"variant_rule":{"alt":[{"stem":"분모와 분자의 차가 12이고, 기약분수로 나타내면 ⟨2/5⟩인 분수는 어느 것인가요?","options":[{"t":"⟨8/20⟩","correct":true},{"t":"⟨6/15⟩","mis":"M5-1-u3-X13"},{"t":"⟨10/25⟩","mis":"M5-1-u3-X13"},{"t":"⟨2/14⟩","mis":"M5-1-u3-X02"}],"explanation":["⟨2/5⟩의 분모와 분자의 차는 5 − 2 = 3이에요.","분모와 분자에 같은 수를 곱하면 차도 그만큼 커져요 — 12 ÷ 3 = 4배.","⟨2/5⟩ = ⟨8/20⟩ — 차는 20 − 8 = 12예요."]},{"stem":"분모와 분자의 차가 9이고, 기약분수로 나타내면 ⟨4/7⟩인 분수는 어느 것인가요?","options":[{"t":"⟨12/21⟩","correct":true},{"t":"⟨8/14⟩","mis":"M5-1-u3-X13"},{"t":"⟨16/28⟩","mis":"M5-1-u3-X13"},{"t":"⟨4/13⟩","mis":"M5-1-u3-X02"}],"explanation":["⟨4/7⟩의 분모와 분자의 차는 7 − 4 = 3이에요.","분모와 분자에 같은 수를 곱하면 차도 그만큼 커져요 — 9 ÷ 3 = 3배.","⟨4/7⟩ = ⟨12/21⟩ — 차는 21 − 12 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#4','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',3,'sa','auto','분모가 12인 진분수 중에서 기약분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"분모가 12인 진분수 중에서 기약분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["분모가 12인 진분수는 ⟨1/12⟩부터 ⟨11/12⟩까지예요.","분자가 12와 공약수 1만 갖는 수여야 기약분수예요 — 1, 5, 7, 11.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"분모가 15인 진분수 중에서 기약분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8","8개"],"explanation":["분모가 15인 진분수는 ⟨1/15⟩부터 ⟨14/15⟩까지예요.","분자가 15와 공약수 1만 갖는 수여야 기약분수예요 — 1, 2, 4, 7, 8, 11, 13, 14.","모두 8개예요."]},{"stem":"분모가 9인 진분수 중에서 기약분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6","6개"],"explanation":["분모가 9인 진분수는 ⟨1/9⟩부터 ⟨8/9⟩까지예요.","분자가 9와 공약수 1만 갖는 수여야 기약분수예요 — 1, 2, 4, 5, 7, 8.","모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#5','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',3,'error','auto','⟨36/48⟩을 기약분수로 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X14']::text[],true,'{"seq":5,"concept":"M5-1-u3-C3","difficulty":3,"kind":"error","stem":"⟨36/48⟩을 기약분수로 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은채 — 「2로 한 번 약분한 ⟨18/24⟩이 기약분수야.」","correct":true,"mis_target":"M5-1-u3-X05"},{"t":"태오 — 「최대공약수 12로 한 번에 나누면 ⟨3/4⟩이야.」","mis":"M5-1-u3-X14"},{"t":"나윤 — 「2, 2, 3으로 차례로 나누어도 ⟨3/4⟩이 돼.」","mis":"M5-1-u3-X14"}],"explanation":["36과 48의 최대공약수는 12예요.","⟨18/24⟩의 분모와 분자에는 아직 공약수 6이 남아 있어요.","그래서 은채는 잘못 말했어요. 기약분수는 ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨40/60⟩을 기약분수로 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「2로 한 번 약분한 ⟨20/30⟩이 기약분수야.」","correct":true,"mis_target":"M5-1-u3-X05"},{"t":"시후 — 「최대공약수 20으로 한 번에 나누면 ⟨2/3⟩야.」","mis":"M5-1-u3-X14"},{"t":"아린 — 「2, 2, 5로 차례로 나누어도 ⟨2/3⟩가 돼.」","mis":"M5-1-u3-X14"}],"explanation":["40과 60의 최대공약수는 20이에요.","⟨20/30⟩의 분모와 분자에는 아직 공약수 10이 남아 있어요.","그래서 윤서는 잘못 말했어요. 기약분수는 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#6','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',3,'mc','auto','어떤 분수를 2로 약분한 다음 다시 3으로 약분했더니 ⟨4/7⟩가 되었어요. 처음 분수는 어느 것인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X01']::text[],true,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 분수를 2로 약분한 다음 다시 3으로 약분했더니 ⟨4/7⟩가 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨24/42⟩","correct":true},{"t":"⟨20/35⟩","mis":"M5-1-u3-X13"},{"t":"⟨9/12⟩","mis":"M5-1-u3-X01"},{"t":"⟨8/14⟩","mis":"M5-1-u3-X13"}],"explanation":["거꾸로 되돌리면 분모와 분자에 3과 2를 곱해요.","2 × 3 = 6 — 분모와 분자에 6을 곱하는 것과 같아요.","⟨4/7⟩ = ⟨24/42⟩예요."],"variant_rule":{"alt":[{"stem":"어떤 분수를 3으로 약분한 다음 다시 2로 약분했더니 ⟨3/5⟩이 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨18/30⟩","correct":true},{"t":"⟨9/15⟩","mis":"M5-1-u3-X13"},{"t":"⟨6/10⟩","mis":"M5-1-u3-X13"},{"t":"⟨8/10⟩","mis":"M5-1-u3-X01"}],"explanation":["거꾸로 되돌리면 분모와 분자에 2와 3을 곱해요.","3 × 2 = 6 — 분모와 분자에 6을 곱하는 것과 같아요.","⟨3/5⟩ = ⟨18/30⟩이에요."]},{"stem":"어떤 분수를 2로 약분한 다음 다시 5로 약분했더니 ⟨1/4⟩이 되었어요. 처음 분수는 어느 것인가요?","options":[{"t":"⟨10/40⟩","correct":true},{"t":"⟨2/8⟩","mis":"M5-1-u3-X13"},{"t":"⟨5/20⟩","mis":"M5-1-u3-X13"},{"t":"⟨8/11⟩","mis":"M5-1-u3-X01"}],"explanation":["거꾸로 되돌리면 분모와 분자에 5와 2를 곱해요.","2 × 5 = 10 — 분모와 분자에 10을 곱하는 것과 같아요.","⟨1/4⟩ = ⟨10/40⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#7','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',3,'mc','auto','⟨42/56⟩를 한 번에 기약분수로 나타내려면 분모와 분자를 어떤 수로 나누어야 하나요?',ARRAY['M5-1-u3-X05','M5-1-u3-X06']::text[],true,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":3,"kind":"mc","stem":"⟨42/56⟩를 한 번에 기약분수로 나타내려면 분모와 분자를 어떤 수로 나누어야 하나요?","options":[{"t":"14","correct":true},{"t":"7","mis":"M5-1-u3-X05"},{"t":"2","mis":"M5-1-u3-X05"},{"t":"28","mis":"M5-1-u3-X06"}],"explanation":["42의 약수: 1, 2, 3, 6, 7, 14, 21, 42 · 56의 약수: 1, 2, 4, 7, 8, 14, 28, 56","공약수 중 가장 큰 최대공약수는 14예요.","42 ÷ 14 = 3, 56 ÷ 14 = 4 — ⟨42/56⟩ = ⟨3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨36/54⟩을 한 번에 기약분수로 나타내려면 분모와 분자를 어떤 수로 나누어야 하나요?","options":[{"t":"18","correct":true},{"t":"9","mis":"M5-1-u3-X05"},{"t":"6","mis":"M5-1-u3-X05"},{"t":"27","mis":"M5-1-u3-X06"}],"explanation":["36의 약수: 1, 2, 3, 4, 6, 9, 12, 18, 36 · 54의 약수: 1, 2, 3, 6, 9, 18, 27, 54","공약수 중 가장 큰 최대공약수는 18이에요.","36 ÷ 18 = 2, 54 ÷ 18 = 3 — ⟨36/54⟩ = ⟨2/3⟩예요."]},{"stem":"⟨45/75⟩를 한 번에 기약분수로 나타내려면 분모와 분자를 어떤 수로 나누어야 하나요?","options":[{"t":"15","correct":true},{"t":"5","mis":"M5-1-u3-X05"},{"t":"3","mis":"M5-1-u3-X05"},{"t":"25","mis":"M5-1-u3-X06"}],"explanation":["45의 약수: 1, 3, 5, 9, 15, 45 · 75의 약수: 1, 3, 5, 15, 25, 75","공약수 중 가장 큰 최대공약수는 15예요.","45 ÷ 15 = 3, 75 ÷ 15 = 5 — ⟨45/75⟩ = ⟨3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#8','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',4,'sa','auto','⟨3/5⟩과 크기가 같은 분수 중에서 분모와 분자의 공약수가 1, 2, 4, 8뿐인 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":4,"kind":"sa","stem":"⟨3/5⟩과 크기가 같은 분수 중에서 분모와 분자의 공약수가 1, 2, 4, 8뿐인 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["공약수가 1, 2, 4, 8뿐이면 최대공약수가 8이에요.","⟨3/5⟩은 기약분수라 분모와 분자에 8을 곱하면 최대공약수가 8이 돼요.","⟨3/5⟩ = ⟨24/40⟩ — 분모는 40이에요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩와 크기가 같은 분수 중에서 분모와 분자의 공약수가 1, 2, 3, 6뿐인 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["공약수가 1, 2, 3, 6뿐이면 최대공약수가 6이에요.","⟨2/7⟩는 기약분수라 분모와 분자에 6을 곱하면 최대공약수가 6이 돼요.","⟨2/7⟩ = ⟨12/42⟩ — 분모는 42예요."]},{"stem":"⟨5/8⟩와 크기가 같은 분수 중에서 분모와 분자의 공약수가 1, 3, 9뿐인 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["공약수가 1, 3, 9뿐이면 최대공약수가 9예요.","⟨5/8⟩는 기약분수라 분모와 분자에 9를 곱하면 최대공약수가 9가 돼요.","⟨5/8⟩ = ⟨45/72⟩ — 분모는 72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#9','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',4,'essay','teacher','⟨18/24⟩을 약분할 때 분자만 3으로 나누면 안 되는 까닭을 조각의 크기와 개수로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":4,"kind":"essay","stem":"⟨18/24⟩을 약분할 때 분자만 3으로 나누면 안 되는 까닭을 조각의 크기와 개수로 설명하세요.","answer_guide":{"answer":"예: 분자만 3으로 나누면 ⟨6/24⟩이 되어 조각의 크기(⟨1/24⟩)은 그대로인데 조각 개수만 18개에서 6개로 줄어 양이 작아진다. 분모와 분자를 함께 3으로 나누면 ⟨6/8⟩이 되어 조각이 3배 커진 만큼 개수가 3배 줄어 양이 그대로이다.","scoring_points":["분자만 나누면 조각 크기는 그대로이고 개수만 준다고 썼는가","그래서 양이 작아진다고 썼는가","분모와 분자를 함께 나누어야 양이 지켜진다고 맺었는가"]},"explanation":["분자만 나누면 ⟨6/24⟩ — 조각 크기는 그대로, 개수만 줄어요.","⟨6/24⟩은 ⟨18/24⟩보다 작아요.","분모와 분자를 함께 나누어야 ⟨18/24⟩ = ⟨6/8⟩처럼 양이 지켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L03_challenge#10','math',5,1,'u3','L03','g5_1_math_u3_L03_challenge','lesson_challenge','M5-1-u3-C3',4,'essay','teacher','⟨24/36⟩를 기약분수로 고치는 두 가지 방법(여러 번 약분하기, 최대공약수로 한 번에 약분하기)을 쓰고 두 결과를 견주세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C3","difficulty":4,"kind":"essay","stem":"⟨24/36⟩를 기약분수로 고치는 두 가지 방법(여러 번 약분하기, 최대공약수로 한 번에 약분하기)을 쓰고 두 결과를 견주세요.","answer_guide":{"answer":"예: 여러 번 약분하면 2로 나누어 ⟨12/18⟩, 다시 2로 나누어 ⟨6/9⟩, 다시 3으로 나누어 ⟨2/3⟩이다. 24와 36의 최대공약수 12로 한 번에 나누면 바로 ⟨2/3⟩이다. 두 방법의 결과는 같고, 최대공약수로 나누면 한 번에 끝난다.","scoring_points":["여러 번 약분하는 과정을 바르게 썼는가","최대공약수 12로 한 번에 약분했는가","두 결과가 ⟨2/3⟩로 같다고 썼는가"]},"explanation":["⟨24/36⟩ = ⟨12/18⟩ = ⟨6/9⟩ = ⟨2/3⟩예요.","24와 36의 최대공약수 12로 나누면 한 번에 ⟨2/3⟩예요.","2 × 2 × 3 = 12 — 여러 번 나눈 수를 곱하면 최대공약수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#1','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',1,'mc','auto','⟨1/6⟩과 ⟨3/10⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X08']::text[],true,'{"seq":1,"concept":"M5-1-u3-C4","difficulty":1,"kind":"mc","stem":"⟨1/6⟩과 ⟨3/10⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"45","correct":true},{"t":"30","mis":"M5-1-u3-X08"},{"t":"60","mis":"M5-1-u3-X08"},{"t":"90","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 6과 10의 공배수예요.","6과 10의 공배수는 30, 60, 90 …이에요.","45는 두 분모 모두의 배수가 아니에요 — 그래서 공통분모가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩과 ⟨5/6⟩를 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"18","correct":true},{"t":"12","mis":"M5-1-u3-X08"},{"t":"24","mis":"M5-1-u3-X08"},{"t":"36","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 4와 6의 공배수예요.","4와 6의 공배수는 12, 24, 36 …이에요.","18은 6의 배수이지만 4의 배수는 아니에요 — 그래서 공통분모가 될 수 없어요."]},{"stem":"⟨2/3⟩와 ⟨3/8⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"32","correct":true},{"t":"24","mis":"M5-1-u3-X08"},{"t":"48","mis":"M5-1-u3-X08"},{"t":"72","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 3과 8의 공배수예요.","3과 8의 공배수는 24, 48, 72 …이에요.","32는 8의 배수이지만 3의 배수는 아니에요 — 그래서 공통분모가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#2','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',1,'sa','auto','⟨1/4⟩과 ⟨5/6⟩를 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C4","difficulty":1,"kind":"sa","stem":"⟨1/4⟩과 ⟨5/6⟩를 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["4의 배수: 4, 8, 12, 16 … · 6의 배수: 6, 12, 18 …","처음으로 함께 나오는 수가 최소공배수 12예요.","그래서 공통분모는 12 — ⟨3/12⟩, ⟨10/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩과 ⟨5/12⟩를 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["8의 배수: 8, 16, 24, 32 … · 12의 배수: 12, 24, 36 …","처음으로 함께 나오는 수가 최소공배수 24예요.","그래서 공통분모는 24 — ⟨9/24⟩, ⟨10/24⟩이에요."]},{"stem":"⟨1/9⟩과 ⟨5/6⟩를 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["9의 배수: 9, 18, 27 … · 6의 배수: 6, 12, 18, 24 …","처음으로 함께 나오는 수가 최소공배수 18이에요.","그래서 공통분모는 18 — ⟨2/18⟩, ⟨15/18⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#3','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',1,'mc','auto','⟨2/3⟩와 ⟨1/4⟩을 두 분모의 곱으로 통분하면 어느 것인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X13','M5-1-u3-X08']::text[],true,'{"seq":3,"concept":"M5-1-u3-C4","difficulty":1,"kind":"mc","stem":"⟨2/3⟩와 ⟨1/4⟩을 두 분모의 곱으로 통분하면 어느 것인가요?","options":[{"t":"⟨8/12⟩, ⟨3/12⟩","correct":true},{"t":"⟨2/12⟩, ⟨1/12⟩","mis":"M5-1-u3-X07"},{"t":"⟨6/12⟩, ⟨4/12⟩","mis":"M5-1-u3-X13"},{"t":"⟨2/3⟩, ⟨3/12⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 곱 3 × 4 = 12예요.","⟨2/3⟩의 분모와 분자에 4를, ⟨1/4⟩의 분모와 분자에 3을 곱해요.","⟨2/3⟩ = ⟨8/12⟩, ⟨1/4⟩ = ⟨3/12⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩과 ⟨2/5⟩를 두 분모의 곱으로 통분하면 어느 것인가요?","options":[{"t":"⟨5/10⟩, ⟨4/10⟩","correct":true},{"t":"⟨1/10⟩, ⟨2/10⟩","mis":"M5-1-u3-X07"},{"t":"⟨2/10⟩, ⟨10/10⟩","mis":"M5-1-u3-X13"},{"t":"⟨1/2⟩, ⟨4/10⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 곱 2 × 5 = 10이에요.","⟨1/2⟩의 분모와 분자에 5를, ⟨2/5⟩의 분모와 분자에 2를 곱해요.","⟨1/2⟩ = ⟨5/10⟩, ⟨2/5⟩ = ⟨4/10⟩예요."]},{"stem":"⟨3/4⟩과 ⟨2/7⟩를 두 분모의 곱으로 통분하면 어느 것인가요?","options":[{"t":"⟨21/28⟩, ⟨8/28⟩","correct":true},{"t":"⟨3/28⟩, ⟨2/28⟩","mis":"M5-1-u3-X07"},{"t":"⟨12/28⟩, ⟨14/28⟩","mis":"M5-1-u3-X13"},{"t":"⟨3/4⟩, ⟨8/28⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 곱 4 × 7 = 28이에요.","⟨3/4⟩의 분모와 분자에 7을, ⟨2/7⟩의 분모와 분자에 4를 곱해요.","⟨3/4⟩ = ⟨21/28⟩, ⟨2/7⟩ = ⟨8/28⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#4','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',1,'sa','auto','⟨1/5⟩과 ⟨2/3⟩를 두 분모의 곱으로 통분하면 ⟨1/5⟩은 ⟨□/15⟩가 돼요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C4","difficulty":1,"kind":"sa","stem":"⟨1/5⟩과 ⟨2/3⟩를 두 분모의 곱으로 통분하면 ⟨1/5⟩은 ⟨□/15⟩가 돼요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 분모의 곱은 5 × 3 = 15예요.","⟨1/5⟩의 분모에 3을 곱했으니 분자에도 3을 곱해요 — 1 × 3 = 3.","⟨1/5⟩ = ⟨3/15⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 ⟨1/7⟩을 두 분모의 곱으로 통분하면 ⟨3/4⟩은 ⟨□/28⟩가 돼요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["두 분모의 곱은 4 × 7 = 28이에요.","⟨3/4⟩의 분모에 7을 곱했으니 분자에도 7을 곱해요 — 3 × 7 = 21.","⟨3/4⟩ = ⟨21/28⟩이에요."]},{"stem":"⟨2/9⟩와 ⟨1/2⟩을 두 분모의 곱으로 통분하면 ⟨2/9⟩는 ⟨□/18⟩가 돼요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 분모의 곱은 9 × 2 = 18이에요.","⟨2/9⟩의 분모에 2를 곱했으니 분자에도 2를 곱해요 — 2 × 2 = 4.","⟨2/9⟩ = ⟨4/18⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#5','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',2,'mc','auto','⟨3/4⟩과 ⟨1/6⟩을 통분한 것 중 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u3-X08']::text[],true,'{"seq":5,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩과 ⟨1/6⟩을 통분한 것 중 잘못된 것은 어느 것인가요?","options":[{"t":"⟨3/12⟩, ⟨1/12⟩","correct":true},{"t":"⟨9/12⟩, ⟨2/12⟩","mis":"M5-1-u3-X08"},{"t":"⟨18/24⟩, ⟨4/24⟩","mis":"M5-1-u3-X08"},{"t":"⟨36/48⟩, ⟨8/48⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모 12, 24, 48은 모두 4와 6의 공배수라 쓸 수 있어요.","분모를 몇 배 했으면 분자도 같은 수만큼 곱해야 해요.","⟨3/12⟩, ⟨1/12⟩은 분모만 12로 바꾸고 분자는 그대로 두어 잘못되었어요 — 바르게는 ⟨9/12⟩, ⟨2/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩와 ⟨1/4⟩을 통분한 것 중 잘못된 것은 어느 것인가요?","options":[{"t":"⟨2/12⟩, ⟨1/12⟩","correct":true},{"t":"⟨8/12⟩, ⟨3/12⟩","mis":"M5-1-u3-X08"},{"t":"⟨16/24⟩, ⟨6/24⟩","mis":"M5-1-u3-X08"},{"t":"⟨32/48⟩, ⟨12/48⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모 12, 24, 48은 모두 3과 4의 공배수라 쓸 수 있어요.","분모를 몇 배 했으면 분자도 같은 수만큼 곱해야 해요.","⟨2/12⟩, ⟨1/12⟩은 분모만 12로 바꾸고 분자는 그대로 두어 잘못되었어요 — 바르게는 ⟨8/12⟩, ⟨3/12⟩이에요."]},{"stem":"⟨1/2⟩과 ⟨3/5⟩을 통분한 것 중 잘못된 것은 어느 것인가요?","options":[{"t":"⟨1/10⟩, ⟨3/10⟩","correct":true},{"t":"⟨5/10⟩, ⟨6/10⟩","mis":"M5-1-u3-X08"},{"t":"⟨10/20⟩, ⟨12/20⟩","mis":"M5-1-u3-X08"},{"t":"⟨20/40⟩, ⟨24/40⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모 10, 20, 40은 모두 2와 5의 공배수라 쓸 수 있어요.","분모를 몇 배 했으면 분자도 같은 수만큼 곱해야 해요.","⟨1/10⟩, ⟨3/10⟩은 분모만 10으로 바꾸고 분자는 그대로 두어 잘못되었어요 — 바르게는 ⟨5/10⟩, ⟨6/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#6','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',2,'sa','auto','⟨2/5⟩와 ⟨4/7⟩를 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u3-C4","difficulty":2,"kind":"sa","stem":"⟨2/5⟩와 ⟨4/7⟩를 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["공통분모는 두 분모 5와 7의 공배수예요.","공배수 중 가장 작은 것은 최소공배수 35예요.","⟨2/5⟩ = ⟨14/35⟩, ⟨4/7⟩ = ⟨20/35⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩와 ⟨3/8⟩을 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["공통분모는 두 분모 6과 8의 공배수예요.","공배수 중 가장 작은 것은 최소공배수 24예요.","⟨5/6⟩ = ⟨20/24⟩, ⟨3/8⟩ = ⟨9/24⟩예요."]},{"stem":"⟨1/4⟩과 ⟨7/10⟩을 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["공통분모는 두 분모 4와 10의 공배수예요.","공배수 중 가장 작은 것은 최소공배수 20이에요.","⟨1/4⟩ = ⟨5/20⟩, ⟨7/10⟩ = ⟨14/20⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#7','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',2,'mc','auto','⟨5/8⟩와 ⟨7/12⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X13','M5-1-u3-X08']::text[],true,'{"seq":7,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨5/8⟩와 ⟨7/12⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨15/24⟩, ⟨14/24⟩","correct":true},{"t":"⟨5/24⟩, ⟨7/24⟩","mis":"M5-1-u3-X07"},{"t":"⟨10/24⟩, ⟨21/24⟩","mis":"M5-1-u3-X13"},{"t":"⟨60/96⟩, ⟨56/96⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 24예요.","⟨5/8⟩의 분모와 분자에 3을, ⟨7/12⟩의 분모와 분자에 2를 곱해요.","⟨5/8⟩ = ⟨15/24⟩, ⟨7/12⟩ = ⟨14/24⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 ⟨5/6⟩를 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨9/12⟩, ⟨10/12⟩","correct":true},{"t":"⟨3/12⟩, ⟨5/12⟩","mis":"M5-1-u3-X07"},{"t":"⟨6/12⟩, ⟨15/12⟩","mis":"M5-1-u3-X13"},{"t":"⟨18/24⟩, ⟨20/24⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 12예요.","⟨3/4⟩의 분모와 분자에 3을, ⟨5/6⟩의 분모와 분자에 2를 곱해요.","⟨3/4⟩ = ⟨9/12⟩, ⟨5/6⟩ = ⟨10/12⟩이에요."]},{"stem":"⟨1/6⟩과 ⟨4/9⟩를 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨3/18⟩, ⟨8/18⟩","correct":true},{"t":"⟨1/18⟩, ⟨4/18⟩","mis":"M5-1-u3-X07"},{"t":"⟨2/18⟩, ⟨12/18⟩","mis":"M5-1-u3-X13"},{"t":"⟨9/54⟩, ⟨24/54⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 18이에요.","⟨1/6⟩의 분모와 분자에 3을, ⟨4/9⟩의 분모와 분자에 2를 곱해요.","⟨1/6⟩ = ⟨3/18⟩, ⟨4/9⟩ = ⟨8/18⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#8','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',2,'mc','auto','통분을 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u3-X04','M5-1-u3-X07','M5-1-u3-X13']::text[],true,'{"seq":8,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"통분을 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"분모가 다른 분수의 크기를 견주려고","correct":true},{"t":"분수를 더 작게 만들려고","mis":"M5-1-u3-X04"},{"t":"분자를 없애려고","mis":"M5-1-u3-X07"},{"t":"분수를 자연수로 바꾸려고","mis":"M5-1-u3-X13"}],"explanation":["꽃밭의 ⟨1/6⟩과 ⟨3/10⟩은 조각의 크기가 달라 바로 견주기 어려워요.","두 띠를 30칸으로 다시 나누면 ⟨5/30⟩와 ⟨9/30⟩ — 같은 자로 잰 셈이에요.","통분은 조각의 크기를 같게 맞추어 견주려고 해요."],"variant_rule":{"alt":[{"stem":"통분에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"통분해도 분수의 크기는 변하지 않는다","correct":true},{"t":"통분하면 분수가 커진다","mis":"M5-1-u3-X04"},{"t":"통분은 분모만 바꾸는 것이다","mis":"M5-1-u3-X07"},{"t":"공통분모는 하나뿐이다","mis":"M5-1-u3-X08"}],"explanation":["통분은 분모와 분자에 같은 수를 곱해 크기가 같은 분수로 바꾸는 거예요.","분모를 몇 배 했으면 분자도 그만큼 곱해요.","공통분모는 두 분모의 공배수 어느 것이든 될 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#9','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',2,'ox','auto','⟨1/6⟩과 ⟨3/10⟩을 통분할 때 공통분모는 30 하나뿐이에요.',ARRAY['M5-1-u3-X08']::text[],true,'{"seq":9,"concept":"M5-1-u3-C4","difficulty":2,"kind":"ox","stem":"⟨1/6⟩과 ⟨3/10⟩을 통분할 때 공통분모는 30 하나뿐이에요.","answer":"X","reason_options":[{"t":"6과 10의 공배수 30, 60, 90 …은 모두 공통분모가 될 수 있으므로","correct":true},{"t":"공통분모는 최소공배수 하나로 정해져 있으므로","mis":"M5-1-u3-X08"}],"mis":"M5-1-u3-X08","explanation":["6과 10의 공배수는 30, 60, 90 …이에요.","60으로 통분하면 ⟨10/60⟩, ⟨18/60⟩ — 이것도 바른 통분이에요.","가장 작은 공통분모가 30일 뿐, 공통분모는 여러 개예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩을 분모가 30인 분수로 바꿀 때 분모만 30으로 바꾸어 ⟨1/30⟩로 써요.","answer":"X","reason_options":[{"t":"분모를 5배 했으면 분자도 5배 해서 ⟨5/30⟩가 되어야 양이 같으므로","correct":true},{"t":"통분은 분모만 같게 하는 것이므로","mis":"M5-1-u3-X07"}],"explanation":["6 × 5 = 30 — 분모를 5배 했어요.","조각이 5배 잘아졌으니 조각 개수도 5배 — 1 × 5 = 5.","⟨1/6⟩ = ⟨5/30⟩예요. ⟨1/30⟩은 양이 확 줄어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_basic#10','math',5,1,'u3','L04','g5_1_math_u3_L04_basic','lesson_basic','M5-1-u3-C4',3,'sa','auto','⟨5/6⟩, ⟨4/9⟩를 두 분모의 최소공배수로 통분했을 때 두 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u3-C4","difficulty":3,"kind":"sa","stem":"⟨5/6⟩, ⟨4/9⟩를 두 분모의 최소공배수로 통분했을 때 두 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["두 분모 6, 9의 최소공배수는 18이에요.","⟨5/6⟩ = ⟨15/18⟩, ⟨4/9⟩ = ⟨8/18⟩이에요.","분자의 합은 15 + 8 = 23이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩, ⟨5/6⟩를 두 분모의 최소공배수로 통분했을 때 두 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["두 분모 4, 6의 최소공배수는 12예요.","⟨3/4⟩ = ⟨9/12⟩, ⟨5/6⟩ = ⟨10/12⟩이에요.","분자의 합은 9 + 10 = 19예요."]},{"stem":"⟨1/8⟩, ⟨5/12⟩를 두 분모의 최소공배수로 통분했을 때 두 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["두 분모 8, 12의 최소공배수는 24예요.","⟨1/8⟩ = ⟨3/24⟩, ⟨5/12⟩ = ⟨10/24⟩이에요.","분자의 합은 3 + 10 = 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#1','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',2,'sa','auto','⟨1/6⟩과 ⟨3/10⟩의 공통분모가 될 수 있는 수 중에서 100보다 작은 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-1-u3-C4","difficulty":2,"kind":"sa","stem":"⟨1/6⟩과 ⟨3/10⟩의 공통분모가 될 수 있는 수 중에서 100보다 작은 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["공통분모는 6과 10의 공배수, 곧 최소공배수 30의 배수예요.","100보다 작은 것은 30, 60, 90이에요.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩과 ⟨5/6⟩의 공통분모가 될 수 있는 수 중에서 50보다 작은 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["공통분모는 4와 6의 공배수, 곧 최소공배수 12의 배수예요.","50보다 작은 것은 12, 24, 36, 48이에요.","모두 4개예요."]},{"stem":"⟨2/9⟩와 ⟨1/6⟩의 공통분모가 될 수 있는 수 중에서 100보다 작은 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["공통분모는 9와 6의 공배수, 곧 최소공배수 18의 배수예요.","100보다 작은 것은 18, 36, 54, 72, 90이에요.","모두 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#2','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',2,'error','auto','⟨2/3⟩와 ⟨3/5⟩을 통분한 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X14']::text[],true,'{"seq":2,"concept":"M5-1-u3-C4","difficulty":2,"kind":"error","stem":"⟨2/3⟩와 ⟨3/5⟩을 통분한 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「분모만 15로 바꾸면 ⟨2/15⟩, ⟨3/15⟩이야.」","correct":true,"mis_target":"M5-1-u3-X07"},{"t":"유나 — 「15로 통분하면 ⟨10/15⟩, ⟨9/15⟩야.」","mis":"M5-1-u3-X14"},{"t":"시우 — 「공통분모는 30으로 해도 돼.」","mis":"M5-1-u3-X14"}],"explanation":["⟨2/3⟩ = ⟨10/15⟩, ⟨3/5⟩ = ⟨9/15⟩예요.","30도 3과 5의 공배수라 공통분모가 될 수 있어요.","라온은 분자를 그대로 두어 잘못 말했어요. 분모를 몇 배 했으면 분자도 그만큼 곱해요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 ⟨1/6⟩을 통분한 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채아 — 「분모만 12로 바꾸면 ⟨3/12⟩, ⟨1/12⟩이야.」","correct":true,"mis_target":"M5-1-u3-X07"},{"t":"준혁 — 「12로 통분하면 ⟨9/12⟩, ⟨2/12⟩야.」","mis":"M5-1-u3-X14"},{"t":"소율 — 「공통분모는 24로 해도 돼.」","mis":"M5-1-u3-X14"}],"explanation":["⟨3/4⟩ = ⟨9/12⟩, ⟨1/6⟩ = ⟨2/12⟩예요.","24도 4와 6의 공배수라 공통분모가 될 수 있어요.","채아는 분자를 그대로 두어 잘못 말했어요. 분모를 몇 배 했으면 분자도 그만큼 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#3','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',3,'sa','auto','⟨3/8⟩과 ⟨5/12⟩를 통분할 때, 두 분모의 곱으로 정한 공통분모와 최소공배수로 정한 공통분모의 차는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u3-C4","difficulty":3,"kind":"sa","stem":"⟨3/8⟩과 ⟨5/12⟩를 통분할 때, 두 분모의 곱으로 정한 공통분모와 최소공배수로 정한 공통분모의 차는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["두 분모의 곱은 8 × 12 = 96이에요.","8과 12의 최소공배수는 24예요.","차는 96 − 24 = 72예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩과 ⟨4/9⟩를 통분할 때, 두 분모의 곱으로 정한 공통분모와 최소공배수로 정한 공통분모의 차는 얼마인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["두 분모의 곱은 6 × 9 = 54예요.","6과 9의 최소공배수는 18이에요.","차는 54 − 18 = 36이에요."]},{"stem":"⟨1/4⟩과 ⟨3/10⟩을 통분할 때, 두 분모의 곱으로 정한 공통분모와 최소공배수로 정한 공통분모의 차는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["두 분모의 곱은 4 × 10 = 40이에요.","4와 10의 최소공배수는 20이에요.","차는 40 − 20 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#4','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',3,'mc','auto','기약분수인 두 분수를 최소공배수로 통분했더니 ⟨9/24⟩, ⟨20/24⟩이 되었어요. 처음 두 분수는 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02','M5-1-u3-X13']::text[],true,'{"seq":4,"concept":"M5-1-u3-C4","difficulty":3,"kind":"mc","stem":"기약분수인 두 분수를 최소공배수로 통분했더니 ⟨9/24⟩, ⟨20/24⟩이 되었어요. 처음 두 분수는 어느 것인가요?","options":[{"t":"⟨3/8⟩, ⟨5/6⟩","correct":true},{"t":"⟨3/8⟩, ⟨10/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨9/12⟩, ⟨20/12⟩","mis":"M5-1-u3-X02"},{"t":"⟨3/4⟩, ⟨5/6⟩","mis":"M5-1-u3-X13"}],"explanation":["통분한 분수를 약분하면 처음 분수로 돌아가요.","⟨9/24⟩ = ⟨3/8⟩, ⟨20/24⟩ = ⟨5/6⟩예요.","8과 6의 최소공배수가 24가 맞는지도 확인해요."],"variant_rule":{"alt":[{"stem":"기약분수인 두 분수를 최소공배수로 통분했더니 ⟨10/12⟩, ⟨3/12⟩이 되었어요. 처음 두 분수는 어느 것인가요?","options":[{"t":"⟨5/6⟩, ⟨1/4⟩","correct":true},{"t":"⟨5/6⟩, ⟨3/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨10/6⟩, ⟨3/4⟩","mis":"M5-1-u3-X02"},{"t":"⟨5/6⟩, ⟨1/3⟩","mis":"M5-1-u3-X13"}],"explanation":["통분한 분수를 약분하면 처음 분수로 돌아가요.","⟨10/12⟩ = ⟨5/6⟩, ⟨3/12⟩ = ⟨1/4⟩이에요.","6과 4의 최소공배수가 12가 맞는지도 확인해요."]},{"stem":"기약분수인 두 분수를 최소공배수로 통분했더니 ⟨14/30⟩, ⟨25/30⟩가 되었어요. 처음 두 분수는 어느 것인가요?","options":[{"t":"⟨7/15⟩, ⟨5/6⟩","correct":true},{"t":"⟨14/30⟩, ⟨5/6⟩","mis":"M5-1-u3-X05"},{"t":"⟨14/15⟩, ⟨25/6⟩","mis":"M5-1-u3-X02"},{"t":"⟨7/15⟩, ⟨5/12⟩","mis":"M5-1-u3-X13"}],"explanation":["통분한 분수를 약분하면 처음 분수로 돌아가요.","⟨14/30⟩ = ⟨7/15⟩, ⟨25/30⟩ = ⟨5/6⟩예요.","15와 6의 최소공배수가 30이 맞는지도 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#5','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',3,'sa','auto','⟨3/4⟩과 ⟨5/6⟩를 통분하려고 해요. 공통분모를 40보다 크고 50보다 작은 수로 하면 공통분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u3-C4","difficulty":3,"kind":"sa","stem":"⟨3/4⟩과 ⟨5/6⟩를 통분하려고 해요. 공통분모를 40보다 크고 50보다 작은 수로 하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["공통분모는 최소공배수 12의 배수예요 — 12, 24, 36, 48, 60 ….","40보다 크고 50보다 작은 것은 48 하나예요.","⟨3/4⟩ = ⟨36/48⟩, ⟨5/6⟩ = ⟨40/48⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩과 ⟨3/8⟩을 통분하려고 해요. 공통분모를 50보다 크고 80보다 작은 수로 하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["공통분모는 최소공배수 24의 배수예요 — 24, 48, 72, 96 ….","50보다 크고 80보다 작은 것은 72 하나예요.","⟨1/6⟩ = ⟨12/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요."]},{"stem":"⟨2/5⟩와 ⟨1/4⟩을 통분하려고 해요. 공통분모를 50보다 크고 70보다 작은 수로 하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["공통분모는 최소공배수 20의 배수예요 — 20, 40, 60, 80 ….","50보다 크고 70보다 작은 것은 60 하나예요.","⟨2/5⟩ = ⟨24/60⟩, ⟨1/4⟩ = ⟨15/60⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#6','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',3,'ox','auto','⟨3/5⟩과 ⟨1/4⟩을 통분할 때는 두 분모의 곱 20이 최소공배수와 같아요.',ARRAY['M5-1-u3-X08']::text[],true,'{"seq":6,"concept":"M5-1-u3-C4","difficulty":3,"kind":"ox","stem":"⟨3/5⟩과 ⟨1/4⟩을 통분할 때는 두 분모의 곱 20이 최소공배수와 같아요.","answer":"O","reason_options":[{"t":"5와 4는 공약수가 1뿐이라 최소공배수가 두 수의 곱 20이므로","correct":true},{"t":"두 분모의 곱은 언제나 최소공배수이므로","mis":"M5-1-u3-X08"}],"mis":"M5-1-u3-X08","explanation":["5와 4의 공약수는 1뿐이에요.","그래서 최소공배수가 5 × 4 = 20이에요.","⟨3/5⟩ = ⟨12/20⟩, ⟨1/4⟩ = ⟨5/20⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩와 ⟨3/8⟩을 통분할 때도 두 분모의 곱 48이 가장 작은 공통분모예요.","answer":"X","reason_options":[{"t":"6과 8의 최소공배수는 24라 48보다 작은 공통분모가 있으므로","correct":true},{"t":"두 분모를 곱한 수가 언제나 가장 작은 공통분모이므로","mis":"M5-1-u3-X08"}],"explanation":["6과 8의 공약수에 2가 있어요.","6과 8의 최소공배수는 24 — 6 × 8 = 48보다 작아요.","⟨5/6⟩ = ⟨20/24⟩, ⟨3/8⟩ = ⟨9/24⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#7','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',3,'match','auto','두 분수를 최소공배수로 통분할 때의 공통분모를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C4","difficulty":3,"kind":"match","stem":"두 분수를 최소공배수로 통분할 때의 공통분모를 이으세요.","pairs":[{"l":"⟨1/4⟩, ⟨1/6⟩","r":"12"},{"l":"⟨1/6⟩, ⟨1/9⟩","r":"18"},{"l":"⟨1/4⟩, ⟨1/10⟩","r":"20"}],"mis":"M5-1-u3-X08","explanation":["4와 6의 최소공배수는 12, 6과 9의 최소공배수는 18이에요.","4와 10의 최소공배수는 20이에요.","두 분모의 곱(24, 54, 40)보다 작은 공통분모예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 분수를 최소공배수로 통분할 때의 공통분모를 이으세요.","pairs":[{"l":"⟨1/6⟩, ⟨1/8⟩","r":"24"},{"l":"⟨1/9⟩, ⟨1/12⟩","r":"36"},{"l":"⟨1/10⟩, ⟨1/15⟩","r":"30"}],"explanation":["6과 8의 최소공배수는 24, 9와 12의 최소공배수는 36이에요.","10과 15의 최소공배수는 30이에요.","두 분모의 곱(48, 108, 150)보다 작은 공통분모예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#8','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',4,'sa','auto','⟨1/4⟩, ⟨5/6⟩, ⟨3/8⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u3-C4","difficulty":4,"kind":"sa","stem":"⟨1/4⟩, ⟨5/6⟩, ⟨3/8⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["세 분모 4, 6, 8의 최소공배수는 24예요.","⟨1/4⟩ = ⟨6/24⟩, ⟨5/6⟩ = ⟨20/24⟩, ⟨3/8⟩ = ⟨9/24⟩예요.","분자의 합은 6 + 20 + 9 = 35예요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩, ⟨3/4⟩, ⟨5/6⟩를 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["세 분모 3, 4, 6의 최소공배수는 12예요.","⟨1/3⟩ = ⟨4/12⟩, ⟨3/4⟩ = ⟨9/12⟩, ⟨5/6⟩ = ⟨10/12⟩이에요.","분자의 합은 4 + 9 + 10 = 23이에요."]},{"stem":"⟨1/6⟩, ⟨4/9⟩, ⟨1/2⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["세 분모 6, 9, 2의 최소공배수는 18이에요.","⟨1/6⟩ = ⟨3/18⟩, ⟨4/9⟩ = ⟨8/18⟩, ⟨1/2⟩ = ⟨9/18⟩예요.","분자의 합은 3 + 8 + 9 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#9','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',4,'essay','teacher','⟨1/6⟩을 분모가 30인 분수로 바꿀 때 분자도 함께 바꿔야 하는 까닭을 조각의 크기와 개수로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C4","difficulty":4,"kind":"essay","stem":"⟨1/6⟩을 분모가 30인 분수로 바꿀 때 분자도 함께 바꿔야 하는 까닭을 조각의 크기와 개수로 설명하세요.","answer_guide":{"answer":"예: 분모를 6에서 30으로 바꾸면 6 × 5 = 30이라 조각이 5배 잘아진다. 같은 양을 나타내려면 조각 개수도 5배가 되어야 하므로 분자도 1 × 5 = 5로 바꾸어 ⟨5/30⟩가 된다. 분모만 바꾸면 ⟨1/30⟩이 되어 양이 줄어든다.","scoring_points":["분모를 5배 하면 조각이 5배 잘아진다고 썼는가","분자도 5배 해야 양이 같다고 썼는가","⟨1/6⟩ = ⟨5/30⟩를 바르게 썼는가"]},"explanation":["6 × 5 = 30 — 조각이 5배 잘아져요.","조각 개수도 5배 — 1 × 5 = 5.","⟨1/6⟩ = ⟨5/30⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L04_challenge#10','math',5,1,'u3','L04','g5_1_math_u3_L04_challenge','lesson_challenge','M5-1-u3-C4',4,'essay','teacher','⟨5/8⟩와 ⟨7/12⟩을 두 분모의 곱으로 통분한 것과 최소공배수로 통분한 것을 모두 쓰고, 각 방법의 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C4","difficulty":4,"kind":"essay","stem":"⟨5/8⟩와 ⟨7/12⟩을 두 분모의 곱으로 통분한 것과 최소공배수로 통분한 것을 모두 쓰고, 각 방법의 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 두 분모의 곱 96으로 통분하면 ⟨60/96⟩, ⟨56/96⟩이고, 최소공배수 24로 통분하면 ⟨15/24⟩, ⟨14/24⟩이다. 곱으로 하면 공통분모를 바로 구할 수 있어 쉽고, 최소공배수로 하면 수가 작아 계산이 간단하다.","scoring_points":["두 분모의 곱으로 바르게 통분했는가","최소공배수로 바르게 통분했는가","두 방법의 좋은 점을 하나씩 썼는가"]},"explanation":["8 × 12 = 96 — ⟨5/8⟩ = ⟨60/96⟩, ⟨7/12⟩ = ⟨56/96⟩이에요.","최소공배수 24 — ⟨5/8⟩ = ⟨15/24⟩, ⟨7/12⟩ = ⟨14/24⟩예요.","곱은 구하기 쉽고, 최소공배수는 수가 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#1','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',1,'mc','auto','⟨1/5⟩과 ⟨1/8⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],true,'{"seq":1,"concept":"M5-1-u3-C5","difficulty":1,"kind":"mc","stem":"⟨1/5⟩과 ⟨1/8⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/8⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 5칸과 8칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/5⟩ > ⟨1/8⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":1,"label":"⟨1/5⟩"},{"den":8,"num":1,"label":"⟨1/8⟩"}]},"variant_rule":{"alt":[{"stem":"⟨1/3⟩과 ⟨1/7⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/7⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 3칸과 7칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/3⟩ > ⟨1/7⟩이에요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"⟨1/3⟩"},{"den":7,"num":1,"label":"⟨1/7⟩"}]}},{"stem":"⟨1/9⟩과 ⟨1/6⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1/9⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 6칸과 9칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/6⟩ > ⟨1/9⟩이에요."],"asset":{"type":"fbar","bars":[{"den":9,"num":1,"label":"⟨1/9⟩"},{"den":6,"num":1,"label":"⟨1/6⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#2','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',1,'sa','auto','⟨5/8⟩와 ⟨7/12⟩을 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C5","difficulty":1,"kind":"sa","stem":"⟨5/8⟩와 ⟨7/12⟩을 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["공통분모는 두 분모 8과 12의 공배수예요.","공배수 중 가장 작은 것은 최소공배수 24예요.","⟨5/8⟩ = ⟨15/24⟩, ⟨7/12⟩ = ⟨14/24⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩와 ⟨1/6⟩을 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["공통분모는 두 분모 9와 6의 공배수예요.","공배수 중 가장 작은 것은 최소공배수 18이에요.","⟨2/9⟩ = ⟨4/18⟩, ⟨1/6⟩ = ⟨3/18⟩이에요."]},{"stem":"⟨3/10⟩과 ⟨4/15⟩를 통분할 때 공통분모가 될 수 있는 수 중 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["공통분모는 두 분모 10과 15의 공배수예요.","공배수 중 가장 작은 것은 최소공배수 30이에요.","⟨3/10⟩ = ⟨9/30⟩, ⟨4/15⟩ = ⟨8/30⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#3','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',1,'mc','auto','⟨3/5⟩과 ⟨5/9⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X09','M5-1-u3-X08']::text[],true,'{"seq":3,"concept":"M5-1-u3-C5","difficulty":1,"kind":"mc","stem":"⟨3/5⟩과 ⟨5/9⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨5/9⟩","mis":"M5-1-u3-X09"},{"t":"두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["공통분모 45로 나타내면 ⟨3/5⟩ = ⟨27/45⟩, ⟨5/9⟩ = ⟨25/45⟩예요.","분자를 견주면 ⟨27/45⟩ > ⟨25/45⟩예요.","그래서 ⟨3/5⟩ > ⟨5/9⟩ — 더 큰 분수는 ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩와 ⟨5/8⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-1-u3-X09"},{"t":"두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["공통분모 24로 나타내면 ⟨2/3⟩ = ⟨16/24⟩, ⟨5/8⟩ = ⟨15/24⟩예요.","분자를 견주면 ⟨16/24⟩ > ⟨15/24⟩예요.","그래서 ⟨2/3⟩ > ⟨5/8⟩ — 더 큰 분수는 ⟨2/3⟩예요."]},{"stem":"⟨3/4⟩과 ⟨7/9⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨3/4⟩","mis":"M5-1-u3-X09"},{"t":"두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["공통분모 36으로 나타내면 ⟨3/4⟩ = ⟨27/36⟩, ⟨7/9⟩ = ⟨28/36⟩이에요.","분자를 견주면 ⟨28/36⟩ > ⟨27/36⟩이에요.","그래서 ⟨7/9⟩ > ⟨3/4⟩ — 더 큰 분수는 ⟨7/9⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#4','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',1,'mc','auto','두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#5','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',2,'mc','auto','분수의 크기 비교에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09']::text[],true,'{"seq":5,"concept":"M5-1-u3-C5","difficulty":2,"kind":"mc","stem":"분수의 크기 비교에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"분모가 크다고 분수가 큰 것은 아니다","correct":true},{"t":"분모가 크면 분수도 언제나 크다","mis":"M5-1-u3-X11"},{"t":"분자가 크면 언제나 분수가 크다","mis":"M5-1-u3-X09"},{"t":"분모와 분자를 따로 견주면 된다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/5⟩ > ⟨1/8⟩ — 분모가 커도 분수는 작을 수 있어요.","⟨3/5⟩ > ⟨5/9⟩ — 분자가 커도 분수는 작을 수 있어요.","분모가 다르면 통분해서 같은 조각으로 견주어요."],"variant_rule":{"alt":[{"stem":"분모가 다른 두 분수를 견주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"통분하여 분자를 견준다","correct":true},{"t":"분자만 견준다","mis":"M5-1-u3-X09"},{"t":"분모만 견준다","mis":"M5-1-u3-X11"},{"t":"분모와 분자의 차를 견준다","mis":"M5-1-u3-X09"}],"explanation":["분모가 다르면 조각의 크기가 달라요.","통분하면 조각의 크기가 같아져요.","그다음 분자, 곧 조각 개수를 견주면 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#6','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',2,'sa','auto','⟨2/3⟩, ⟨3/4⟩, ⟨5/8⟩ 중 가장 큰 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u3-C5","difficulty":2,"kind":"sa","stem":"⟨2/3⟩, ⟨3/4⟩, ⟨5/8⟩ 중 가장 큰 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["공통분모 24로 나타내면 ⟨2/3⟩ = ⟨16/24⟩, ⟨3/4⟩ = ⟨18/24⟩, ⟨5/8⟩ = ⟨15/24⟩예요.","분자가 가장 큰 것은 ⟨18/24⟩이에요.","가장 큰 분수는 ⟨3/4⟩ — 분자는 3이에요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩, ⟨7/9⟩, ⟨3/4⟩ 중 가장 큰 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["공통분모 36으로 나타내면 ⟨5/6⟩ = ⟨30/36⟩, ⟨7/9⟩ = ⟨28/36⟩, ⟨3/4⟩ = ⟨27/36⟩이에요.","분자가 가장 큰 것은 ⟨30/36⟩이에요.","가장 큰 분수는 ⟨5/6⟩ — 분자는 5예요."]},{"stem":"⟨3/5⟩, ⟨7/10⟩, ⟨2/3⟩ 중 가장 큰 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["공통분모 30으로 나타내면 ⟨3/5⟩ = ⟨18/30⟩, ⟨7/10⟩ = ⟨21/30⟩, ⟨2/3⟩ = ⟨20/30⟩이에요.","분자가 가장 큰 것은 ⟨21/30⟩이에요.","가장 큰 분수는 ⟨7/10⟩ — 분자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#7','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',2,'sa','auto','⟨4/7⟩, ⟨3/8⟩, ⟨5/12⟩ 중 ⟨1/2⟩보다 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C5","difficulty":2,"kind":"sa","stem":"⟨4/7⟩, ⟨3/8⟩, ⟨5/12⟩ 중 ⟨1/2⟩보다 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분자를 2배 해서 분모와 견주면 ⟨1/2⟩보다 큰지 작은지 알 수 있어요.","4 × 2 = 8이 7보다 커서 ⟨4/7⟩ > ⟨1/2⟩ · 3 × 2 = 6이 8보다 작아서 ⟨3/8⟩ < ⟨1/2⟩ · 5 × 2 = 10이 12보다 작아서 ⟨5/12⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 분수는 ⟨4/7⟩ — 분모는 7이에요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩, ⟨5/11⟩, ⟨7/12⟩ 중 ⟨1/2⟩보다 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["분자를 2배 해서 분모와 견주면 ⟨1/2⟩보다 큰지 작은지 알 수 있어요.","4 × 2 = 8이 9보다 작아서 ⟨4/9⟩ < ⟨1/2⟩ · 5 × 2 = 10이 11보다 작아서 ⟨5/11⟩ < ⟨1/2⟩ · 7 × 2 = 14가 12보다 커서 ⟨7/12⟩ > ⟨1/2⟩.","⟨1/2⟩보다 큰 분수는 ⟨7/12⟩ — 분모는 12예요."]},{"stem":"⟨2/5⟩, ⟨5/8⟩, ⟨6/13⟩ 중 ⟨1/2⟩보다 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분자를 2배 해서 분모와 견주면 ⟨1/2⟩보다 큰지 작은지 알 수 있어요.","2 × 2 = 4가 5보다 작아서 ⟨2/5⟩ < ⟨1/2⟩ · 5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩ · 6 × 2 = 12가 13보다 작아서 ⟨6/13⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 분수는 ⟨5/8⟩ — 분모는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#8','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',2,'mc','auto','⟨7/10⟩, ⟨2/3⟩, ⟨3/4⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],true,'{"seq":8,"concept":"M5-1-u3-C5","difficulty":2,"kind":"mc","stem":"⟨7/10⟩, ⟨2/3⟩, ⟨3/4⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩, ⟨7/10⟩, ⟨2/3⟩","correct":true},{"t":"⟨2/3⟩, ⟨7/10⟩, ⟨3/4⟩","mis":"M5-1-u3-X14"},{"t":"⟨7/10⟩, ⟨3/4⟩, ⟨2/3⟩","mis":"M5-1-u3-X09"},{"t":"⟨7/10⟩, ⟨2/3⟩, ⟨3/4⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 60으로 나타내면 ⟨7/10⟩ = ⟨42/60⟩, ⟨2/3⟩ = ⟨40/60⟩, ⟨3/4⟩ = ⟨45/60⟩예요.","견주면 ⟨45/60⟩ > ⟨42/60⟩ > ⟨40/60⟩이에요.","그래서 큰 것부터 쓰면 ⟨3/4⟩, ⟨7/10⟩, ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩, ⟨4/5⟩, ⟨7/9⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩, ⟨4/5⟩, ⟨7/9⟩","correct":true},{"t":"⟨7/9⟩, ⟨4/5⟩, ⟨5/6⟩","mis":"M5-1-u3-X14"},{"t":"⟨7/9⟩, ⟨5/6⟩, ⟨4/5⟩","mis":"M5-1-u3-X09"},{"t":"⟨5/6⟩, ⟨7/9⟩, ⟨4/5⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 90으로 나타내면 ⟨5/6⟩ = ⟨75/90⟩, ⟨4/5⟩ = ⟨72/90⟩, ⟨7/9⟩ = ⟨70/90⟩이에요.","견주면 ⟨75/90⟩ > ⟨72/90⟩ > ⟨70/90⟩이에요.","그래서 큰 것부터 쓰면 ⟨5/6⟩, ⟨4/5⟩, ⟨7/9⟩이에요."]},{"stem":"⟨3/8⟩, ⟨2/5⟩, ⟨1/3⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩, ⟨3/8⟩, ⟨1/3⟩","correct":true},{"t":"⟨1/3⟩, ⟨3/8⟩, ⟨2/5⟩","mis":"M5-1-u3-X14"},{"t":"⟨3/8⟩, ⟨2/5⟩, ⟨1/3⟩","mis":"M5-1-u3-X09"},{"t":"⟨3/8⟩, ⟨1/3⟩, ⟨2/5⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 120으로 나타내면 ⟨3/8⟩ = ⟨45/120⟩, ⟨2/5⟩ = ⟨48/120⟩, ⟨1/3⟩ = ⟨40/120⟩이에요.","견주면 ⟨48/120⟩ > ⟨45/120⟩ > ⟨40/120⟩이에요.","그래서 큰 것부터 쓰면 ⟨2/5⟩, ⟨3/8⟩, ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#9','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',2,'ox','auto','⟨4/9⟩는 ⟨1/2⟩보다 작아요.',ARRAY['M5-1-u3-X11']::text[],true,'{"seq":9,"concept":"M5-1-u3-C5","difficulty":2,"kind":"ox","stem":"⟨4/9⟩는 ⟨1/2⟩보다 작아요.","answer":"O","reason_options":[{"t":"4 × 2 = 8이 9보다 작아 분자가 분모의 절반보다 작으므로","correct":true},{"t":"분모 9가 ⟨1/2⟩의 분모 2보다 크므로","mis":"M5-1-u3-X11"}],"mis":"M5-1-u3-X11","explanation":["분자를 2배 해서 분모와 견주어요.","4 × 2 = 8 — 9보다 작아요.","그래서 ⟨4/9⟩ < ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/8⟩는 ⟨1/2⟩보다 작아요.","answer":"X","reason_options":[{"t":"5 × 2 = 10이 8보다 커서 분자가 분모의 절반보다 크므로","correct":true},{"t":"분모 8이 2보다 크면 언제나 ⟨1/2⟩보다 작으므로","mis":"M5-1-u3-X11"}],"explanation":["분자를 2배 해서 분모와 견주어요.","5 × 2 = 10 — 8보다 커요.","그래서 ⟨5/8⟩ > ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_basic#10','math',5,1,'u3','L05','g5_1_math_u3_L05_basic','lesson_basic','M5-1-u3-C5',3,'mc','auto','⟨1/2⟩을 기준으로 삼으면 통분하지 않고도 바로 크기를 알 수 있는 두 분수는 어느 것인가요?',ARRAY['M5-1-u3-X10']::text[],true,'{"seq":10,"concept":"M5-1-u3-C5","difficulty":3,"kind":"mc","stem":"⟨1/2⟩을 기준으로 삼으면 통분하지 않고도 바로 크기를 알 수 있는 두 분수는 어느 것인가요?","options":[{"t":"⟨4/9⟩와 ⟨5/8⟩","correct":true},{"t":"⟨3/7⟩과 ⟨5/11⟩","mis":"M5-1-u3-X10"},{"t":"⟨2/5⟩와 ⟨3/7⟩","mis":"M5-1-u3-X10"},{"t":"⟨7/8⟩과 ⟨9/10⟩","mis":"M5-1-u3-X10"}],"explanation":["4 × 2 = 8이 9보다 작아서 ⟨4/9⟩ < ⟨1/2⟩ · 5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩.","두 분수가 ⟨1/2⟩을 사이에 두고 갈리면 바로 견줄 수 있어요.","다른 짝은 두 분수가 ⟨1/2⟩의 같은 쪽에 있어 기준만으로는 가릴 수 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. ⟨1/2⟩을 기준으로 삼으면 통분하지 않고도 바로 크기를 알 수 있는 두 분수는 어느 것인가요?","options":[{"t":"⟨5/12⟩와 ⟨4/7⟩","correct":true},{"t":"⟨5/9⟩와 ⟨4/7⟩","mis":"M5-1-u3-X10"},{"t":"⟨3/8⟩과 ⟨2/5⟩","mis":"M5-1-u3-X10"},{"t":"⟨5/6⟩와 ⟨6/7⟩","mis":"M5-1-u3-X10"}],"explanation":["5 × 2 = 10이 12보다 작아서 ⟨5/12⟩ < ⟨1/2⟩ · 4 × 2 = 8이 7보다 커서 ⟨4/7⟩ > ⟨1/2⟩.","두 분수가 ⟨1/2⟩을 사이에 두고 갈리면 바로 견줄 수 있어요.","다른 짝은 두 분수가 ⟨1/2⟩의 같은 쪽에 있어 기준만으로는 가릴 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#1','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',2,'mc','auto','⟨3/7⟩과 ⟨3/10⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],true,'{"seq":1,"concept":"M5-1-u3-C5","difficulty":2,"kind":"mc","stem":"⟨3/7⟩과 ⟨3/10⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 3개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨3/7⟩ > ⟨3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/9⟩와 ⟨5/6⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨5/9⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 5개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨5/6⟩ > ⟨5/9⟩예요."]},{"stem":"⟨4/11⟩와 ⟨4/9⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨4/11⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 4개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨4/9⟩ > ⟨4/11⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#2','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',2,'sa','auto','⟨□/12⟩가 ⟨2/3⟩보다 크고 1보다 작은 분수가 되게 하는 자연수 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C5","difficulty":2,"kind":"sa","stem":"⟨□/12⟩가 ⟨2/3⟩보다 크고 1보다 작은 분수가 되게 하는 자연수 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["분모를 12로 맞추면 ⟨2/3⟩ = ⟨8/12⟩, 1 = ⟨12/12⟩예요.","□는 8보다 크고 12보다 작은 수 — 9, 10, 11이에요.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨□/10⟩가 ⟨1/2⟩보다 크고 ⟨4/5⟩보다 작은 분수가 되게 하는 자연수 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2","2개"],"explanation":["분모를 10으로 맞추면 ⟨1/2⟩ = ⟨5/10⟩, ⟨4/5⟩ = ⟨8/10⟩이에요.","□는 5보다 크고 8보다 작은 수 — 6, 7이에요.","모두 2개예요."]},{"stem":"⟨□/24⟩가 ⟨3/8⟩보다 크고 ⟨2/3⟩보다 작은 분수가 되게 하는 자연수 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6","6개"],"explanation":["분모를 24로 맞추면 ⟨3/8⟩ = ⟨9/24⟩, ⟨2/3⟩ = ⟨16/24⟩이에요.","□는 9보다 크고 16보다 작은 수 — 10, 11, 12, 13, 14, 15예요.","모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#3','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',3,'mc','auto','⟨5/6⟩, ⟨3/4⟩, ⟨7/9⟩ 중 가장 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X09','M5-1-u3-X13']::text[],true,'{"seq":3,"concept":"M5-1-u3-C5","difficulty":3,"kind":"mc","stem":"⟨5/6⟩, ⟨3/4⟩, ⟨7/9⟩ 중 가장 큰 분수는 어느 것인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-1-u3-X09"},{"t":"⟨3/4⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["공통분모 36으로 나타내면 ⟨5/6⟩ = ⟨30/36⟩, ⟨3/4⟩ = ⟨27/36⟩, ⟨7/9⟩ = ⟨28/36⟩이에요.","분자를 견주면 ⟨30/36⟩ > ⟨28/36⟩ > ⟨27/36⟩이에요.","그래서 가장 큰 분수는 ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4/5⟩, ⟨7/10⟩, ⟨3/4⟩ 중 가장 큰 분수는 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨7/10⟩","mis":"M5-1-u3-X09"},{"t":"⟨3/4⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["공통분모 20으로 나타내면 ⟨4/5⟩ = ⟨16/20⟩, ⟨7/10⟩ = ⟨14/20⟩, ⟨3/4⟩ = ⟨15/20⟩예요.","분자를 견주면 ⟨16/20⟩ > ⟨15/20⟩ > ⟨14/20⟩예요.","그래서 가장 큰 분수는 ⟨4/5⟩예요."]},{"stem":"⟨2/3⟩, ⟨5/8⟩, ⟨7/12⟩ 중 가장 큰 분수는 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u3-X09"},{"t":"⟨5/8⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["공통분모 24로 나타내면 ⟨2/3⟩ = ⟨16/24⟩, ⟨5/8⟩ = ⟨15/24⟩, ⟨7/12⟩ = ⟨14/24⟩예요.","분자를 견주면 ⟨16/24⟩ > ⟨15/24⟩ > ⟨14/24⟩예요.","그래서 가장 큰 분수는 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#4','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',3,'sa','auto','1부터 9까지의 수 중에서 ⟨□/8⟩ < ⟨3/5⟩이 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C5","difficulty":3,"kind":"sa","stem":"1부터 9까지의 수 중에서 ⟨□/8⟩ < ⟨3/5⟩이 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩이고, ⟨□/8⟩의 분자는 □ × 5가 돼요.","□ × 5가 24보다 작아야 해요 — □는 1, 2, 3, 4.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"1부터 9까지의 수 중에서 ⟨□/6⟩ > ⟨3/4⟩이 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["12로 통분하면 ⟨3/4⟩ = ⟨9/12⟩이고, ⟨□/6⟩의 분자는 □ × 2가 돼요.","□ × 2가 9보다 커야 해요 — □는 5, 6, 7, 8, 9.","모두 5개예요."]},{"stem":"1부터 9까지의 수 중에서 ⟨□/9⟩ < ⟨2/3⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["분모를 9로 맞추면 ⟨2/3⟩ = ⟨6/9⟩이에요.","□가 6보다 작아야 해요 — □는 1, 2, 3, 4, 5.","모두 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#5','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',3,'error','auto','⟨3/5⟩과 ⟨4/7⟩의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X09','M5-1-u3-X14']::text[],true,'{"seq":5,"concept":"M5-1-u3-C5","difficulty":3,"kind":"error","stem":"⟨3/5⟩과 ⟨4/7⟩의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「분자 4가 3보다 크니까 ⟨4/7⟩가 더 커.」","correct":true,"mis_target":"M5-1-u3-X09"},{"t":"다은 — 「35로 통분하면 ⟨21/35⟩, ⟨20/35⟩ — ⟨3/5⟩이 더 커.」","mis":"M5-1-u3-X14"},{"t":"이안 — 「둘 다 ⟨1/2⟩보다 크니까 ⟨1/2⟩만으로는 못 가려.」","mis":"M5-1-u3-X14"}],"explanation":["35로 통분하면 ⟨3/5⟩ = ⟨21/35⟩, ⟨4/7⟩ = ⟨20/35⟩이에요.","⟨3/5⟩이 더 커요.","준서는 분모나 분자 하나만 보고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"⟨5/8⟩와 ⟨2/3⟩의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「분모 8이 3보다 크니까 ⟨5/8⟩가 더 커.」","correct":true,"mis_target":"M5-1-u3-X11"},{"t":"서아 — 「24로 통분하면 ⟨15/24⟩, ⟨16/24⟩ — ⟨2/3⟩가 더 커.」","mis":"M5-1-u3-X14"},{"t":"지율 — 「둘 다 ⟨1/2⟩보다 크니까 ⟨1/2⟩만으로는 못 가려.」","mis":"M5-1-u3-X14"}],"explanation":["24로 통분하면 ⟨5/8⟩ = ⟨15/24⟩, ⟨2/3⟩ = ⟨16/24⟩이에요.","⟨2/3⟩가 더 커요.","하준은 분모나 분자 하나만 보고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#6','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',3,'sa','auto','⟨5/11⟩, ⟨7/12⟩, ⟨4/9⟩, ⟨6/11⟩ 중 ⟨1/2⟩보다 큰 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u3-C5","difficulty":3,"kind":"sa","stem":"⟨5/11⟩, ⟨7/12⟩, ⟨4/9⟩, ⟨6/11⟩ 중 ⟨1/2⟩보다 큰 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2","2개"],"explanation":["분자를 2배 해서 분모보다 크면 ⟨1/2⟩보다 커요.","5 × 2 = 10이 11보다 작아서 ⟨5/11⟩ < ⟨1/2⟩ · 7 × 2 = 14가 12보다 커서 ⟨7/12⟩ > ⟨1/2⟩ · 4 × 2 = 8이 9보다 작아서 ⟨4/9⟩ < ⟨1/2⟩ · 6 × 2 = 12가 11보다 커서 ⟨6/11⟩ > ⟨1/2⟩.","⟨1/2⟩보다 큰 분수는 ⟨7/12⟩, ⟨6/11⟩ — 2개예요."],"variant_rule":{"alt":[{"stem":"⟨5/8⟩, ⟨6/13⟩, ⟨7/10⟩, ⟨9/16⟩, ⟨3/7⟩ 중 ⟨1/2⟩보다 큰 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["분자를 2배 해서 분모보다 크면 ⟨1/2⟩보다 커요.","5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩ · 6 × 2 = 12가 13보다 작아서 ⟨6/13⟩ < ⟨1/2⟩ · 7 × 2 = 14가 10보다 커서 ⟨7/10⟩ > ⟨1/2⟩ · 9 × 2 = 18이 16보다 커서 ⟨9/16⟩ > ⟨1/2⟩ · 3 × 2 = 6이 7보다 작아서 ⟨3/7⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 분수는 ⟨5/8⟩, ⟨7/10⟩, ⟨9/16⟩ — 3개예요."]},{"stem":"⟨7/13⟩, ⟨5/9⟩, ⟨6/11⟩, ⟨8/15⟩, ⟨3/8⟩ 중 ⟨1/2⟩보다 큰 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["분자를 2배 해서 분모보다 크면 ⟨1/2⟩보다 커요.","7 × 2 = 14가 13보다 커서 ⟨7/13⟩ > ⟨1/2⟩ · 5 × 2 = 10이 9보다 커서 ⟨5/9⟩ > ⟨1/2⟩ · 6 × 2 = 12가 11보다 커서 ⟨6/11⟩ > ⟨1/2⟩ · 8 × 2 = 16이 15보다 커서 ⟨8/15⟩ > ⟨1/2⟩ · 3 × 2 = 6이 8보다 작아서 ⟨3/8⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 분수는 ⟨7/13⟩, ⟨5/9⟩, ⟨6/11⟩, ⟨8/15⟩ — 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#7','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',3,'ox','auto','분모와 분자가 모두 더 큰 분수가 언제나 더 커요.',ARRAY['M5-1-u3-X09']::text[],true,'{"seq":7,"concept":"M5-1-u3-C5","difficulty":3,"kind":"ox","stem":"분모와 분자가 모두 더 큰 분수가 언제나 더 커요.","answer":"X","reason_options":[{"t":"⟨3/4⟩과 ⟨4/7⟩처럼 분모와 분자가 모두 커도 더 작은 분수가 있으므로","correct":true},{"t":"분모와 분자가 커지면 조각이 많아지므로","mis":"M5-1-u3-X09"}],"mis":"M5-1-u3-X09","explanation":["28로 통분하면 ⟨3/4⟩ = ⟨21/28⟩, ⟨4/7⟩ = ⟨16/28⟩이에요.","⟨4/7⟩는 분모와 분자가 모두 더 크지만 ⟨3/4⟩ > ⟨4/7⟩예요.","분모와 분자를 따로 보지 말고 통분해서 견주어요."],"variant_rule":{"alt":[{"stem":"분모가 같으면 분자가 큰 분수가 더 커요.","answer":"O","reason_options":[{"t":"조각의 크기가 같으니 조각 개수가 많은 쪽이 크므로","correct":true},{"t":"분자가 큰 분수는 분모와 상관없이 언제나 크므로","mis":"M5-1-u3-X09"}],"explanation":["분모가 같으면 조각 하나의 크기가 같아요.","분자는 조각의 개수예요.","예: ⟨5/9⟩ > ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#8','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',4,'mc','auto','⟨2/5⟩, ⟨3/8⟩, ⟨5/12⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],true,'{"seq":8,"concept":"M5-1-u3-C5","difficulty":4,"kind":"mc","stem":"⟨2/5⟩, ⟨3/8⟩, ⟨5/12⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩, ⟨2/5⟩, ⟨5/12⟩","correct":true},{"t":"⟨5/12⟩, ⟨2/5⟩, ⟨3/8⟩","mis":"M5-1-u3-X14"},{"t":"⟨2/5⟩, ⟨3/8⟩, ⟨5/12⟩","mis":"M5-1-u3-X09"},{"t":"⟨2/5⟩, ⟨5/12⟩, ⟨3/8⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 120으로 나타내면 ⟨2/5⟩ = ⟨48/120⟩, ⟨3/8⟩ = ⟨45/120⟩, ⟨5/12⟩ = ⟨50/120⟩이에요.","견주면 ⟨45/120⟩ < ⟨48/120⟩ < ⟨50/120⟩이에요.","그래서 작은 것부터 쓰면 ⟨3/8⟩, ⟨2/5⟩, ⟨5/12⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩, ⟨7/9⟩, ⟨11/12⟩을 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨7/9⟩, ⟨5/6⟩, ⟨11/12⟩","correct":true},{"t":"⟨11/12⟩, ⟨5/6⟩, ⟨7/9⟩","mis":"M5-1-u3-X14"},{"t":"⟨5/6⟩, ⟨7/9⟩, ⟨11/12⟩","mis":"M5-1-u3-X09"},{"t":"⟨5/6⟩, ⟨11/12⟩, ⟨7/9⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 36으로 나타내면 ⟨5/6⟩ = ⟨30/36⟩, ⟨7/9⟩ = ⟨28/36⟩, ⟨11/12⟩ = ⟨33/36⟩이에요.","견주면 ⟨28/36⟩ < ⟨30/36⟩ < ⟨33/36⟩이에요.","그래서 작은 것부터 쓰면 ⟨7/9⟩, ⟨5/6⟩, ⟨11/12⟩이에요."]},{"stem":"⟨5/6⟩, ⟨7/8⟩, ⟨4/5⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩, ⟨5/6⟩, ⟨7/8⟩","correct":true},{"t":"⟨7/8⟩, ⟨5/6⟩, ⟨4/5⟩","mis":"M5-1-u3-X14"},{"t":"⟨5/6⟩, ⟨7/8⟩, ⟨4/5⟩","mis":"M5-1-u3-X13"},{"t":"⟨5/6⟩, ⟨4/5⟩, ⟨7/8⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 120으로 나타내면 ⟨5/6⟩ = ⟨100/120⟩, ⟨7/8⟩ = ⟨105/120⟩, ⟨4/5⟩ = ⟨96/120⟩이에요.","견주면 ⟨96/120⟩ < ⟨100/120⟩ < ⟨105/120⟩예요.","그래서 작은 것부터 쓰면 ⟨4/5⟩, ⟨5/6⟩, ⟨7/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#9','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',4,'sa','auto','⟨□/7⟩는 ⟨1/3⟩보다 크고 ⟨5/6⟩보다 작아요. □에 들어갈 수 있는 자연수를 모두 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u3-C5","difficulty":4,"kind":"sa","stem":"⟨□/7⟩는 ⟨1/3⟩보다 크고 ⟨5/6⟩보다 작아요. □에 들어갈 수 있는 자연수를 모두 더하면 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["42로 통분하면 ⟨1/3⟩ = ⟨14/42⟩, ⟨5/6⟩ = ⟨35/42⟩이고, ⟨□/7⟩의 분자는 □ × 6이 돼요.","□ × 6이 14보다 크고 35보다 작은 □는 3, 4, 5예요.","모두 더하면 3 + 4 + 5 = 12예요."],"variant_rule":{"alt":[{"stem":"⟨□/9⟩는 ⟨1/3⟩보다 크고 ⟨3/4⟩보다 작아요. □에 들어갈 수 있는 자연수를 모두 더하면 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["36으로 통분하면 ⟨1/3⟩ = ⟨12/36⟩, ⟨3/4⟩ = ⟨27/36⟩이고, ⟨□/9⟩의 분자는 □ × 4가 돼요.","□ × 4가 12보다 크고 27보다 작은 □는 4, 5, 6이에요.","모두 더하면 4 + 5 + 6 = 15예요."]},{"stem":"⟨□/8⟩는 ⟨1/4⟩보다 크고 ⟨4/5⟩보다 작아요. □에 들어갈 수 있는 자연수를 모두 더하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["40으로 통분하면 ⟨1/4⟩ = ⟨10/40⟩, ⟨4/5⟩ = ⟨32/40⟩이고, ⟨□/8⟩의 분자는 □ × 5가 돼요.","□ × 5가 10보다 크고 32보다 작은 □는 3, 4, 5, 6이에요.","모두 더하면 3 + 4 + 5 + 6 = 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L05_challenge#10','math',5,1,'u3','L05','g5_1_math_u3_L05_challenge','lesson_challenge','M5-1-u3-C5',4,'essay','teacher','⟨4/9⟩와 ⟨5/8⟩의 크기를 통분하지 않고 비교하는 방법을 설명하고, 어느 것이 더 큰지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C5","difficulty":4,"kind":"essay","stem":"⟨4/9⟩와 ⟨5/8⟩의 크기를 통분하지 않고 비교하는 방법을 설명하고, 어느 것이 더 큰지 쓰세요.","answer_guide":{"answer":"예: ⟨1/2⟩을 기준으로 삼는다. ⟨4/9⟩는 분자 4를 2배 한 8이 분모 9보다 작아서 ⟨1/2⟩보다 작고, ⟨5/8⟩는 분자 5를 2배 한 10이 분모 8보다 커서 ⟨1/2⟩보다 크다. 그래서 ⟨5/8⟩가 더 크다.","scoring_points":["⟨1/2⟩을 기준으로 삼았는가","두 분수가 ⟨1/2⟩보다 큰지 작은지 까닭과 함께 썼는가","⟨5/8⟩가 더 크다고 맺었는가"]},"explanation":["4 × 2 = 8 — 9보다 작아 ⟨4/9⟩ < ⟨1/2⟩.","5 × 2 = 10 — 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩.","그래서 ⟨4/9⟩ < ⟨5/8⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#1','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',1,'mc','auto','⟨3/5⟩을 소수로 나타내면 얼마인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X13']::text[],true,'{"seq":1,"concept":"M5-1-u3-C6","difficulty":1,"kind":"mc","stem":"⟨3/5⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.35","mis":"M5-1-u3-X12"},{"t":"0.3","mis":"M5-1-u3-X12"},{"t":"0.5","mis":"M5-1-u3-X13"}],"explanation":["분모를 10으로 만들어요 — 분모와 분자에 2를 곱해요.","⟨3/5⟩ = ⟨6/10⟩이에요.","⟨6/10⟩ = 0.6 — 소수로 0.6이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"0.14","mis":"M5-1-u3-X12"},{"t":"0.4","mis":"M5-1-u3-X12"},{"t":"0.75","mis":"M5-1-u3-X13"}],"explanation":["분모를 100으로 만들어요 — 분모와 분자에 25를 곱해요.","⟨1/4⟩ = ⟨25/100⟩예요.","⟨25/100⟩ = 0.25 — 소수로 0.25예요."]},{"stem":"⟨1/2⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"0.12","mis":"M5-1-u3-X12"},{"t":"0.2","mis":"M5-1-u3-X12"},{"t":"0.25","mis":"M5-1-u3-X13"}],"explanation":["분모를 10으로 만들어요 — 분모와 분자에 5를 곱해요.","⟨1/2⟩ = ⟨5/10⟩예요.","⟨5/10⟩ = 0.5 — 소수로 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#2','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',1,'sa','auto','0.4를 분모가 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C6","difficulty":1,"kind":"sa","stem":"0.4를 분모가 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.4는 소수 한 자리 수예요.","소수 한 자리 수는 분모가 10인 분수로 나타내요.","0.4 = ⟨4/10⟩ — 분자는 4예요."],"variant_rule":{"alt":[{"stem":"0.9를 분모가 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["0.9는 소수 한 자리 수예요.","소수 한 자리 수는 분모가 10인 분수로 나타내요.","0.9 = ⟨9/10⟩ — 분자는 9예요."]},{"stem":"0.6을 분모가 10인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["0.6은 소수 한 자리 수예요.","소수 한 자리 수는 분모가 10인 분수로 나타내요.","0.6 = ⟨6/10⟩ — 분자는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#3','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',1,'mc','auto','0.7과 ⟨3/5⟩ 중 더 큰 수는 어느 것인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],true,'{"seq":3,"concept":"M5-1-u3-C6","difficulty":1,"kind":"mc","stem":"0.7과 ⟨3/5⟩ 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.7","correct":true},{"t":"⟨3/5⟩","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨3/5⟩ = 0.6.","0.7 > 0.6이에요.","그래서 더 큰 수는 0.7이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩과 0.8 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.8","correct":true},{"t":"⟨3/4⟩","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨3/4⟩ = 0.75.","0.8 > 0.75예요.","그래서 더 큰 수는 0.8이에요."]},{"stem":"⟨2/5⟩와 0.3 중 더 큰 수는 어느 것인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"0.3","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨2/5⟩ = 0.4.","0.4 > 0.3이에요.","그래서 더 큰 수는 ⟨2/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#4','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',1,'sa','auto','0.25를 분모가 100인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C6","difficulty":1,"kind":"sa","stem":"0.25를 분모가 100인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["0.25는 소수 두 자리 수예요.","소수 두 자리 수는 분모가 100인 분수로 나타내요.","0.25 = ⟨25/100⟩ — 분자는 25예요."],"variant_rule":{"alt":[{"stem":"0.48을 분모가 100인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["0.48은 소수 두 자리 수예요.","소수 두 자리 수는 분모가 100인 분수로 나타내요.","0.48 = ⟨48/100⟩ — 분자는 48이에요."]},{"stem":"0.06을 분모가 100인 분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["0.06은 소수 두 자리 수예요.","소수 두 자리 수는 분모가 100인 분수로 나타내요.","0.06 = ⟨6/100⟩ — 분자는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#5','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',2,'mc','auto','⟨7/20⟩을 소수로 나타내면 얼마인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X13']::text[],true,'{"seq":5,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"⟨7/20⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"0.72","mis":"M5-1-u3-X12"},{"t":"0.27","mis":"M5-1-u3-X12"},{"t":"0.7","mis":"M5-1-u3-X13"}],"explanation":["분모를 100으로 만들어요 — 분모와 분자에 5를 곱해요.","⟨7/20⟩ = ⟨35/100⟩예요.","⟨35/100⟩ = 0.35 — 소수로 0.35예요."],"variant_rule":{"alt":[{"stem":"⟨9/25⟩를 소수로 나타내면 얼마인가요?","options":[{"t":"0.36","correct":true},{"t":"0.925","mis":"M5-1-u3-X12"},{"t":"3.6","mis":"M5-1-u3-X12"},{"t":"0.09","mis":"M5-1-u3-X12"}],"explanation":["분모를 100으로 만들어요 — 분모와 분자에 4를 곱해요.","⟨9/25⟩ = ⟨36/100⟩이에요.","⟨36/100⟩ = 0.36 — 소수로 0.36이에요."]},{"stem":"⟨3/50⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.06","correct":true},{"t":"0.6","mis":"M5-1-u3-X12"},{"t":"0.35","mis":"M5-1-u3-X12"},{"t":"0.03","mis":"M5-1-u3-X13"}],"explanation":["분모를 100으로 만들어요 — 분모와 분자에 2를 곱해요.","⟨3/50⟩ = ⟨6/100⟩이에요.","⟨6/100⟩ = 0.06 — 소수로 0.06이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#6','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',2,'mc','auto','0.45를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X12']::text[],true,'{"seq":6,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.45를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨45/100⟩","mis":"M5-1-u3-X05"},{"t":"⟨45/10⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/45⟩","mis":"M5-1-u3-X12"}],"explanation":["0.45 = ⟨45/100⟩예요 — 소수 두 자리 수라 분모가 100이에요.","45와 100의 최대공약수 5로 약분해요 — 45 ÷ 5 = 9, 100 ÷ 5 = 20.","⟨45/100⟩ = ⟨9/20⟩예요."],"variant_rule":{"alt":[{"stem":"0.6을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨6/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/100⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/6⟩","mis":"M5-1-u3-X12"}],"explanation":["0.6 = ⟨6/10⟩이에요 — 소수 한 자리 수라 분모가 10이에요.","6과 10의 최대공약수 2로 약분해요 — 6 ÷ 2 = 3, 10 ÷ 2 = 5.","⟨6/10⟩ = ⟨3/5⟩이에요."]},{"stem":"0.75를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨75/100⟩","mis":"M5-1-u3-X05"},{"t":"⟨75/10⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/75⟩","mis":"M5-1-u3-X12"}],"explanation":["0.75 = ⟨75/100⟩예요 — 소수 두 자리 수라 분모가 100이에요.","75와 100의 최대공약수 25로 약분해요 — 75 ÷ 25 = 3, 100 ÷ 25 = 4.","⟨75/100⟩ = ⟨3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#7','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',2,'sa','auto','0.8, ⟨3/4⟩, 0.65 중 가장 큰 수를 소수로 쓰면 0.□예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u3-C6","difficulty":2,"kind":"sa","stem":"0.8, ⟨3/4⟩, 0.65 중 가장 큰 수를 소수로 쓰면 0.□예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/4⟩ = 0.75.","가장 큰 수는 0.8이에요.","□에 알맞은 수는 8이에요."],"variant_rule":{"alt":[{"stem":"0.55, ⟨3/5⟩, 0.58 중 가장 큰 수를 소수로 쓰면 0.□예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/5⟩ = 0.6.","가장 큰 수는 0.6이에요.","□에 알맞은 수는 6이에요."]},{"stem":"⟨1/4⟩, 0.2, 0.3 중 가장 큰 수를 소수로 쓰면 0.□예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분수를 소수로 바꾸어요 — ⟨1/4⟩ = 0.25.","가장 큰 수는 0.3이에요.","□에 알맞은 수는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#8','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',2,'mc','auto','1.4와 ⟨6/5⟩을 견주면 어떻게 되나요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],true,'{"seq":8,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"1.4와 ⟨6/5⟩을 견주면 어떻게 되나요?","options":[{"t":"1.4가 크다","correct":true},{"t":"⟨6/5⟩이 크다","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨6/5⟩ = 1.2.","1.4 > 1.2예요.","그래서 1.4가 커요."],"variant_rule":{"alt":[{"stem":"⟨7/4⟩과 1.8을 견주면 어떻게 되나요?","options":[{"t":"1.8이 크다","correct":true},{"t":"⟨7/4⟩이 크다","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨7/4⟩ = 1.75.","1.8 > 1.75예요.","그래서 1.8이 커요."]},{"stem":"⟨9/5⟩와 1.7을 견주면 어떻게 되나요?","options":[{"t":"⟨9/5⟩가 크다","correct":true},{"t":"1.7이 크다","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨9/5⟩ = 1.8.","1.8 > 1.7이에요.","그래서 ⟨9/5⟩가 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#9','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',2,'ox','auto','⟨3/5⟩을 소수로 나타내면 분자와 분모를 나란히 쓴 0.35예요.',ARRAY['M5-1-u3-X12']::text[],true,'{"seq":9,"concept":"M5-1-u3-C6","difficulty":2,"kind":"ox","stem":"⟨3/5⟩을 소수로 나타내면 분자와 분모를 나란히 쓴 0.35예요.","answer":"X","reason_options":[{"t":"⟨3/5⟩ = ⟨6/10⟩이라 소수로 0.6이므로","correct":true},{"t":"분자는 소수 첫째 자리, 분모는 둘째 자리에 쓰므로","mis":"M5-1-u3-X12"}],"mis":"M5-1-u3-X12","explanation":["분모를 10으로 만들어요 — 분모와 분자에 2를 곱해요.","⟨3/5⟩ = ⟨6/10⟩ = 0.6이에요.","0.35는 ⟨35/100⟩ — ⟨3/5⟩과 다른 수예요."],"variant_rule":{"alt":[{"stem":"0.25는 분모가 100인 분수 ⟨25/100⟩로 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"소수 두 자리 수는 분모가 100인 분수와 같으므로","correct":true},{"t":"소수점 아래 숫자가 두 개면 분모를 10으로 쓰므로","mis":"M5-1-u3-X12"}],"explanation":["0.25는 소수 두 자리 수예요.","1을 100칸으로 나눈 것 중 25칸 — ⟨25/100⟩예요.","0.25 = ⟨25/100⟩ = ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_basic#10','math',5,1,'u3','L06','g5_1_math_u3_L06_basic','lesson_basic','M5-1-u3-C6',3,'mc','auto','⟨2/5⟩, 0.5, ⟨9/20⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],true,'{"seq":10,"concept":"M5-1-u3-C6","difficulty":3,"kind":"mc","stem":"⟨2/5⟩, 0.5, ⟨9/20⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨2/5⟩, ⟨9/20⟩, 0.5","correct":true},{"t":"0.5, ⟨9/20⟩, ⟨2/5⟩","mis":"M5-1-u3-X14"},{"t":"⟨2/5⟩, 0.5, ⟨9/20⟩","mis":"M5-1-u3-X09"},{"t":"0.5, ⟨2/5⟩, ⟨9/20⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨2/5⟩ = 0.4, ⟨9/20⟩ = 0.45 — 모두 소수로 나타내요.","견주면 0.4 < 0.45 < 0.5예요.","그래서 작은 것부터 쓰면 ⟨2/5⟩, ⟨9/20⟩, 0.5예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩, 0.7, ⟨4/5⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"0.7, ⟨3/4⟩, ⟨4/5⟩","correct":true},{"t":"⟨4/5⟩, ⟨3/4⟩, 0.7","mis":"M5-1-u3-X14"},{"t":"⟨3/4⟩, ⟨4/5⟩, 0.7","mis":"M5-1-u3-X09"},{"t":"⟨3/4⟩, 0.7, ⟨4/5⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨3/4⟩ = 0.75, ⟨4/5⟩ = 0.8 — 모두 소수로 나타내요.","견주면 0.7 < 0.75 < 0.8이에요.","그래서 작은 것부터 쓰면 0.7, ⟨3/4⟩, ⟨4/5⟩예요."]},{"stem":"0.35, ⟨1/4⟩, ⟨3/10⟩을 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨1/4⟩, ⟨3/10⟩, 0.35","correct":true},{"t":"0.35, ⟨3/10⟩, ⟨1/4⟩","mis":"M5-1-u3-X14"},{"t":"0.35, ⟨1/4⟩, ⟨3/10⟩","mis":"M5-1-u3-X13"},{"t":"⟨1/4⟩, 0.35, ⟨3/10⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨1/4⟩ = 0.25, ⟨3/10⟩ = 0.3 — 모두 소수로 나타내요.","견주면 0.25 < 0.3 < 0.35예요.","그래서 작은 것부터 쓰면 ⟨1/4⟩, ⟨3/10⟩, 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#1','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',2,'sa','auto','⟨1/4⟩을 소수로 나타내려고 분모를 100으로 만들 때 분모와 분자에 곱해야 하는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-1-u3-C6","difficulty":2,"kind":"sa","stem":"⟨1/4⟩을 소수로 나타내려고 분모를 100으로 만들 때 분모와 분자에 곱해야 하는 수는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["4 × 25 = 100이에요.","분자에도 25를 곱해요 — 1 × 25 = 25.","⟨1/4⟩ = ⟨25/100⟩ = 0.25예요."],"variant_rule":{"alt":[{"stem":"⟨3/20⟩을 소수로 나타내려고 분모를 100으로 만들 때 분모와 분자에 곱해야 하는 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["20 × 5 = 100이에요.","분자에도 5를 곱해요 — 3 × 5 = 15.","⟨3/20⟩ = ⟨15/100⟩ = 0.15예요."]},{"stem":"⟨7/25⟩을 소수로 나타내려고 분모를 100으로 만들 때 분모와 분자에 곱해야 하는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["25 × 4 = 100이에요.","분자에도 4를 곱해요 — 7 × 4 = 28.","⟨7/25⟩ = ⟨28/100⟩ = 0.28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#2','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',2,'error','auto','0.6을 분수로 나타낸 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X14']::text[],true,'{"seq":2,"concept":"M5-1-u3-C6","difficulty":2,"kind":"error","stem":"0.6을 분수로 나타낸 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「소수 한 자리니까 ⟨6/100⟩이야.」","correct":true,"mis_target":"M5-1-u3-X12"},{"t":"건우 — 「⟨6/10⟩이고 약분하면 ⟨3/5⟩이야.」","mis":"M5-1-u3-X14"},{"t":"서하 — 「0.6은 1을 10칸으로 나눈 것 중 6칸이야.」","mis":"M5-1-u3-X14"}],"explanation":["0.6은 소수 한 자리 수라 분모가 10이에요.","0.6 = ⟨6/10⟩ = ⟨3/5⟩이에요.","로아는 분모를 100으로 잘못 정했어요."],"variant_rule":{"alt":[{"stem":"0.25를 분수로 나타낸 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「소수 두 자리니까 ⟨25/10⟩야.」","correct":true,"mis_target":"M5-1-u3-X12"},{"t":"도겸 — 「⟨25/100⟩이고 약분하면 ⟨1/4⟩이야.」","mis":"M5-1-u3-X14"},{"t":"리아 — 「0.25는 1을 100칸으로 나눈 것 중 25칸이야.」","mis":"M5-1-u3-X14"}],"explanation":["0.25는 소수 두 자리 수라 분모가 100이에요.","0.25 = ⟨25/100⟩ = ⟨1/4⟩이에요.","하윤은 분모를 10으로 잘못 정했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#3','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',3,'mc','auto','⟨2/3⟩, 0.7, ⟨5/8⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],true,'{"seq":3,"concept":"M5-1-u3-C6","difficulty":3,"kind":"mc","stem":"⟨2/3⟩, 0.7, ⟨5/8⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩, ⟨2/3⟩, 0.7","correct":true},{"t":"0.7, ⟨2/3⟩, ⟨5/8⟩","mis":"M5-1-u3-X14"},{"t":"⟨2/3⟩, ⟨5/8⟩, 0.7","mis":"M5-1-u3-X09"},{"t":"⟨2/3⟩, 0.7, ⟨5/8⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 120으로 나타내면 ⟨2/3⟩ = ⟨80/120⟩, 0.7 = ⟨84/120⟩, ⟨5/8⟩ = ⟨75/120⟩예요.","견주면 ⟨75/120⟩ < ⟨80/120⟩ < ⟨84/120⟩예요.","그래서 작은 것부터 쓰면 ⟨5/8⟩, ⟨2/3⟩, 0.7이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩, 0.3, ⟨3/8⟩을 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"0.3, ⟨1/3⟩, ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩, ⟨1/3⟩, 0.3","mis":"M5-1-u3-X14"},{"t":"⟨1/3⟩, 0.3, ⟨3/8⟩","mis":"M5-1-u3-X09"},{"t":"⟨1/3⟩, ⟨3/8⟩, 0.3","mis":"M5-1-u3-X11"}],"explanation":["공통분모 120으로 나타내면 ⟨1/3⟩ = ⟨40/120⟩, 0.3 = ⟨36/120⟩, ⟨3/8⟩ = ⟨45/120⟩예요.","견주면 ⟨36/120⟩ < ⟨40/120⟩ < ⟨45/120⟩예요.","그래서 작은 것부터 쓰면 0.3, ⟨1/3⟩, ⟨3/8⟩이에요."]},{"stem":"⟨5/6⟩, 0.8, ⟨7/9⟩을 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨7/9⟩, 0.8, ⟨5/6⟩","correct":true},{"t":"⟨5/6⟩, 0.8, ⟨7/9⟩","mis":"M5-1-u3-X14"},{"t":"⟨5/6⟩, ⟨7/9⟩, 0.8","mis":"M5-1-u3-X09"},{"t":"0.8, ⟨5/6⟩, ⟨7/9⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 90으로 나타내면 ⟨5/6⟩ = ⟨75/90⟩, 0.8 = ⟨72/90⟩, ⟨7/9⟩ = ⟨70/90⟩이에요.","견주면 ⟨70/90⟩ < ⟨72/90⟩ < ⟨75/90⟩예요.","그래서 작은 것부터 쓰면 ⟨7/9⟩, 0.8, ⟨5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#4','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',3,'sa','auto','0.□가 ⟨3/5⟩보다 크고 ⟨9/10⟩보다 작을 때, □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C6","difficulty":3,"kind":"sa","stem":"0.□가 ⟨3/5⟩보다 크고 ⟨9/10⟩보다 작을 때, □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2","2개"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/5⟩ = 0.6, ⟨9/10⟩ = 0.9.","0.6보다 크고 0.9보다 작은 0.□는 0.7, 0.8이에요.","모두 2개예요."],"variant_rule":{"alt":[{"stem":"0.□가 ⟨1/4⟩보다 크고 ⟨4/5⟩보다 작을 때, □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["분수를 소수로 바꾸어요 — ⟨1/4⟩ = 0.25, ⟨4/5⟩ = 0.8.","0.25보다 크고 0.8보다 작은 0.□는 0.3, 0.4, 0.5, 0.6, 0.7이에요.","모두 5개예요."]},{"stem":"0.□가 ⟨3/10⟩보다 크고 ⟨3/4⟩보다 작을 때, □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/10⟩ = 0.3, ⟨3/4⟩ = 0.75.","0.3보다 크고 0.75보다 작은 0.□는 0.4, 0.5, 0.6, 0.7이에요.","모두 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#5','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',3,'mc','auto','⟨13/20⟩과 0.62 중 더 큰 수는 어느 것인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],true,'{"seq":5,"concept":"M5-1-u3-C6","difficulty":3,"kind":"mc","stem":"⟨13/20⟩과 0.62 중 더 큰 수는 어느 것인가요?","options":[{"t":"⟨13/20⟩","correct":true},{"t":"0.62","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨13/20⟩ = 0.65.","0.65 > 0.62예요.","그래서 더 큰 수는 ⟨13/20⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨7/25⟩과 0.3 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.3","correct":true},{"t":"⟨7/25⟩","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨7/25⟩ = 0.28.","0.3 > 0.28이에요.","그래서 더 큰 수는 0.3이에요."]},{"stem":"⟨11/20⟩과 0.5 중 더 큰 수는 어느 것인가요?","options":[{"t":"⟨11/20⟩","correct":true},{"t":"0.5","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨11/20⟩ = 0.55.","0.55 > 0.5예요.","그래서 더 큰 수는 ⟨11/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#6','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',3,'match','auto','크기가 같은 분수와 소수를 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u3-C6","difficulty":3,"kind":"match","stem":"크기가 같은 분수와 소수를 이으세요.","pairs":[{"l":"⟨1/4⟩","r":"0.25"},{"l":"⟨2/5⟩","r":"0.4"},{"l":"⟨3/20⟩","r":"0.15"}],"mis":"M5-1-u3-X12","explanation":["⟨1/4⟩ = ⟨25/100⟩ = 0.25예요.","⟨2/5⟩ = ⟨4/10⟩ = 0.4, ⟨3/20⟩ = ⟨15/100⟩ = 0.15예요.","분모를 10이나 100으로 만들면 소수로 바로 읽혀요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 크기가 같은 분수와 소수를 이으세요.","pairs":[{"l":"⟨3/4⟩","r":"0.75"},{"l":"⟨1/5⟩","r":"0.2"},{"l":"⟨9/50⟩","r":"0.18"}],"explanation":["⟨3/4⟩ = ⟨75/100⟩ = 0.75예요.","⟨1/5⟩ = ⟨2/10⟩ = 0.2, ⟨9/50⟩ = ⟨18/100⟩ = 0.18이에요.","분모를 10이나 100으로 만들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#7','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',3,'ox','auto','⟨1/2⟩, 0.5, ⟨50/100⟩은 모두 같은 수예요.',ARRAY['M5-1-u3-X12']::text[],true,'{"seq":7,"concept":"M5-1-u3-C6","difficulty":3,"kind":"ox","stem":"⟨1/2⟩, 0.5, ⟨50/100⟩은 모두 같은 수예요.","answer":"O","reason_options":[{"t":"⟨1/2⟩ = ⟨5/10⟩ = ⟨50/100⟩이고 ⟨5/10⟩ = 0.5이므로","correct":true},{"t":"세 수에 모두 숫자 5가 들어 있으므로","mis":"M5-1-u3-X12"}],"mis":"M5-1-u3-X12","explanation":["⟨1/2⟩의 분모와 분자에 5를 곱하면 ⟨5/10⟩, 50을 곱하면 ⟨50/100⟩이에요.","⟨5/10⟩ = 0.5예요.","그래서 ⟨1/2⟩ = 0.5 = ⟨50/100⟩ — 모두 같은 수예요."],"variant_rule":{"alt":[{"stem":"0.08은 ⟨8/10⟩과 같아요.","answer":"X","reason_options":[{"t":"0.08은 소수 두 자리 수라 ⟨8/100⟩이므로","correct":true},{"t":"소수점 아래 숫자가 8 하나뿐이므로","mis":"M5-1-u3-X12"}],"explanation":["0.08은 소수점 아래 둘째 자리에 8이 있어요.","소수 두 자리 수는 분모가 100 — 0.08 = ⟨8/100⟩이에요.","⟨8/10⟩ = 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#8','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',4,'sa','auto','⟨3/4⟩, 0.7, ⟨7/10⟩, 0.72, ⟨19/25⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u3-C6","difficulty":4,"kind":"sa","stem":"⟨3/4⟩, 0.7, ⟨7/10⟩, 0.72, ⟨19/25⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/4⟩ = 0.75, ⟨7/10⟩ = 0.7, ⟨19/25⟩ = 0.76.","가장 큰 수는 0.76이에요.","□□에 알맞은 수는 76이에요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩, 0.38, ⟨9/20⟩, 0.42, ⟨11/25⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["분수를 소수로 바꾸어요 — ⟨2/5⟩ = 0.4, ⟨9/20⟩ = 0.45, ⟨11/25⟩ = 0.44.","가장 큰 수는 0.45예요.","□□에 알맞은 수는 45예요."]},{"stem":"⟨3/5⟩, 0.58, ⟨13/20⟩, 0.64, ⟨16/25⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/5⟩ = 0.6, ⟨13/20⟩ = 0.65, ⟨16/25⟩ = 0.64.","가장 큰 수는 0.65예요.","□□에 알맞은 수는 65예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#9','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',4,'essay','teacher','⟨3/5⟩과 0.7의 크기를 비교하는 방법을 두 가지(분수를 소수로, 소수를 분수로)로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C6","difficulty":4,"kind":"essay","stem":"⟨3/5⟩과 0.7의 크기를 비교하는 방법을 두 가지(분수를 소수로, 소수를 분수로)로 설명하세요.","answer_guide":{"answer":"예: 첫째, ⟨3/5⟩의 분모와 분자에 2를 곱하면 ⟨6/10⟩이므로 0.6이고, 0.6 < 0.7이다. 둘째, 0.7을 분수로 바꾸면 ⟨7/10⟩이고, ⟨3/5⟩ = ⟨6/10⟩이므로 ⟨6/10⟩ < ⟨7/10⟩이다. 두 방법 모두 0.7이 더 크다.","scoring_points":["⟨3/5⟩을 소수 0.6으로 바르게 바꾸었는가","0.7을 분수 ⟨7/10⟩로 바르게 바꾸었는가","두 방법 모두 0.7이 더 크다고 맺었는가"]},"explanation":["⟨3/5⟩ = ⟨6/10⟩ = 0.6 — 0.6 < 0.7이에요.","0.7 = ⟨7/10⟩ — ⟨6/10⟩ < ⟨7/10⟩이에요.","어느 쪽 옷을 입혀도 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L06_challenge#10','math',5,1,'u3','L06','g5_1_math_u3_L06_challenge','lesson_challenge','M5-1-u3-C6',4,'essay','teacher','0.6과 ⟨6/10⟩이 같은 수인 까닭을 1을 10칸으로 나눈 그림으로 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C6","difficulty":4,"kind":"essay","stem":"0.6과 ⟨6/10⟩이 같은 수인 까닭을 1을 10칸으로 나눈 그림으로 설명하세요.","answer_guide":{"answer":"예: 1을 똑같이 10칸으로 나누면 한 칸은 0.1이고 ⟨1/10⟩이다. 0.6은 0.1이 6개, ⟨6/10⟩은 ⟨1/10⟩이 6개이므로 둘 다 10칸 중 6칸을 나타낸다. 그래서 0.6과 ⟨6/10⟩은 같은 수이다.","scoring_points":["1을 10칸으로 나눈 한 칸이 0.1이고 ⟨1/10⟩이라고 썼는가","두 수 모두 10칸 중 6칸이라고 썼는가","소수는 분모가 10인 분수의 다른 이름이라고 맺었는가"]},"explanation":["한 칸은 0.1 — ⟨1/10⟩이에요.","0.6도 ⟨6/10⟩도 10칸 중 6칸이에요.","소수는 분모가 10, 100인 분수의 다른 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#1','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',1,'mc','auto','⟨5/7⟩, ⟨1/3⟩, ⟨5/8⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?',ARRAY['M5-1-u3-X10']::text[],true,'{"seq":1,"concept":"M5-1-u3-C7","difficulty":1,"kind":"mc","stem":"⟨5/7⟩, ⟨1/3⟩, ⟨5/8⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨5/7⟩","mis":"M5-1-u3-X10"},{"t":"⟨5/8⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","5 × 2 = 10이 7보다 커서 ⟨5/7⟩ > ⟨1/2⟩ · 1 × 2 = 2가 3보다 작아서 ⟨1/3⟩ < ⟨1/2⟩ · 5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩, ⟨7/12⟩, ⟨5/6⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u3-X10"},{"t":"⟨5/6⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","4 × 2 = 8이 9보다 작아서 ⟨4/9⟩ < ⟨1/2⟩ · 7 × 2 = 14가 12보다 커서 ⟨7/12⟩ > ⟨1/2⟩ · 5 × 2 = 10이 6보다 커서 ⟨5/6⟩ > ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨4/9⟩예요."]},{"stem":"⟨3/5⟩, ⟨2/7⟩, ⟨6/11⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-1-u3-X10"},{"t":"⟨6/11⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","3 × 2 = 6이 5보다 커서 ⟨3/5⟩ > ⟨1/2⟩ · 2 × 2 = 4가 7보다 작아서 ⟨2/7⟩ < ⟨1/2⟩ · 6 × 2 = 12가 11보다 커서 ⟨6/11⟩ > ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨2/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#2','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',1,'sa','auto','⟨5/7⟩와 ⟨5/8⟩ 중 더 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C7","difficulty":1,"kind":"sa","stem":"⟨5/7⟩와 ⟨5/8⟩ 중 더 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["두 분수의 분자가 5로 같아요 — 조각 개수가 같아요.","조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","⟨5/7⟩가 더 커요 — 분모는 7이에요."],"variant_rule":{"alt":[{"stem":"⟨3/11⟩과 ⟨3/8⟩ 중 더 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 분수의 분자가 3으로 같아요 — 조각 개수가 같아요.","조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","⟨3/8⟩이 더 커요 — 분모는 8이에요."]},{"stem":"⟨4/5⟩와 ⟨4/9⟩ 중 더 큰 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["두 분수의 분자가 4로 같아요 — 조각 개수가 같아요.","조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","⟨4/5⟩가 더 커요 — 분모는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#3','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',1,'mc','auto','분자가 같은 분수의 크기 비교로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X14']::text[],true,'{"seq":3,"concept":"M5-1-u3-C7","difficulty":1,"kind":"mc","stem":"분자가 같은 분수의 크기 비교로 옳은 것은 어느 것인가요?","options":[{"t":"분모가 작을수록 크다","correct":true},{"t":"분모가 클수록 크다","mis":"M5-1-u3-X11"},{"t":"분모와 상관없이 모두 같다","mis":"M5-1-u3-X09"},{"t":"분자가 클수록 작다","mis":"M5-1-u3-X14"}],"explanation":["분자가 같으면 조각 개수가 같아요.","분모가 작을수록 조각 하나가 커요.","예: ⟨5/7⟩ > ⟨5/8⟩예요."],"variant_rule":{"alt":[{"stem":"분모가 같은 분수의 크기 비교로 옳은 것은 어느 것인가요?","options":[{"t":"분자가 클수록 크다","correct":true},{"t":"분자가 작을수록 크다","mis":"M5-1-u3-X11"},{"t":"분자와 상관없이 모두 같다","mis":"M5-1-u3-X09"},{"t":"분모가 클수록 크다","mis":"M5-1-u3-X14"}],"explanation":["분모가 같으면 조각 하나의 크기가 같아요.","분자는 조각의 개수예요.","예: ⟨5/8⟩ > ⟨3/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#4','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',1,'sa','auto','배터리 용량이 같은 전기 자동차 세 대가 각각 ⟨1/3⟩, ⟨5/7⟩, ⟨5/8⟩만큼 충전되어 있어요. 가장 적게 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u3-C7","difficulty":1,"kind":"sa","stem":"배터리 용량이 같은 전기 자동차 세 대가 각각 ⟨1/3⟩, ⟨5/7⟩, ⟨5/8⟩만큼 충전되어 있어요. 가장 적게 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/2⟩을 기준으로 갈라 보아요.","1 × 2 = 2가 3보다 작아서 ⟨1/3⟩ < ⟨1/2⟩ · 5 × 2 = 10이 7보다 커서 ⟨5/7⟩ > ⟨1/2⟩ · 5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩.","가장 적게 충전된 것은 ⟨1/3⟩ — 분모는 3이에요."],"variant_rule":{"alt":[{"stem":"배터리 용량이 같은 전기 자동차 세 대가 각각 ⟨3/5⟩, ⟨2/9⟩, ⟨3/4⟩만큼 충전되어 있어요. 가장 적게 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/2⟩을 기준으로 갈라 보아요.","3 × 2 = 6이 5보다 커서 ⟨3/5⟩ > ⟨1/2⟩ · 2 × 2 = 4가 9보다 작아서 ⟨2/9⟩ < ⟨1/2⟩ · 3 × 2 = 6이 4보다 커서 ⟨3/4⟩ > ⟨1/2⟩.","가장 적게 충전된 것은 ⟨2/9⟩ — 분모는 9예요."]},{"stem":"배터리 용량이 같은 전기 자동차 세 대가 각각 ⟨5/6⟩, ⟨5/9⟩, ⟨3/7⟩만큼 충전되어 있어요. 가장 적게 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨1/2⟩을 기준으로 갈라 보아요.","5 × 2 = 10이 6보다 커서 ⟨5/6⟩ > ⟨1/2⟩ · 5 × 2 = 10이 9보다 커서 ⟨5/9⟩ > ⟨1/2⟩ · 3 × 2 = 6이 7보다 작아서 ⟨3/7⟩ < ⟨1/2⟩.","가장 적게 충전된 것은 ⟨3/7⟩ — 분모는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#5','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',2,'mc','auto','⟨3/11⟩, ⟨3/8⟩, ⟨3/5⟩ 중 가장 작은 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X13','M5-1-u3-X09']::text[],true,'{"seq":5,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨3/11⟩, ⟨3/8⟩, ⟨3/5⟩ 중 가장 작은 분수는 어느 것인가요?","options":[{"t":"⟨3/11⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-1-u3-X11"},{"t":"⟨3/8⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["세 분수 모두 분자가 3으로 같아요.","분자가 같으면 분모가 클수록 조각이 작아 분수도 작아요.","분모가 가장 큰 ⟨3/11⟩이 가장 작아요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩, ⟨2/5⟩, ⟨2/7⟩ 중 가장 작은 분수는 어느 것인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨2/5⟩","mis":"M5-1-u3-X11"},{"t":"⟨2/7⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["세 분수 모두 분자가 2로 같아요.","분자가 같으면 분모가 클수록 조각이 작아 분수도 작아요.","분모가 가장 큰 ⟨2/9⟩가 가장 작아요."]},{"stem":"⟨6/7⟩, ⟨6/13⟩, ⟨6/11⟩ 중 가장 작은 분수는 어느 것인가요?","options":[{"t":"⟨6/13⟩","correct":true},{"t":"⟨6/7⟩","mis":"M5-1-u3-X11"},{"t":"⟨6/11⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["세 분수 모두 분자가 6으로 같아요.","분자가 같으면 분모가 클수록 조각이 작아 분수도 작아요.","분모가 가장 큰 ⟨6/13⟩이 가장 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#6','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',2,'mc','auto','⟨2/5⟩, ⟨7/8⟩, ⟨2/7⟩를 큰 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X11','M5-1-u3-X13']::text[],true,'{"seq":6,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨2/5⟩, ⟨7/8⟩, ⟨2/7⟩를 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨7/8⟩, ⟨2/5⟩, ⟨2/7⟩","correct":true},{"t":"⟨2/7⟩, ⟨2/5⟩, ⟨7/8⟩","mis":"M5-1-u3-X14"},{"t":"⟨7/8⟩, ⟨2/7⟩, ⟨2/5⟩","mis":"M5-1-u3-X11"},{"t":"⟨2/5⟩, ⟨7/8⟩, ⟨2/7⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨1/2⟩을 기준으로 먼저 갈라요 — 2 × 2 = 4가 5보다 작아서 ⟨2/5⟩ < ⟨1/2⟩ · 7 × 2 = 14가 8보다 커서 ⟨7/8⟩ > ⟨1/2⟩ · 2 × 2 = 4가 7보다 작아서 ⟨2/7⟩ < ⟨1/2⟩.","견주면 ⟨7/8⟩ > ⟨2/5⟩ > ⟨2/7⟩ — 같은 쪽의 두 분수는 분자가 같아 분모가 작은 쪽이 커요이에요.","그래서 큰 것부터 쓰면 ⟨7/8⟩, ⟨2/5⟩, ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩, ⟨5/6⟩, ⟨3/8⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩, ⟨3/7⟩, ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩, ⟨3/7⟩, ⟨5/6⟩","mis":"M5-1-u3-X14"},{"t":"⟨3/7⟩, ⟨5/6⟩, ⟨3/8⟩","mis":"M5-1-u3-X13"},{"t":"⟨3/7⟩, ⟨3/8⟩, ⟨5/6⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨1/2⟩을 기준으로 먼저 갈라요 — 3 × 2 = 6이 7보다 작아서 ⟨3/7⟩ < ⟨1/2⟩ · 5 × 2 = 10이 6보다 커서 ⟨5/6⟩ > ⟨1/2⟩ · 3 × 2 = 6이 8보다 작아서 ⟨3/8⟩ < ⟨1/2⟩.","견주면 ⟨5/6⟩ > ⟨3/7⟩ > ⟨3/8⟩ — 같은 쪽의 두 분수는 분자가 같아 분모가 작은 쪽이 커요이에요.","그래서 큰 것부터 쓰면 ⟨5/6⟩, ⟨3/7⟩, ⟨3/8⟩이에요."]},{"stem":"⟨5/9⟩, ⟨1/4⟩, ⟨1/3⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/9⟩, ⟨1/3⟩, ⟨1/4⟩","correct":true},{"t":"⟨1/4⟩, ⟨1/3⟩, ⟨5/9⟩","mis":"M5-1-u3-X14"},{"t":"⟨5/9⟩, ⟨1/4⟩, ⟨1/3⟩","mis":"M5-1-u3-X09"},{"t":"⟨1/4⟩, ⟨5/9⟩, ⟨1/3⟩","mis":"M5-1-u3-X13"}],"explanation":["⟨1/2⟩을 기준으로 먼저 갈라요 — 5 × 2 = 10이 9보다 커서 ⟨5/9⟩ > ⟨1/2⟩ · 1 × 2 = 2가 4보다 작아서 ⟨1/4⟩ < ⟨1/2⟩ · 1 × 2 = 2가 3보다 작아서 ⟨1/3⟩ < ⟨1/2⟩.","견주면 ⟨5/9⟩ > ⟨1/3⟩ > ⟨1/4⟩ — 같은 쪽의 두 분수는 분자가 같아 분모가 작은 쪽이 커요이에요.","그래서 큰 것부터 쓰면 ⟨5/9⟩, ⟨1/3⟩, ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#7','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',2,'mc','auto','통분하지 않고도 크기를 견줄 수 있는 경우가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X14']::text[],false,'{"seq":7,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"통분하지 않고도 크기를 견줄 수 있는 경우가 아닌 것은 어느 것인가요?","options":[{"t":"분모도 분자도 다르고 ⟨1/2⟩을 사이에 두고 갈리지도 않을 때","correct":true},{"t":"분자가 같을 때","mis":"M5-1-u3-X14"},{"t":"분모가 같을 때","mis":"M5-1-u3-X14"},{"t":"⟨1/2⟩을 사이에 두고 갈릴 때","mis":"M5-1-u3-X14"}],"explanation":["분모가 같으면 분자를, 분자가 같으면 분모를 보면 돼요.","⟨1/2⟩을 사이에 두고 갈리면 기준 하나로 견줄 수 있어요.","기댈 곳이 하나도 없을 때 통분을 꺼내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#8','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',2,'mc','auto','⟨3/7⟩과 ⟨5/8⟩를 견주는 가장 가벼운 길은 어느 것인가요?',ARRAY['M5-1-u3-X09']::text[],true,'{"seq":8,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨3/7⟩과 ⟨5/8⟩를 견주는 가장 가벼운 길은 어느 것인가요?","options":[{"t":"⟨1/2⟩을 기준으로 갈라 본다","correct":true},{"t":"분자가 같으니 분모를 본다","mis":"M5-1-u3-X09"},{"t":"분모가 같으니 분자를 본다","mis":"M5-1-u3-X09"},{"t":"분모와 분자를 각각 견준다","mis":"M5-1-u3-X09"}],"explanation":["3 × 2 = 6이 7보다 작아 ⟨3/7⟩ < ⟨1/2⟩이에요.","5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩이에요.","⟨1/2⟩을 사이에 두고 갈리니 통분 없이 ⟨3/7⟩ < ⟨5/8⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩와 ⟨4/11⟩를 견주는 가장 가벼운 길은 어느 것인가요?","options":[{"t":"분자가 같으니 분모를 본다","correct":true},{"t":"⟨1/2⟩을 기준으로 갈라 본다","mis":"M5-1-u3-X10"},{"t":"분모가 같으니 분자를 본다","mis":"M5-1-u3-X09"},{"t":"분자가 큰 쪽이 크다고 본다","mis":"M5-1-u3-X09"}],"explanation":["두 분수 모두 ⟨1/2⟩보다 작아 기준으로는 갈리지 않아요.","분자가 4로 같으니 분모가 작은 쪽이 커요.","그래서 ⟨4/9⟩ > ⟨4/11⟩예요."]},{"stem":"⟨7/12⟩과 ⟨11/12⟩을 견주는 가장 가벼운 길은 어느 것인가요?","options":[{"t":"분모가 같으니 분자를 본다","correct":true},{"t":"분자가 같으니 분모를 본다","mis":"M5-1-u3-X09"},{"t":"⟨1/2⟩을 기준으로 갈라 본다","mis":"M5-1-u3-X10"},{"t":"분모와 분자를 각각 견준다","mis":"M5-1-u3-X09"}],"explanation":["두 분수 모두 ⟨1/2⟩보다 커 기준으로는 갈리지 않아요.","분모가 12로 같으니 분자가 큰 쪽이 커요.","그래서 ⟨7/12⟩ < ⟨11/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#9','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',2,'ox','auto','⟨5/7⟩와 ⟨5/8⟩는 분자가 같으니 분모가 큰 ⟨5/8⟩가 더 커요.',ARRAY['M5-1-u3-X11']::text[],true,'{"seq":9,"concept":"M5-1-u3-C7","difficulty":2,"kind":"ox","stem":"⟨5/7⟩와 ⟨5/8⟩는 분자가 같으니 분모가 큰 ⟨5/8⟩가 더 커요.","answer":"X","reason_options":[{"t":"조각 개수가 같으면 조각이 큰 쪽, 곧 분모가 작은 ⟨5/7⟩가 크므로","correct":true},{"t":"분모가 크면 조각이 많아 더 크므로","mis":"M5-1-u3-X11"}],"mis":"M5-1-u3-X11","explanation":["두 분수 모두 조각이 5개예요.","⟨1/7⟩ 조각이 ⟨1/8⟩ 조각보다 커요.","그래서 ⟨5/7⟩ > ⟨5/8⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩은 분자 1이 분모 3의 절반보다 작으니 ⟨1/2⟩보다 작아요.","answer":"O","reason_options":[{"t":"1 × 2 = 2가 3보다 작아 분자가 분모의 절반보다 작으므로","correct":true},{"t":"분모 3이 2보다 크면 언제나 ⟨1/2⟩보다 작으므로","mis":"M5-1-u3-X11"}],"explanation":["분자를 2배 해서 분모와 견주어요.","1 × 2 = 2 — 3보다 작아요.","그래서 ⟨1/3⟩ < ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_basic#10','math',5,1,'u3','L07','g5_1_math_u3_L07_basic','lesson_basic','M5-1-u3-C7',3,'sa','auto','충전량이 각각 ⟨3/8⟩, ⟨5/9⟩, ⟨3/7⟩, ⟨5/6⟩인 전기 자동차 네 대가 있어요. 둘째로 많이 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-1-u3-C7","difficulty":3,"kind":"sa","stem":"충전량이 각각 ⟨3/8⟩, ⟨5/9⟩, ⟨3/7⟩, ⟨5/6⟩인 전기 자동차 네 대가 있어요. 둘째로 많이 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/2⟩을 기준으로 먼저 갈라요 — 3 × 2 = 6이 8보다 작아서 ⟨3/8⟩ < ⟨1/2⟩ · 5 × 2 = 10이 9보다 커서 ⟨5/9⟩ > ⟨1/2⟩ · 3 × 2 = 6이 7보다 작아서 ⟨3/7⟩ < ⟨1/2⟩ · 5 × 2 = 10이 6보다 커서 ⟨5/6⟩ > ⟨1/2⟩.","같은 쪽끼리는 분자가 같은지 보고, 아니면 통분해요 — ⟨5/6⟩ > ⟨5/9⟩ > ⟨3/7⟩ > ⟨3/8⟩.","둘째로 많이 충전된 것은 ⟨5/9⟩ — 분모는 9예요."],"variant_rule":{"alt":[{"stem":"충전량이 각각 ⟨2/7⟩, ⟨4/5⟩, ⟨2/5⟩, ⟨4/9⟩인 전기 자동차 네 대가 있어요. 셋째로 많이 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1/2⟩을 기준으로 먼저 갈라요 — 2 × 2 = 4가 7보다 작아서 ⟨2/7⟩ < ⟨1/2⟩ · 4 × 2 = 8이 5보다 커서 ⟨4/5⟩ > ⟨1/2⟩ · 2 × 2 = 4가 5보다 작아서 ⟨2/5⟩ < ⟨1/2⟩ · 4 × 2 = 8이 9보다 작아서 ⟨4/9⟩ < ⟨1/2⟩.","같은 쪽끼리는 분자가 같은지 보고, 아니면 통분해요 — ⟨4/5⟩ > ⟨4/9⟩ > ⟨2/5⟩ > ⟨2/7⟩.","셋째로 많이 충전된 것은 ⟨2/5⟩ — 분모는 5예요."]},{"stem":"충전량이 각각 ⟨7/9⟩, ⟨3/10⟩, ⟨7/12⟩, ⟨3/5⟩인 전기 자동차 네 대가 있어요. 가장 적게 충전된 자동차의 충전량을 나타낸 분수의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["⟨1/2⟩을 기준으로 먼저 갈라요 — 7 × 2 = 14가 9보다 커서 ⟨7/9⟩ > ⟨1/2⟩ · 3 × 2 = 6이 10보다 작아서 ⟨3/10⟩ < ⟨1/2⟩ · 7 × 2 = 14가 12보다 커서 ⟨7/12⟩ > ⟨1/2⟩ · 3 × 2 = 6이 5보다 커서 ⟨3/5⟩ > ⟨1/2⟩.","같은 쪽끼리는 분자가 같은지 보고, 아니면 통분해요 — ⟨3/10⟩ < ⟨7/12⟩ < ⟨3/5⟩ < ⟨7/9⟩.","가장 적게 충전된 것은 ⟨3/10⟩ — 분모는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#1','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',2,'mc','auto','충전량 ⟨5/7⟩, ⟨1/3⟩, ⟨5/8⟩를 견줄 때 3, 7, 8의 공배수 168로 한꺼번에 통분하지 않아도 되는 까닭은 무엇인가요?',ARRAY['M5-1-u3-X08','M5-1-u3-X11']::text[],false,'{"seq":1,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"충전량 ⟨5/7⟩, ⟨1/3⟩, ⟨5/8⟩를 견줄 때 3, 7, 8의 공배수 168로 한꺼번에 통분하지 않아도 되는 까닭은 무엇인가요?","options":[{"t":"⟨1/2⟩ 기준과 같은 분자로 견줄 수 있어서","correct":true},{"t":"분수끼리는 원래 견줄 수 없어서","mis":"M5-1-u3-X08"},{"t":"분모가 가장 큰 ⟨5/8⟩가 가장 크다는 것을 알아서","mis":"M5-1-u3-X11"},{"t":"168은 공통분모가 될 수 없어서","mis":"M5-1-u3-X08"}],"explanation":["⟨1/3⟩은 ⟨1/2⟩보다 작고, ⟨5/7⟩와 ⟨5/8⟩는 ⟨1/2⟩보다 커요.","⟨5/7⟩와 ⟨5/8⟩는 분자가 같아 분모가 작은 ⟨5/7⟩가 커요.","그래서 ⟨5/7⟩ > ⟨5/8⟩ > ⟨1/3⟩ — 통분 한 번 없이 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#2','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',2,'sa','auto','⟨□/9⟩는 ⟨1/2⟩보다 작은 진분수예요. □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u3-C7","difficulty":2,"kind":"sa","stem":"⟨□/9⟩는 ⟨1/2⟩보다 작은 진분수예요. □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["□ × 2가 9보다 작으면 ⟨1/2⟩보다 작아요.","□ = 1, 2, 3, 4예요.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"⟨□/11⟩는 ⟨1/2⟩보다 큰 진분수예요. □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["□ × 2가 11보다 크면 ⟨1/2⟩보다 커요.","□ = 6, 7, 8, 9, 10이에요.","모두 5개예요."]},{"stem":"⟨□/7⟩는 ⟨1/2⟩보다 작은 진분수예요. □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["□ × 2가 7보다 작으면 ⟨1/2⟩보다 작아요.","□ = 1, 2, 3이에요.","모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#3','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',3,'mc','auto','⟨6/13⟩, ⟨6/11⟩, ⟨5/12⟩ 중 가장 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09']::text[],true,'{"seq":3,"concept":"M5-1-u3-C7","difficulty":3,"kind":"mc","stem":"⟨6/13⟩, ⟨6/11⟩, ⟨5/12⟩ 중 가장 큰 분수는 어느 것인가요?","options":[{"t":"⟨6/11⟩","correct":true},{"t":"⟨6/13⟩","mis":"M5-1-u3-X11"},{"t":"⟨5/12⟩","mis":"M5-1-u3-X09"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩을 기준으로 갈라 보아요.","6 × 2 = 12가 13보다 작아서 ⟨6/13⟩ < ⟨1/2⟩ · 6 × 2 = 12가 11보다 커서 ⟨6/11⟩ > ⟨1/2⟩ · 5 × 2 = 10이 12보다 작아서 ⟨5/12⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 것은 ⟨6/11⟩ 하나뿐 — 통분하지 않아도 가장 큰 분수예요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩, ⟨5/9⟩, ⟨5/11⟩ 중 가장 큰 분수는 어느 것인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨5/11⟩","mis":"M5-1-u3-X09"},{"t":"⟨4/9⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩을 기준으로 갈라 보아요.","4 × 2 = 8이 9보다 작아서 ⟨4/9⟩ < ⟨1/2⟩ · 5 × 2 = 10이 9보다 커서 ⟨5/9⟩ > ⟨1/2⟩ · 5 × 2 = 10이 11보다 작아서 ⟨5/11⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 것은 ⟨5/9⟩ 하나뿐 — 통분하지 않아도 가장 큰 분수예요."]},{"stem":"⟨7/15⟩, ⟨7/13⟩, ⟨6/13⟩ 중 가장 큰 분수는 어느 것인가요?","options":[{"t":"⟨7/13⟩","correct":true},{"t":"⟨7/15⟩","mis":"M5-1-u3-X11"},{"t":"⟨6/13⟩","mis":"M5-1-u3-X13"},{"t":"세 분수는 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩을 기준으로 갈라 보아요.","7 × 2 = 14가 15보다 작아서 ⟨7/15⟩ < ⟨1/2⟩ · 7 × 2 = 14가 13보다 커서 ⟨7/13⟩ > ⟨1/2⟩ · 6 × 2 = 12가 13보다 작아서 ⟨6/13⟩ < ⟨1/2⟩.","⟨1/2⟩보다 큰 것은 ⟨7/13⟩ 하나뿐 — 통분하지 않아도 가장 큰 분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#4','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',3,'mc','auto','세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 서윤 ⟨3/8⟩, 도윤 ⟨3/5⟩, 하린 ⟨7/12⟩. 가장 많이 마신 사람은 누구인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X09']::text[],true,'{"seq":4,"concept":"M5-1-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 서윤 ⟨3/8⟩, 도윤 ⟨3/5⟩, 하린 ⟨7/12⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"서윤","mis":"M5-1-u3-X13"},{"t":"하린","mis":"M5-1-u3-X09"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 120으로 나타내면 ⟨3/8⟩ = ⟨45/120⟩, ⟨3/5⟩ = ⟨72/120⟩, ⟨7/12⟩ = ⟨70/120⟩이에요.","⟨3/5⟩ > ⟨7/12⟩ > ⟨3/8⟩ — 가장 많이 마신 사람은 도윤이에요."],"variant_rule":{"alt":[{"stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 지우 ⟨4/9⟩, 하람 ⟨2/3⟩, 은우 ⟨5/8⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"하람","correct":true},{"t":"지우","mis":"M5-1-u3-X09"},{"t":"은우","mis":"M5-1-u3-X09"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 72로 나타내면 ⟨4/9⟩ = ⟨32/72⟩, ⟨2/3⟩ = ⟨48/72⟩, ⟨5/8⟩ = ⟨45/72⟩예요.","⟨2/3⟩ > ⟨5/8⟩ > ⟨4/9⟩ — 가장 많이 마신 사람은 하람이에요."]},{"stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 나은 ⟨5/6⟩, 시온 ⟨4/5⟩, 태린 ⟨2/5⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"나은","correct":true},{"t":"시온","mis":"M5-1-u3-X13"},{"t":"태린","mis":"M5-1-u3-X13"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 30으로 나타내면 ⟨5/6⟩ = ⟨25/30⟩, ⟨4/5⟩ = ⟨24/30⟩, ⟨2/5⟩ = ⟨12/30⟩예요.","⟨5/6⟩ > ⟨4/5⟩ > ⟨2/5⟩ — 가장 많이 마신 사람은 나은이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#5','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',3,'error','auto','⟨4/9⟩와 ⟨5/11⟩ 중 더 큰 수를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u3-X10','M5-1-u3-X14']::text[],true,'{"seq":5,"concept":"M5-1-u3-C7","difficulty":3,"kind":"error","stem":"⟨4/9⟩와 ⟨5/11⟩ 중 더 큰 수를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「둘 다 ⟨1/2⟩보다 작으니까 크기가 같아.」","correct":true,"mis_target":"M5-1-u3-X10"},{"t":"예린 — 「99로 통분하면 ⟨44/99⟩, ⟨45/99⟩ — ⟨5/11⟩가 더 커.」","mis":"M5-1-u3-X14"},{"t":"지안 — 「⟨1/2⟩만으로는 가려지지 않으니 통분해야 해.」","mis":"M5-1-u3-X14"}],"explanation":["두 분수는 ⟨1/2⟩의 같은 쪽에 있어 기준만으로는 가릴 수 없어요.","99로 통분하면 ⟨4/9⟩ = ⟨44/99⟩, ⟨5/11⟩ = ⟨45/99⟩예요.","⟨5/11⟩가 더 커요. 수호는 같은 쪽에 있다는 것만 보고 크기가 같다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"⟨5/8⟩와 ⟨7/11⟩ 중 더 큰 수를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「둘 다 ⟨1/2⟩보다 크니까 크기가 같아.」","correct":true,"mis_target":"M5-1-u3-X10"},{"t":"가온 — 「88로 통분하면 ⟨55/88⟩, ⟨56/88⟩ — ⟨7/11⟩이 더 커.」","mis":"M5-1-u3-X14"},{"t":"다솜 — 「⟨1/2⟩만으로는 가려지지 않으니 통분해야 해.」","mis":"M5-1-u3-X14"}],"explanation":["두 분수는 ⟨1/2⟩의 같은 쪽에 있어 기준만으로는 가릴 수 없어요.","88로 통분하면 ⟨5/8⟩ = ⟨55/88⟩, ⟨7/11⟩ = ⟨56/88⟩이에요.","⟨7/11⟩이 더 커요. 윤슬은 같은 쪽에 있다는 것만 보고 크기가 같다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#6','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',3,'sa','auto','가, 나, 다, 라 네 휴대 전화의 배터리가 각각 ⟨3/4⟩, ⟨2/5⟩, ⟨3/7⟩, ⟨5/6⟩만큼 남아 있어요. 가장 많이 남은 전화와 가장 적게 남은 전화의 배터리를 나타낸 두 분수의 분모의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u3-C7","difficulty":3,"kind":"sa","stem":"가, 나, 다, 라 네 휴대 전화의 배터리가 각각 ⟨3/4⟩, ⟨2/5⟩, ⟨3/7⟩, ⟨5/6⟩만큼 남아 있어요. 가장 많이 남은 전화와 가장 적게 남은 전화의 배터리를 나타낸 두 분수의 분모의 합은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["⟨1/2⟩ 기준으로 먼저 갈라요 — 3 × 2 = 6이 4보다 커서 ⟨3/4⟩ > ⟨1/2⟩ · 2 × 2 = 4가 5보다 작아서 ⟨2/5⟩ < ⟨1/2⟩ · 3 × 2 = 6이 7보다 작아서 ⟨3/7⟩ < ⟨1/2⟩ · 5 × 2 = 10이 6보다 커서 ⟨5/6⟩ > ⟨1/2⟩.","같은 쪽끼리 견주면 가장 많이 남은 것은 ⟨5/6⟩, 가장 적게 남은 것은 ⟨2/5⟩예요.","분모의 합은 6 + 5 = 11이에요."],"variant_rule":{"alt":[{"stem":"가, 나, 다, 라 네 휴대 전화의 배터리가 각각 ⟨2/9⟩, ⟨5/7⟩, ⟨2/7⟩, ⟨9/10⟩만큼 남아 있어요. 가장 많이 남은 전화와 가장 적게 남은 전화의 배터리를 나타낸 두 분수의 분모의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨1/2⟩ 기준으로 먼저 갈라요 — 2 × 2 = 4가 9보다 작아서 ⟨2/9⟩ < ⟨1/2⟩ · 5 × 2 = 10이 7보다 커서 ⟨5/7⟩ > ⟨1/2⟩ · 2 × 2 = 4가 7보다 작아서 ⟨2/7⟩ < ⟨1/2⟩ · 9 × 2 = 18이 10보다 커서 ⟨9/10⟩ > ⟨1/2⟩.","같은 쪽끼리 견주면 가장 많이 남은 것은 ⟨9/10⟩, 가장 적게 남은 것은 ⟨2/9⟩예요.","분모의 합은 10 + 9 = 19예요."]},{"stem":"가, 나, 다, 라 네 휴대 전화의 배터리가 각각 ⟨3/5⟩, ⟨1/6⟩, ⟨2/3⟩, ⟨1/5⟩만큼 남아 있어요. 가장 많이 남은 전화와 가장 적게 남은 전화의 배터리를 나타낸 두 분수의 분모의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1/2⟩ 기준으로 먼저 갈라요 — 3 × 2 = 6이 5보다 커서 ⟨3/5⟩ > ⟨1/2⟩ · 1 × 2 = 2가 6보다 작아서 ⟨1/6⟩ < ⟨1/2⟩ · 2 × 2 = 4가 3보다 커서 ⟨2/3⟩ > ⟨1/2⟩ · 1 × 2 = 2가 5보다 작아서 ⟨1/5⟩ < ⟨1/2⟩.","같은 쪽끼리 견주면 가장 많이 남은 것은 ⟨2/3⟩, 가장 적게 남은 것은 ⟨1/6⟩이에요.","분모의 합은 3 + 6 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#7','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',3,'ox','auto','⟨7/8⟩과 ⟨9/10⟩는 둘 다 1에서 조각 하나만 모자라니, 모자란 조각이 더 작은 ⟨9/10⟩가 더 커요.',ARRAY['M5-1-u3-X09']::text[],true,'{"seq":7,"concept":"M5-1-u3-C7","difficulty":3,"kind":"ox","stem":"⟨7/8⟩과 ⟨9/10⟩는 둘 다 1에서 조각 하나만 모자라니, 모자란 조각이 더 작은 ⟨9/10⟩가 더 커요.","answer":"O","reason_options":[{"t":"1보다 ⟨1/8⟩, ⟨1/10⟩만큼 작고 ⟨1/10⟩이 ⟨1/8⟩보다 작으므로","correct":true},{"t":"분자 9가 7보다 크므로","mis":"M5-1-u3-X09"}],"mis":"M5-1-u3-X09","explanation":["⟨7/8⟩은 1보다 ⟨1/8⟩, ⟨9/10⟩는 1보다 ⟨1/10⟩만큼 작아요.","⟨1/10⟩ < ⟨1/8⟩ — 덜 모자란 쪽이 커요.","그래서 ⟨7/8⟩ < ⟨9/10⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩와 ⟨3/4⟩은 둘 다 1에서 조각 하나만 모자라니 크기가 같아요.","answer":"X","reason_options":[{"t":"모자란 조각 ⟨1/3⟩이 ⟨1/4⟩보다 커서 ⟨2/3⟩가 더 작으므로","correct":true},{"t":"모자란 조각이 하나씩이면 언제나 크기가 같으므로","mis":"M5-1-u3-X09"}],"explanation":["⟨2/3⟩는 1보다 ⟨1/3⟩, ⟨3/4⟩은 1보다 ⟨1/4⟩만큼 작아요.","⟨1/3⟩ > ⟨1/4⟩ — 더 많이 모자란 쪽이 작아요.","그래서 ⟨2/3⟩ < ⟨3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#8','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',4,'mc','auto','충전량이 각각 ⟨5/12⟩, ⟨3/8⟩, ⟨4/9⟩, ⟨7/18⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X11','M5-1-u3-X09']::text[],true,'{"seq":8,"concept":"M5-1-u3-C7","difficulty":4,"kind":"mc","stem":"충전량이 각각 ⟨5/12⟩, ⟨3/8⟩, ⟨4/9⟩, ⟨7/18⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨5/12⟩","mis":"M5-1-u3-X13"},{"t":"⟨3/8⟩","mis":"M5-1-u3-X11"},{"t":"⟨7/18⟩","mis":"M5-1-u3-X09"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 72로 나타내면 ⟨5/12⟩ = ⟨30/72⟩, ⟨3/8⟩ = ⟨27/72⟩, ⟨4/9⟩ = ⟨32/72⟩, ⟨7/18⟩ = ⟨28/72⟩이에요.","가장 큰 것은 ⟨4/9⟩예요."],"variant_rule":{"alt":[{"stem":"충전량이 각각 ⟨7/12⟩, ⟨5/8⟩, ⟨11/18⟩, ⟨5/9⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u3-X13"},{"t":"⟨11/18⟩","mis":"M5-1-u3-X09"},{"t":"⟨5/9⟩","mis":"M5-1-u3-X11"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 72로 나타내면 ⟨7/12⟩ = ⟨42/72⟩, ⟨5/8⟩ = ⟨45/72⟩, ⟨11/18⟩ = ⟨44/72⟩, ⟨5/9⟩ = ⟨40/72⟩이에요.","가장 큰 것은 ⟨5/8⟩예요."]},{"stem":"충전량이 각각 ⟨3/10⟩, ⟨2/5⟩, ⟨7/20⟩, ⟨1/4⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-1-u3-X09"},{"t":"⟨7/20⟩","mis":"M5-1-u3-X09"},{"t":"⟨1/4⟩","mis":"M5-1-u3-X11"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 20으로 나타내면 ⟨3/10⟩ = ⟨6/20⟩, ⟨2/5⟩ = ⟨8/20⟩, ⟨7/20⟩ = ⟨7/20⟩, ⟨1/4⟩ = ⟨5/20⟩예요.","가장 큰 것은 ⟨2/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#9','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',4,'essay','teacher','충전량 ⟨5/7⟩, ⟨1/3⟩, ⟨5/8⟩를 통분하지 않고 큰 것부터 차례로 늘어놓는 과정을 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C7","difficulty":4,"kind":"essay","stem":"충전량 ⟨5/7⟩, ⟨1/3⟩, ⟨5/8⟩를 통분하지 않고 큰 것부터 차례로 늘어놓는 과정을 설명하세요.","answer_guide":{"answer":"예: 먼저 ⟨1/2⟩을 기준으로 갈라 본다. ⟨1/3⟩은 분자 1을 2배 한 2가 3보다 작아 ⟨1/2⟩보다 작고, ⟨5/7⟩와 ⟨5/8⟩는 ⟨1/2⟩보다 크다. ⟨5/7⟩와 ⟨5/8⟩는 분자가 5로 같으니 분모가 작은 ⟨5/7⟩가 더 크다. 그래서 ⟨5/7⟩, ⟨5/8⟩, ⟨1/3⟩ 차례이다.","scoring_points":["⟨1/2⟩을 기준으로 ⟨1/3⟩을 먼저 가려냈는가","분자가 같은 두 분수를 분모로 견주었는가","⟨5/7⟩, ⟨5/8⟩, ⟨1/3⟩ 차례로 바르게 썼는가"]},"explanation":["⟨1/3⟩ < ⟨1/2⟩, ⟨5/7⟩와 ⟨5/8⟩는 ⟨1/2⟩보다 커요.","분자가 같으니 분모가 작은 ⟨5/7⟩가 커요.","⟨5/7⟩ > ⟨5/8⟩ > ⟨1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_L07_challenge#10','math',5,1,'u3','L07','g5_1_math_u3_L07_challenge','lesson_challenge','M5-1-u3-C7',4,'essay','teacher','⟨3/7⟩과 ⟨5/11⟩처럼 ⟨1/2⟩ 기준으로도, 같은 분자·같은 분모로도 견줄 수 없을 때 어떻게 견주는지 설명하고 어느 것이 더 큰지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C7","difficulty":4,"kind":"essay","stem":"⟨3/7⟩과 ⟨5/11⟩처럼 ⟨1/2⟩ 기준으로도, 같은 분자·같은 분모로도 견줄 수 없을 때 어떻게 견주는지 설명하고 어느 것이 더 큰지 쓰세요.","answer_guide":{"answer":"예: 두 분수 모두 ⟨1/2⟩보다 작고 분모와 분자가 모두 달라 기댈 곳이 없으므로 통분한다. 7과 11의 최소공배수 77로 통분하면 ⟨3/7⟩ = ⟨33/77⟩, ⟨5/11⟩ = ⟨35/77⟩이다. 분자를 견주면 35가 더 크므로 ⟨5/11⟩가 더 크다.","scoring_points":["기댈 곳이 없어 통분해야 한다고 썼는가","77로 바르게 통분했는가","⟨5/11⟩가 더 크다고 맺었는가"]},"explanation":["⟨3/7⟩과 ⟨5/11⟩는 둘 다 ⟨1/2⟩보다 작아요.","77로 통분하면 ⟨3/7⟩ = ⟨33/77⟩, ⟨5/11⟩ = ⟨35/77⟩예요.","그래서 ⟨3/7⟩ < ⟨5/11⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#1','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C1',1,'mc','auto','같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":1,"concept":"M5-1-u3-C1","difficulty":1,"kind":"mc","stem":"같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/2⟩ = ⟨2/4⟩","correct":true},{"t":"⟨1/2⟩ < ⟨2/4⟩","mis":"M5-1-u3-X04"},{"t":"⟨1/2⟩ > ⟨2/4⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 2칸 중 1칸, 아래 띠는 4칸 중 2칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨1/2⟩ = ⟨2/4⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"label":"⟨1/2⟩"},{"den":4,"num":2,"label":"⟨2/4⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#2','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C1',2,'mc','auto','⟨1/2⟩과 크기가 같은 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":2,"concept":"M5-1-u3-C1","difficulty":2,"kind":"mc","stem":"⟨1/2⟩과 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨2/4⟩","mis":"M5-1-u3-X04"},{"t":"⟨4/8⟩","mis":"M5-1-u3-X04"},{"t":"⟨5/10⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨1/2⟩ = ⟨2/4⟩ = ⟨4/8⟩ = ⟨5/10⟩예요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨3/5⟩은 ⟨1/2⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨3/5⟩ ≠ ⟨1/2⟩ — 크기가 같은 분수가 아닌 것은 ⟨3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#3','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C2',1,'sa','auto','⟨2/3⟩ = ⟨□/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":1,"kind":"sa","stem":"⟨2/3⟩ = ⟨□/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분모 3에 4를 곱해 12가 되었어요 — 3 × 4 = 12.","분자에도 같은 수 4를 곱해요 — 2 × 4 = 8.","⟨2/3⟩ = ⟨8/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#4','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C2',1,'mc','auto','⟨2/5⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],false,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨2/5⟩의 분모와 분자에 각각 3을 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨6/15⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-1-u3-X01"},{"t":"⟨6/5⟩","mis":"M5-1-u3-X02"},{"t":"⟨2/15⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 5 × 3 = 15, 분자 2 × 3 = 6이에요.","⟨2/5⟩ = ⟨6/15⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#5','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C2',3,'sa','auto','⟨3/4⟩과 크기가 같은 분수 중 분모가 20보다 크고 40보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨3/4⟩과 크기가 같은 분수 중 분모가 20보다 크고 40보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["⟨3/4⟩과 크기가 같은 분수의 분모는 4의 배수예요.","20보다 크고 40보다 작은 4의 배수는 24, 28, 32, 36이에요.","⟨18/24⟩, ⟨21/28⟩, ⟨24/32⟩, ⟨27/36⟩ — 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#6','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C3',1,'mc','auto','⟨12/18⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02']::text[],false,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨12/18⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨6/9⟩","mis":"M5-1-u3-X05"},{"t":"⟨4/6⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/18⟩","mis":"M5-1-u3-X02"}],"explanation":["12와 18의 공약수는 1, 2, 3, 6, 최대공약수는 6이에요.","최대공약수로 나누면 한 번에 끝나요 — 12 ÷ 6 = 2, 18 ÷ 6 = 3.","⟨12/18⟩ = ⟨2/3⟩ — 공약수가 1뿐이라 기약분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#7','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C3',2,'mc','auto','기약분수인 것은 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],false,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"기약분수인 것은 어느 것인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨6/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨4/14⟩","mis":"M5-1-u3-X05"},{"t":"⟨9/21⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨6/10⟩은 2로 약분돼요 · ⟨4/14⟩는 2로 약분돼요 · ⟨9/21⟩는 3으로 약분돼요.","5와 9의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨5/9⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#8','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C3',3,'sa','auto','⟨36/48⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"⟨36/48⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["36과 48의 공약수는 1, 2, 3, 4, 6, 12예요.","1이 아닌 공약수 2, 3, 4, 6, 12로 한 번씩 나누어요.","⟨18/24⟩, ⟨12/16⟩, ⟨9/12⟩, ⟨6/8⟩, ⟨3/4⟩ — 모두 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#9','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C3',3,'sa','auto','분모가 48인 분수를 약분했더니 ⟨3/8⟩이 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"분모가 48인 분수를 약분했더니 ⟨3/8⟩이 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 8을 48로 만들려면 8 × 6 = 48 — 6을 곱해요.","분자도 3 × 6 = 18 — 처음 분수는 ⟨18/48⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#10','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C4',1,'sa','auto','⟨1/6⟩과 ⟨3/8⟩을 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C4","difficulty":1,"kind":"sa","stem":"⟨1/6⟩과 ⟨3/8⟩을 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["6의 배수: 6, 12, 18, 24, 30 … · 8의 배수: 8, 16, 24, 32 …","처음으로 함께 나오는 수가 최소공배수 24예요.","그래서 공통분모는 24 — ⟨4/24⟩, ⟨9/24⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#11','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C4',2,'mc','auto','⟨1/6⟩과 ⟨3/8⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X13','M5-1-u3-X08']::text[],false,'{"seq":11,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨1/6⟩과 ⟨3/8⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨4/24⟩, ⟨9/24⟩","correct":true},{"t":"⟨1/24⟩, ⟨3/24⟩","mis":"M5-1-u3-X07"},{"t":"⟨3/24⟩, ⟨12/24⟩","mis":"M5-1-u3-X13"},{"t":"⟨8/48⟩, ⟨18/48⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 24예요.","⟨1/6⟩의 분모와 분자에 4를, ⟨3/8⟩의 분모와 분자에 3을 곱해요.","⟨1/6⟩ = ⟨4/24⟩, ⟨3/8⟩ = ⟨9/24⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#12','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C4',2,'mc','auto','⟨1/6⟩과 ⟨1/4⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X08']::text[],false,'{"seq":12,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨1/6⟩과 ⟨1/4⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"18","correct":true},{"t":"12","mis":"M5-1-u3-X08"},{"t":"24","mis":"M5-1-u3-X08"},{"t":"36","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 6과 4의 공배수예요.","6과 4의 공배수는 12, 24, 36 …이에요.","18은 6의 배수이지만 4의 배수는 아니에요 — 그래서 공통분모가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#13','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C4',4,'sa','auto','⟨1/2⟩, ⟨2/3⟩, ⟨3/4⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-1-u3-C4","difficulty":4,"kind":"sa","stem":"⟨1/2⟩, ⟨2/3⟩, ⟨3/4⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["세 분모 2, 3, 4의 최소공배수는 12예요.","⟨1/2⟩ = ⟨6/12⟩, ⟨2/3⟩ = ⟨8/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요.","분자의 합은 6 + 8 + 9 = 23이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#14','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C5',1,'mc','auto','⟨1/4⟩과 ⟨1/7⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":14,"concept":"M5-1-u3-C5","difficulty":1,"kind":"mc","stem":"⟨1/4⟩과 ⟨1/7⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1/7⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 4칸과 7칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/4⟩ > ⟨1/7⟩이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"⟨1/4⟩"},{"den":7,"num":1,"label":"⟨1/7⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#15','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C5',2,'mc','auto','두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#16','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C5',3,'mc','auto','⟨3/4⟩, ⟨5/8⟩, ⟨2/3⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],false,'{"seq":16,"concept":"M5-1-u3-C5","difficulty":3,"kind":"mc","stem":"⟨3/4⟩, ⟨5/8⟩, ⟨2/3⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩, ⟨2/3⟩, ⟨3/4⟩","correct":true},{"t":"⟨3/4⟩, ⟨2/3⟩, ⟨5/8⟩","mis":"M5-1-u3-X14"},{"t":"⟨2/3⟩, ⟨3/4⟩, ⟨5/8⟩","mis":"M5-1-u3-X09"},{"t":"⟨3/4⟩, ⟨5/8⟩, ⟨2/3⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 24로 나타내면 ⟨3/4⟩ = ⟨18/24⟩, ⟨5/8⟩ = ⟨15/24⟩, ⟨2/3⟩ = ⟨16/24⟩이에요.","견주면 ⟨15/24⟩ < ⟨16/24⟩ < ⟨18/24⟩이에요.","그래서 작은 것부터 쓰면 ⟨5/8⟩, ⟨2/3⟩, ⟨3/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#17','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C5',3,'sa','auto','1부터 9까지의 수 중에서 ⟨□/10⟩ < ⟨3/4⟩이 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u3-C5","difficulty":3,"kind":"sa","stem":"1부터 9까지의 수 중에서 ⟨□/10⟩ < ⟨3/4⟩이 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7","7개"],"explanation":["20으로 통분하면 ⟨3/4⟩ = ⟨15/20⟩이고, ⟨□/10⟩의 분자는 □ × 2가 돼요.","□ × 2가 15보다 작아야 해요 — □는 1, 2, 3, 4, 5, 6, 7.","모두 7개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#18','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C6',1,'mc','auto','⟨2/5⟩를 소수로 나타내면 얼마인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X13']::text[],false,'{"seq":18,"concept":"M5-1-u3-C6","difficulty":1,"kind":"mc","stem":"⟨2/5⟩를 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"0.25","mis":"M5-1-u3-X12"},{"t":"0.2","mis":"M5-1-u3-X12"},{"t":"0.5","mis":"M5-1-u3-X13"}],"explanation":["분모를 10으로 만들어요 — 분모와 분자에 2를 곱해요.","⟨2/5⟩ = ⟨4/10⟩예요.","⟨4/10⟩ = 0.4 — 소수로 0.4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#19','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C6',2,'mc','auto','0.8을 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X12']::text[],false,'{"seq":19,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.8을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨8/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨8/100⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/8⟩","mis":"M5-1-u3-X12"}],"explanation":["0.8 = ⟨8/10⟩이에요 — 소수 한 자리 수라 분모가 10이에요.","8과 10의 최대공약수 2로 약분해요 — 8 ÷ 2 = 4, 10 ÷ 2 = 5.","⟨8/10⟩ = ⟨4/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#20','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C6',2,'mc','auto','0.9와 ⟨4/5⟩ 중 더 큰 수는 어느 것인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],false,'{"seq":20,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.9와 ⟨4/5⟩ 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.9","correct":true},{"t":"⟨4/5⟩","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨4/5⟩ = 0.8.","0.9 > 0.8이에요.","그래서 더 큰 수는 0.9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#21','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C6',4,'sa','auto','⟨1/4⟩, 0.2, ⟨6/25⟩, 0.23, ⟨11/50⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u3-C6","difficulty":4,"kind":"sa","stem":"⟨1/4⟩, 0.2, ⟨6/25⟩, 0.23, ⟨11/50⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["분수를 소수로 바꾸어요 — ⟨1/4⟩ = 0.25, ⟨6/25⟩ = 0.24, ⟨11/50⟩ = 0.22.","가장 큰 수는 0.25예요.","□□에 알맞은 수는 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#22','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C7',1,'mc','auto','⟨4/7⟩, ⟨2/5⟩, ⟨7/9⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?',ARRAY['M5-1-u3-X10']::text[],false,'{"seq":22,"concept":"M5-1-u3-C7","difficulty":1,"kind":"mc","stem":"⟨4/7⟩, ⟨2/5⟩, ⟨7/9⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨4/7⟩","mis":"M5-1-u3-X10"},{"t":"⟨7/9⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","4 × 2 = 8이 7보다 커서 ⟨4/7⟩ > ⟨1/2⟩ · 2 × 2 = 4가 5보다 작아서 ⟨2/5⟩ < ⟨1/2⟩ · 7 × 2 = 14가 9보다 커서 ⟨7/9⟩ > ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨2/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#23','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C7',2,'mc','auto','⟨2/7⟩와 ⟨2/9⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":23,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨2/7⟩와 ⟨2/9⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 2개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨2/7⟩ > ⟨2/9⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#24','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C7',3,'mc','auto','세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 민서 ⟨2/5⟩, 지후 ⟨3/4⟩, 라희 ⟨5/7⟩. 가장 많이 마신 사람은 누구인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X09']::text[],false,'{"seq":24,"concept":"M5-1-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 민서 ⟨2/5⟩, 지후 ⟨3/4⟩, 라희 ⟨5/7⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"지후","correct":true},{"t":"민서","mis":"M5-1-u3-X13"},{"t":"라희","mis":"M5-1-u3-X09"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 140으로 나타내면 ⟨2/5⟩ = ⟨56/140⟩, ⟨3/4⟩ = ⟨105/140⟩, ⟨5/7⟩ = ⟨100/140⟩이에요.","⟨3/4⟩ > ⟨5/7⟩ > ⟨2/5⟩ — 가장 많이 마신 사람은 지후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_a#25','math',5,1,'u3','','g5_1_math_u3_review_a','unit_review','M5-1-u3-C7',4,'mc','auto','충전량이 각각 ⟨3/7⟩, ⟨5/14⟩, ⟨2/5⟩, ⟨9/20⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X09','M5-1-u3-X11']::text[],false,'{"seq":25,"concept":"M5-1-u3-C7","difficulty":4,"kind":"mc","stem":"충전량이 각각 ⟨3/7⟩, ⟨5/14⟩, ⟨2/5⟩, ⟨9/20⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨3/7⟩","mis":"M5-1-u3-X13"},{"t":"⟨5/14⟩","mis":"M5-1-u3-X09"},{"t":"⟨2/5⟩","mis":"M5-1-u3-X11"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 140으로 나타내면 ⟨3/7⟩ = ⟨60/140⟩, ⟨5/14⟩ = ⟨50/140⟩, ⟨2/5⟩ = ⟨56/140⟩, ⟨9/20⟩ = ⟨63/140⟩이에요.","가장 큰 것은 ⟨9/20⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#1','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C1',1,'mc','auto','같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":1,"concept":"M5-1-u3-C1","difficulty":1,"kind":"mc","stem":"같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨2/3⟩ = ⟨4/6⟩","correct":true},{"t":"⟨2/3⟩ < ⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨2/3⟩ > ⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 3칸 중 2칸, 아래 띠는 6칸 중 4칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨2/3⟩ = ⟨4/6⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":2,"label":"⟨2/3⟩"},{"den":6,"num":4,"label":"⟨4/6⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#2','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C1',2,'mc','auto','⟨2/3⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":2,"concept":"M5-1-u3-C1","difficulty":2,"kind":"mc","stem":"⟨2/3⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/6⟩","mis":"M5-1-u3-X04"},{"t":"⟨6/9⟩","mis":"M5-1-u3-X04"},{"t":"⟨10/15⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨2/3⟩ = ⟨4/6⟩ = ⟨6/9⟩ = ⟨10/15⟩이에요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨3/4⟩은 ⟨2/3⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨3/4⟩ ≠ ⟨2/3⟩ — 크기가 같은 분수가 아닌 것은 ⟨3/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#3','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C2',1,'sa','auto','⟨3/4⟩ = ⟨□/20⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":1,"kind":"sa","stem":"⟨3/4⟩ = ⟨□/20⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["분모 4에 5를 곱해 20이 되었어요 — 4 × 5 = 20.","분자에도 같은 수 5를 곱해요 — 3 × 5 = 15.","⟨3/4⟩ = ⟨15/20⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#4','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C2',1,'mc','auto','⟨12/18⟩의 분모와 분자를 각각 6으로 나누면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],false,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨12/18⟩의 분모와 분자를 각각 6으로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨6/12⟩","mis":"M5-1-u3-X01"},{"t":"⟨2/18⟩","mis":"M5-1-u3-X02"},{"t":"⟨12/3⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 18 ÷ 6 = 3, 분자 12 ÷ 6 = 2예요.","⟨12/18⟩ = ⟨2/3⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#5','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C2',3,'sa','auto','⟨2/3⟩와 크기가 같은 분수 중 분모가 10보다 크고 25보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨2/3⟩와 크기가 같은 분수 중 분모가 10보다 크고 25보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["⟨2/3⟩와 크기가 같은 분수의 분모는 3의 배수예요.","10보다 크고 25보다 작은 3의 배수는 12, 15, 18, 21, 24예요.","⟨8/12⟩, ⟨10/15⟩, ⟨12/18⟩, ⟨14/21⟩, ⟨16/24⟩ — 모두 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#6','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C3',1,'mc','auto','⟨20/28⟩을 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02']::text[],false,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨20/28⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/7⟩","correct":true},{"t":"⟨10/14⟩","mis":"M5-1-u3-X05"},{"t":"⟨5/28⟩","mis":"M5-1-u3-X02"},{"t":"⟨20/7⟩","mis":"M5-1-u3-X02"}],"explanation":["20과 28의 공약수는 1, 2, 4, 최대공약수는 4예요.","최대공약수로 나누면 한 번에 끝나요 — 20 ÷ 4 = 5, 28 ÷ 4 = 7.","⟨20/28⟩ = ⟨5/7⟩ — 공약수가 1뿐이라 기약분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#7','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C3',2,'mc','auto','기약분수인 것은 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],false,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"기약분수인 것은 어느 것인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨8/12⟩","mis":"M5-1-u3-X05"},{"t":"⟨6/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨10/16⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨8/12⟩은 4로 약분돼요 · ⟨6/15⟩은 3으로 약분돼요 · ⟨10/16⟩은 2로 약분돼요.","7과 12의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨7/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#8','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C3',3,'sa','auto','⟨24/40⟩를 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"⟨24/40⟩를 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["24와 40의 공약수는 1, 2, 4, 8이에요.","1이 아닌 공약수 2, 4, 8로 한 번씩 나누어요.","⟨12/20⟩, ⟨6/10⟩, ⟨3/5⟩ — 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#9','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C3',3,'sa','auto','분모가 36인 분수를 약분했더니 ⟨5/9⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"분모가 36인 분수를 약분했더니 ⟨5/9⟩가 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 9를 36으로 만들려면 9 × 4 = 36 — 4를 곱해요.","분자도 5 × 4 = 20 — 처음 분수는 ⟨20/36⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#10','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C4',1,'sa','auto','⟨1/4⟩과 ⟨2/5⟩를 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C4","difficulty":1,"kind":"sa","stem":"⟨1/4⟩과 ⟨2/5⟩를 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["4의 배수: 4, 8, 12, 16, 20, 24 … · 5의 배수: 5, 10, 15, 20, 25 …","처음으로 함께 나오는 수가 최소공배수 20이에요.","그래서 공통분모는 20 — ⟨5/20⟩, ⟨8/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#11','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C4',2,'mc','auto','⟨3/4⟩과 ⟨1/10⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X13','M5-1-u3-X08']::text[],false,'{"seq":11,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩과 ⟨1/10⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨15/20⟩, ⟨2/20⟩","correct":true},{"t":"⟨3/20⟩, ⟨1/20⟩","mis":"M5-1-u3-X07"},{"t":"⟨6/20⟩, ⟨5/20⟩","mis":"M5-1-u3-X13"},{"t":"⟨30/40⟩, ⟨4/40⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 20이에요.","⟨3/4⟩의 분모와 분자에 5를, ⟨1/10⟩의 분모와 분자에 2를 곱해요.","⟨3/4⟩ = ⟨15/20⟩, ⟨1/10⟩ = ⟨2/20⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#12','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C4',2,'mc','auto','⟨2/5⟩와 ⟨1/3⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X08']::text[],false,'{"seq":12,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨2/5⟩와 ⟨1/3⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"25","correct":true},{"t":"15","mis":"M5-1-u3-X08"},{"t":"30","mis":"M5-1-u3-X08"},{"t":"45","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 5와 3의 공배수예요.","5와 3의 공배수는 15, 30, 45 …이에요.","25는 5의 배수이지만 3의 배수는 아니에요 — 그래서 공통분모가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#13','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C4',4,'sa','auto','⟨1/6⟩, ⟨3/4⟩, ⟨2/3⟩를 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-1-u3-C4","difficulty":4,"kind":"sa","stem":"⟨1/6⟩, ⟨3/4⟩, ⟨2/3⟩를 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["세 분모 6, 4, 3의 최소공배수는 12예요.","⟨1/6⟩ = ⟨2/12⟩, ⟨3/4⟩ = ⟨9/12⟩, ⟨2/3⟩ = ⟨8/12⟩이에요.","분자의 합은 2 + 9 + 8 = 19예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#14','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C5',1,'mc','auto','⟨1/10⟩과 ⟨1/3⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":14,"concept":"M5-1-u3-C5","difficulty":1,"kind":"mc","stem":"⟨1/10⟩과 ⟨1/3⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/10⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 3칸과 10칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/3⟩ > ⟨1/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":1,"label":"⟨1/10⟩"},{"den":3,"num":1,"label":"⟨1/3⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#15','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C5',2,'mc','auto','두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#16','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C5',3,'mc','auto','⟨5/6⟩, ⟨3/4⟩, ⟨7/9⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],false,'{"seq":16,"concept":"M5-1-u3-C5","difficulty":3,"kind":"mc","stem":"⟨5/6⟩, ⟨3/4⟩, ⟨7/9⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩, ⟨7/9⟩, ⟨3/4⟩","correct":true},{"t":"⟨3/4⟩, ⟨7/9⟩, ⟨5/6⟩","mis":"M5-1-u3-X14"},{"t":"⟨7/9⟩, ⟨5/6⟩, ⟨3/4⟩","mis":"M5-1-u3-X09"},{"t":"⟨5/6⟩, ⟨3/4⟩, ⟨7/9⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 36으로 나타내면 ⟨5/6⟩ = ⟨30/36⟩, ⟨3/4⟩ = ⟨27/36⟩, ⟨7/9⟩ = ⟨28/36⟩이에요.","견주면 ⟨30/36⟩ > ⟨28/36⟩ > ⟨27/36⟩이에요.","그래서 큰 것부터 쓰면 ⟨5/6⟩, ⟨7/9⟩, ⟨3/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#17','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C5',3,'sa','auto','1부터 11까지의 수 중에서 ⟨□/12⟩ > ⟨2/3⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u3-C5","difficulty":3,"kind":"sa","stem":"1부터 11까지의 수 중에서 ⟨□/12⟩ > ⟨2/3⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["분모를 12로 맞추면 ⟨2/3⟩ = ⟨8/12⟩이에요.","□가 8보다 커야 해요 — □는 9, 10, 11.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#18','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C6',1,'mc','auto','⟨3/4⟩을 소수로 나타내면 얼마인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X13']::text[],false,'{"seq":18,"concept":"M5-1-u3-C6","difficulty":1,"kind":"mc","stem":"⟨3/4⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.34","mis":"M5-1-u3-X12"},{"t":"0.3","mis":"M5-1-u3-X12"},{"t":"0.25","mis":"M5-1-u3-X13"}],"explanation":["분모를 100으로 만들어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","⟨75/100⟩ = 0.75 — 소수로 0.75예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#19','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C6',2,'mc','auto','0.35를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X12']::text[],false,'{"seq":19,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.35를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/20⟩","correct":true},{"t":"⟨35/100⟩","mis":"M5-1-u3-X05"},{"t":"⟨35/10⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/35⟩","mis":"M5-1-u3-X12"}],"explanation":["0.35 = ⟨35/100⟩예요 — 소수 두 자리 수라 분모가 100이에요.","35와 100의 최대공약수 5로 약분해요 — 35 ÷ 5 = 7, 100 ÷ 5 = 20.","⟨35/100⟩ = ⟨7/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#20','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C6',2,'mc','auto','⟨1/4⟩과 0.3 중 더 큰 수는 어느 것인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],false,'{"seq":20,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"⟨1/4⟩과 0.3 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.3","correct":true},{"t":"⟨1/4⟩","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨1/4⟩ = 0.25.","0.3 > 0.25예요.","그래서 더 큰 수는 0.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#21','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C6',4,'sa','auto','⟨4/5⟩, 0.78, ⟨17/20⟩, 0.82, ⟨21/25⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u3-C6","difficulty":4,"kind":"sa","stem":"⟨4/5⟩, 0.78, ⟨17/20⟩, 0.82, ⟨21/25⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["분수를 소수로 바꾸어요 — ⟨4/5⟩ = 0.8, ⟨17/20⟩ = 0.85, ⟨21/25⟩ = 0.84.","가장 큰 수는 0.85예요.","□□에 알맞은 수는 85예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#22','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C7',1,'mc','auto','⟨5/9⟩, ⟨6/11⟩, ⟨3/10⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?',ARRAY['M5-1-u3-X10']::text[],false,'{"seq":22,"concept":"M5-1-u3-C7","difficulty":1,"kind":"mc","stem":"⟨5/9⟩, ⟨6/11⟩, ⟨3/10⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨5/9⟩","mis":"M5-1-u3-X10"},{"t":"⟨6/11⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","5 × 2 = 10이 9보다 커서 ⟨5/9⟩ > ⟨1/2⟩ · 6 × 2 = 12가 11보다 커서 ⟨6/11⟩ > ⟨1/2⟩ · 3 × 2 = 6이 10보다 작아서 ⟨3/10⟩ < ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨3/10⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#23','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C7',2,'mc','auto','⟨5/12⟩와 ⟨5/8⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":23,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨5/12⟩와 ⟨5/8⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨5/12⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 5개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨5/8⟩ > ⟨5/12⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#24','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C7',3,'mc','auto','세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 보민 ⟨5/9⟩, 하윤 ⟨1/3⟩, 세아 ⟨4/7⟩. 가장 많이 마신 사람은 누구인가요?',ARRAY['M5-1-u3-X09','M5-1-u3-X13']::text[],false,'{"seq":24,"concept":"M5-1-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 보민 ⟨5/9⟩, 하윤 ⟨1/3⟩, 세아 ⟨4/7⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"세아","correct":true},{"t":"보민","mis":"M5-1-u3-X09"},{"t":"하윤","mis":"M5-1-u3-X13"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 63으로 나타내면 ⟨5/9⟩ = ⟨35/63⟩, ⟨1/3⟩ = ⟨21/63⟩, ⟨4/7⟩ = ⟨36/63⟩이에요.","⟨4/7⟩ > ⟨5/9⟩ > ⟨1/3⟩ — 가장 많이 마신 사람은 세아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_b#25','math',5,1,'u3','','g5_1_math_u3_review_b','unit_review','M5-1-u3-C7',4,'mc','auto','충전량이 각각 ⟨5/8⟩, ⟨7/12⟩, ⟨3/5⟩, ⟨13/20⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X09','M5-1-u3-X11']::text[],false,'{"seq":25,"concept":"M5-1-u3-C7","difficulty":4,"kind":"mc","stem":"충전량이 각각 ⟨5/8⟩, ⟨7/12⟩, ⟨3/5⟩, ⟨13/20⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨13/20⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-1-u3-X13"},{"t":"⟨7/12⟩","mis":"M5-1-u3-X09"},{"t":"⟨3/5⟩","mis":"M5-1-u3-X11"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 120으로 나타내면 ⟨5/8⟩ = ⟨75/120⟩, ⟨7/12⟩ = ⟨70/120⟩, ⟨3/5⟩ = ⟨72/120⟩, ⟨13/20⟩ = ⟨78/120⟩이에요.","가장 큰 것은 ⟨13/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#1','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C1',1,'mc','auto','같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":1,"concept":"M5-1-u3-C1","difficulty":1,"kind":"mc","stem":"같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/4⟩ = ⟨3/12⟩","correct":true},{"t":"⟨1/4⟩ < ⟨3/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨1/4⟩ > ⟨3/12⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 4칸 중 1칸, 아래 띠는 12칸 중 3칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 3배로 잘게 나누었을 뿐이에요.","그래서 ⟨1/4⟩ = ⟨3/12⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"⟨1/4⟩"},{"den":12,"num":3,"label":"⟨3/12⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#2','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C1',2,'mc','auto','⟨3/5⟩과 크기가 같은 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":2,"concept":"M5-1-u3-C1","difficulty":2,"kind":"mc","stem":"⟨3/5⟩과 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨6/10⟩","mis":"M5-1-u3-X04"},{"t":"⟨9/15⟩","mis":"M5-1-u3-X04"},{"t":"⟨12/20⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨3/5⟩ = ⟨6/10⟩ = ⟨9/15⟩ = ⟨12/20⟩예요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨4/6⟩는 ⟨3/5⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨4/6⟩ ≠ ⟨3/5⟩ — 크기가 같은 분수가 아닌 것은 ⟨4/6⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#3','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C2',1,'sa','auto','⟨1/6⟩ = ⟨□/18⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":1,"kind":"sa","stem":"⟨1/6⟩ = ⟨□/18⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 6에 3을 곱해 18이 되었어요 — 6 × 3 = 18.","분자에도 같은 수 3을 곱해요 — 1 × 3 = 3.","⟨1/6⟩ = ⟨3/18⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#4','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C2',1,'mc','auto','⟨3/7⟩의 분모와 분자에 각각 2를 곱하면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],false,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨3/7⟩의 분모와 분자에 각각 2를 곱하면 어떤 분수가 되나요?","options":[{"t":"⟨6/14⟩","correct":true},{"t":"⟨5/9⟩","mis":"M5-1-u3-X01"},{"t":"⟨6/7⟩","mis":"M5-1-u3-X02"},{"t":"⟨3/14⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 7 × 2 = 14, 분자 3 × 2 = 6이에요.","⟨3/7⟩ = ⟨6/14⟩ — 분모와 분자에 같은 수를 곱해 크기는 그대로예요.","분모와 분자에 같은 수를 더하면 크기가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#5','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C2',3,'sa','auto','⟨1/5⟩과 크기가 같은 분수 중 분모가 12보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨1/5⟩과 크기가 같은 분수 중 분모가 12보다 크고 30보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["⟨1/5⟩과 크기가 같은 분수의 분모는 5의 배수예요.","12보다 크고 30보다 작은 5의 배수는 15, 20, 25예요.","⟨3/15⟩, ⟨4/20⟩, ⟨5/25⟩ — 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#6','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C3',1,'mc','auto','⟨18/45⟩을 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02']::text[],false,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨18/45⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨6/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/45⟩","mis":"M5-1-u3-X02"},{"t":"⟨18/5⟩","mis":"M5-1-u3-X02"}],"explanation":["18과 45의 공약수는 1, 3, 9, 최대공약수는 9예요.","최대공약수로 나누면 한 번에 끝나요 — 18 ÷ 9 = 2, 45 ÷ 9 = 5.","⟨18/45⟩ = ⟨2/5⟩ — 공약수가 1뿐이라 기약분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#7','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C3',2,'mc','auto','기약분수인 것은 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],false,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"기약분수인 것은 어느 것인가요?","options":[{"t":"⟨9/16⟩","correct":true},{"t":"⟨12/16⟩","mis":"M5-1-u3-X05"},{"t":"⟨9/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨14/18⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨12/16⟩는 4로 약분돼요 · ⟨9/15⟩는 3으로 약분돼요 · ⟨14/18⟩는 2로 약분돼요.","9와 16의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨9/16⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#8','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C3',3,'sa','auto','⟨30/42⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"⟨30/42⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["30과 42의 공약수는 1, 2, 3, 6이에요.","1이 아닌 공약수 2, 3, 6으로 한 번씩 나누어요.","⟨15/21⟩, ⟨10/14⟩, ⟨5/7⟩ — 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#9','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C3',3,'sa','auto','분모가 54인 분수를 약분했더니 ⟨7/9⟩이 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"분모가 54인 분수를 약분했더니 ⟨7/9⟩이 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 9를 54로 만들려면 9 × 6 = 54 — 6을 곱해요.","분자도 7 × 6 = 42 — 처음 분수는 ⟨42/54⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#10','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C4',1,'sa','auto','⟨5/6⟩와 ⟨1/9⟩을 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C4","difficulty":1,"kind":"sa","stem":"⟨5/6⟩와 ⟨1/9⟩을 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["6의 배수: 6, 12, 18, 24 … · 9의 배수: 9, 18, 27 …","처음으로 함께 나오는 수가 최소공배수 18이에요.","그래서 공통분모는 18 — ⟨15/18⟩, ⟨2/18⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#11','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C4',2,'mc','auto','⟨2/9⟩와 ⟨5/6⟩를 두 분모의 최소공배수로 통분하면 어느 것인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X13','M5-1-u3-X08']::text[],false,'{"seq":11,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨2/9⟩와 ⟨5/6⟩를 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨4/18⟩, ⟨15/18⟩","correct":true},{"t":"⟨2/18⟩, ⟨5/18⟩","mis":"M5-1-u3-X07"},{"t":"⟨6/18⟩, ⟨10/18⟩","mis":"M5-1-u3-X13"},{"t":"⟨12/54⟩, ⟨45/54⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 18이에요.","⟨2/9⟩의 분모와 분자에 2를, ⟨5/6⟩의 분모와 분자에 3을 곱해요.","⟨2/9⟩ = ⟨4/18⟩, ⟨5/6⟩ = ⟨15/18⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#12','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C4',2,'mc','auto','⟨1/8⟩과 ⟨5/6⟩를 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X08']::text[],false,'{"seq":12,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨1/8⟩과 ⟨5/6⟩를 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"32","correct":true},{"t":"24","mis":"M5-1-u3-X08"},{"t":"48","mis":"M5-1-u3-X08"},{"t":"72","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 8과 6의 공배수예요.","8과 6의 공배수는 24, 48, 72 …이에요.","32는 8의 배수이지만 6의 배수는 아니에요 — 그래서 공통분모가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#13','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C4',4,'sa','auto','⟨1/5⟩, ⟨3/10⟩, ⟨1/2⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-1-u3-C4","difficulty":4,"kind":"sa","stem":"⟨1/5⟩, ⟨3/10⟩, ⟨1/2⟩을 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세 분모 5, 10, 2의 최소공배수는 10이에요.","⟨1/5⟩ = ⟨2/10⟩, ⟨3/10⟩ = ⟨3/10⟩, ⟨1/2⟩ = ⟨5/10⟩예요.","분자의 합은 2 + 3 + 5 = 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#14','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C5',1,'mc','auto','⟨1/6⟩과 ⟨1/9⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":14,"concept":"M5-1-u3-C5","difficulty":1,"kind":"mc","stem":"⟨1/6⟩과 ⟨1/9⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1/9⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 6칸과 9칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/6⟩ > ⟨1/9⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":1,"label":"⟨1/6⟩"},{"den":9,"num":1,"label":"⟨1/9⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#15','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C5',2,'mc','auto','두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#16','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C5',3,'mc','auto','⟨1/2⟩, ⟨3/5⟩, ⟨4/9⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],false,'{"seq":16,"concept":"M5-1-u3-C5","difficulty":3,"kind":"mc","stem":"⟨1/2⟩, ⟨3/5⟩, ⟨4/9⟩를 작은 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩, ⟨1/2⟩, ⟨3/5⟩","correct":true},{"t":"⟨3/5⟩, ⟨1/2⟩, ⟨4/9⟩","mis":"M5-1-u3-X14"},{"t":"⟨1/2⟩, ⟨3/5⟩, ⟨4/9⟩","mis":"M5-1-u3-X09"},{"t":"⟨1/2⟩, ⟨4/9⟩, ⟨3/5⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 90으로 나타내면 ⟨1/2⟩ = ⟨45/90⟩, ⟨3/5⟩ = ⟨54/90⟩, ⟨4/9⟩ = ⟨40/90⟩이에요.","견주면 ⟨40/90⟩ < ⟨45/90⟩ < ⟨54/90⟩예요.","그래서 작은 것부터 쓰면 ⟨4/9⟩, ⟨1/2⟩, ⟨3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#17','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C5',3,'sa','auto','1부터 9까지의 수 중에서 ⟨□/6⟩ < ⟨4/9⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u3-C5","difficulty":3,"kind":"sa","stem":"1부터 9까지의 수 중에서 ⟨□/6⟩ < ⟨4/9⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2","2개"],"explanation":["18로 통분하면 ⟨4/9⟩ = ⟨8/18⟩이고, ⟨□/6⟩의 분자는 □ × 3이 돼요.","□ × 3이 8보다 작아야 해요 — □는 1, 2.","모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#18','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C6',1,'mc','auto','⟨1/5⟩을 소수로 나타내면 얼마인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X13']::text[],false,'{"seq":18,"concept":"M5-1-u3-C6","difficulty":1,"kind":"mc","stem":"⟨1/5⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"0.2","correct":true},{"t":"0.15","mis":"M5-1-u3-X12"},{"t":"0.5","mis":"M5-1-u3-X12"},{"t":"0.1","mis":"M5-1-u3-X13"}],"explanation":["분모를 10으로 만들어요 — 분모와 분자에 2를 곱해요.","⟨1/5⟩ = ⟨2/10⟩예요.","⟨2/10⟩ = 0.2 — 소수로 0.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#19','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C6',2,'mc','auto','0.5를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X12']::text[],false,'{"seq":19,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.5를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨5/10⟩","mis":"M5-1-u3-X05"},{"t":"⟨5/100⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/5⟩","mis":"M5-1-u3-X12"}],"explanation":["0.5 = ⟨5/10⟩예요 — 소수 한 자리 수라 분모가 10이에요.","5와 10의 최대공약수 5로 약분해요 — 5 ÷ 5 = 1, 10 ÷ 5 = 2.","⟨5/10⟩ = ⟨1/2⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#20','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C6',2,'mc','auto','0.55와 ⟨3/5⟩ 중 더 큰 수는 어느 것인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],false,'{"seq":20,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.55와 ⟨3/5⟩ 중 더 큰 수는 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"0.55","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨3/5⟩ = 0.6.","0.6 > 0.55예요.","그래서 더 큰 수는 ⟨3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#21','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C6',4,'sa','auto','⟨2/5⟩, 0.38, ⟨9/25⟩, 0.41, ⟨19/50⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u3-C6","difficulty":4,"kind":"sa","stem":"⟨2/5⟩, 0.38, ⟨9/25⟩, 0.41, ⟨19/50⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["분수를 소수로 바꾸어요 — ⟨2/5⟩ = 0.4, ⟨9/25⟩ = 0.36, ⟨19/50⟩ = 0.38.","가장 큰 수는 0.41이에요.","□□에 알맞은 수는 41이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#22','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C7',1,'mc','auto','⟨2/9⟩, ⟨5/8⟩, ⟨3/4⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?',ARRAY['M5-1-u3-X10']::text[],false,'{"seq":22,"concept":"M5-1-u3-C7","difficulty":1,"kind":"mc","stem":"⟨2/9⟩, ⟨5/8⟩, ⟨3/4⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-1-u3-X10"},{"t":"⟨3/4⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","2 × 2 = 4가 9보다 작아서 ⟨2/9⟩ < ⟨1/2⟩ · 5 × 2 = 10이 8보다 커서 ⟨5/8⟩ > ⟨1/2⟩ · 3 × 2 = 6이 4보다 커서 ⟨3/4⟩ > ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨2/9⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#23','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C7',2,'mc','auto','⟨3/4⟩과 ⟨3/10⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":23,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨3/4⟩과 ⟨3/10⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨3/10⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 3개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨3/4⟩ > ⟨3/10⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#24','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C7',3,'mc','auto','세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 도하 ⟨7/10⟩, 유진 ⟨2/3⟩, 채원 ⟨3/8⟩. 가장 많이 마신 사람은 누구인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X09']::text[],false,'{"seq":24,"concept":"M5-1-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 도하 ⟨7/10⟩, 유진 ⟨2/3⟩, 채원 ⟨3/8⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"도하","correct":true},{"t":"유진","mis":"M5-1-u3-X13"},{"t":"채원","mis":"M5-1-u3-X13"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 120으로 나타내면 ⟨7/10⟩ = ⟨84/120⟩, ⟨2/3⟩ = ⟨80/120⟩, ⟨3/8⟩ = ⟨45/120⟩예요.","⟨7/10⟩ > ⟨2/3⟩ > ⟨3/8⟩ — 가장 많이 마신 사람은 도하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_c#25','math',5,1,'u3','','g5_1_math_u3_review_c','unit_review','M5-1-u3-C7',4,'mc','auto','충전량이 각각 ⟨4/9⟩, ⟨5/12⟩, ⟨7/18⟩, ⟨1/3⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?',ARRAY['M5-1-u3-X09','M5-1-u3-X11']::text[],false,'{"seq":25,"concept":"M5-1-u3-C7","difficulty":4,"kind":"mc","stem":"충전량이 각각 ⟨4/9⟩, ⟨5/12⟩, ⟨7/18⟩, ⟨1/3⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨5/12⟩","mis":"M5-1-u3-X09"},{"t":"⟨7/18⟩","mis":"M5-1-u3-X09"},{"t":"⟨1/3⟩","mis":"M5-1-u3-X11"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 36으로 나타내면 ⟨4/9⟩ = ⟨16/36⟩, ⟨5/12⟩ = ⟨15/36⟩, ⟨7/18⟩ = ⟨14/36⟩, ⟨1/3⟩ = ⟨12/36⟩예요.","가장 큰 것은 ⟨4/9⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#1','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C1',1,'mc','auto','같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":1,"concept":"M5-1-u3-C1","difficulty":1,"kind":"mc","stem":"같은 길이의 띠 두 개를 그림처럼 나누어 색칠했어요. 두 분수의 크기를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩ = ⟨6/10⟩","correct":true},{"t":"⟨3/5⟩ < ⟨6/10⟩","mis":"M5-1-u3-X04"},{"t":"⟨3/5⟩ > ⟨6/10⟩","mis":"M5-1-u3-X04"},{"t":"이름이 달라서 견줄 수 없다","mis":"M5-1-u3-X04"}],"explanation":["위 띠는 5칸 중 3칸, 아래 띠는 10칸 중 6칸을 색칠했어요.","색칠한 끝이 같은 자리에서 멈춰요 — 칸을 2배로 잘게 나누었을 뿐이에요.","그래서 ⟨3/5⟩ = ⟨6/10⟩ — 이름은 달라도 양은 같아요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"label":"⟨3/5⟩"},{"den":10,"num":6,"label":"⟨6/10⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#2','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C1',2,'mc','auto','⟨5/6⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?',ARRAY['M5-1-u3-X04']::text[],false,'{"seq":2,"concept":"M5-1-u3-C1","difficulty":2,"kind":"mc","stem":"⟨5/6⟩와 크기가 같은 분수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨10/12⟩","mis":"M5-1-u3-X04"},{"t":"⟨15/18⟩","mis":"M5-1-u3-X04"},{"t":"⟨20/24⟩","mis":"M5-1-u3-X04"}],"explanation":["⟨5/6⟩ = ⟨10/12⟩ = ⟨15/18⟩ = ⟨20/24⟩이에요 — 모두 분모와 분자에 같은 수를 곱하거나 나눈 분수예요.","⟨6/7⟩은 ⟨5/6⟩의 분모와 분자에 같은 수를 곱하거나 나누어 만들 수 없어요.","⟨6/7⟩ ≠ ⟨5/6⟩ — 크기가 같은 분수가 아닌 것은 ⟨6/7⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#3','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C2',1,'sa','auto','⟨4/5⟩ = ⟨□/25⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-1-u3-C2","difficulty":1,"kind":"sa","stem":"⟨4/5⟩ = ⟨□/25⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["분모 5에 5를 곱해 25가 되었어요 — 5 × 5 = 25.","분자에도 같은 수 5를 곱해요 — 4 × 5 = 20.","⟨4/5⟩ = ⟨20/25⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#4','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C2',1,'mc','auto','⟨15/20⟩의 분모와 분자를 각각 5로 나누면 어떤 분수가 되나요?',ARRAY['M5-1-u3-X01','M5-1-u3-X02']::text[],false,'{"seq":4,"concept":"M5-1-u3-C2","difficulty":1,"kind":"mc","stem":"⟨15/20⟩의 분모와 분자를 각각 5로 나누면 어떤 분수가 되나요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X01"},{"t":"⟨3/20⟩","mis":"M5-1-u3-X02"},{"t":"⟨15/4⟩","mis":"M5-1-u3-X02"}],"explanation":["분모 20 ÷ 5 = 4, 분자 15 ÷ 5 = 3이에요.","⟨15/20⟩ = ⟨3/4⟩ — 분모와 분자를 같은 수로 나누어도 크기는 그대로예요.","분모나 분자 한쪽만 나누면 크기가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#5','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C2',3,'sa','auto','⟨5/6⟩와 크기가 같은 분수 중 분모가 20보다 크고 50보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u3-C2","difficulty":3,"kind":"sa","stem":"⟨5/6⟩와 크기가 같은 분수 중 분모가 20보다 크고 50보다 작은 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["⟨5/6⟩와 크기가 같은 분수의 분모는 6의 배수예요.","20보다 크고 50보다 작은 6의 배수는 24, 30, 36, 42, 48이에요.","⟨20/24⟩, ⟨25/30⟩, ⟨30/36⟩, ⟨35/42⟩, ⟨40/48⟩ — 모두 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#6','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C3',1,'mc','auto','⟨14/42⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X02']::text[],false,'{"seq":6,"concept":"M5-1-u3-C3","difficulty":1,"kind":"mc","stem":"⟨14/42⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨7/21⟩","mis":"M5-1-u3-X05"},{"t":"⟨2/6⟩","mis":"M5-1-u3-X05"},{"t":"⟨1/42⟩","mis":"M5-1-u3-X02"}],"explanation":["14와 42의 공약수는 1, 2, 7, 14, 최대공약수는 14예요.","최대공약수로 나누면 한 번에 끝나요 — 14 ÷ 14 = 1, 42 ÷ 14 = 3.","⟨14/42⟩ = ⟨1/3⟩ — 공약수가 1뿐이라 기약분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#7','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C3',2,'mc','auto','기약분수인 것은 어느 것인가요?',ARRAY['M5-1-u3-X05']::text[],false,'{"seq":7,"concept":"M5-1-u3-C3","difficulty":2,"kind":"mc","stem":"기약분수인 것은 어느 것인가요?","options":[{"t":"⟨11/15⟩","correct":true},{"t":"⟨10/15⟩","mis":"M5-1-u3-X05"},{"t":"⟨12/18⟩","mis":"M5-1-u3-X05"},{"t":"⟨15/21⟩","mis":"M5-1-u3-X05"}],"explanation":["⟨10/15⟩은 5로 약분돼요 · ⟨12/18⟩는 6으로 약분돼요 · ⟨15/21⟩는 3으로 약분돼요.","11과 15의 공약수는 1뿐이에요.","그래서 더 약분할 수 없는 기약분수는 ⟨11/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#8','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C3',3,'sa','auto','⟨16/48⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"⟨16/48⟩을 약분하여 만들 수 있는 분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["16과 48의 공약수는 1, 2, 4, 8, 16이에요.","1이 아닌 공약수 2, 4, 8, 16으로 한 번씩 나누어요.","⟨8/24⟩, ⟨4/12⟩, ⟨2/6⟩, ⟨1/3⟩ — 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#9','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C3',3,'sa','auto','분모가 60인 분수를 약분했더니 ⟨7/12⟩이 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u3-C3","difficulty":3,"kind":"sa","stem":"분모가 60인 분수를 약분했더니 ⟨7/12⟩이 되었어요. 처음 분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["약분한 것을 되돌리면 분모와 분자에 같은 수를 곱해요.","분모 12를 60으로 만들려면 12 × 5 = 60 — 5를 곱해요.","분자도 7 × 5 = 35 — 처음 분수는 ⟨35/60⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#10','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C4',1,'sa','auto','⟨2/3⟩와 ⟨1/7⟩을 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u3-C4","difficulty":1,"kind":"sa","stem":"⟨2/3⟩와 ⟨1/7⟩을 두 분모의 최소공배수로 통분하면 공통분모는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["3의 배수: 3, 6, 9, 12, 15, 18, 21, 24 … · 7의 배수: 7, 14, 21, 28 …","처음으로 함께 나오는 수가 최소공배수 21이에요.","그래서 공통분모는 21 — ⟨14/21⟩, ⟨3/21⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#11','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C4',2,'mc','auto','⟨3/8⟩과 ⟨1/12⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?',ARRAY['M5-1-u3-X07','M5-1-u3-X13','M5-1-u3-X08']::text[],false,'{"seq":11,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨3/8⟩과 ⟨1/12⟩을 두 분모의 최소공배수로 통분하면 어느 것인가요?","options":[{"t":"⟨9/24⟩, ⟨2/24⟩","correct":true},{"t":"⟨3/24⟩, ⟨1/24⟩","mis":"M5-1-u3-X07"},{"t":"⟨6/24⟩, ⟨3/24⟩","mis":"M5-1-u3-X13"},{"t":"⟨36/96⟩, ⟨8/96⟩","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모의 최소공배수 24예요.","⟨3/8⟩의 분모와 분자에 3을, ⟨1/12⟩의 분모와 분자에 2를 곱해요.","⟨3/8⟩ = ⟨9/24⟩, ⟨1/12⟩ = ⟨2/24⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#12','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C4',2,'mc','auto','⟨3/4⟩과 ⟨1/10⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?',ARRAY['M5-1-u3-X08']::text[],false,'{"seq":12,"concept":"M5-1-u3-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩과 ⟨1/10⟩을 통분할 때 공통분모가 될 수 없는 수는 어느 것인가요?","options":[{"t":"30","correct":true},{"t":"20","mis":"M5-1-u3-X08"},{"t":"40","mis":"M5-1-u3-X08"},{"t":"60","mis":"M5-1-u3-X08"}],"explanation":["공통분모는 두 분모 4와 10의 공배수예요.","4와 10의 공배수는 20, 40, 60 …이에요.","30은 10의 배수이지만 4의 배수는 아니에요 — 그래서 공통분모가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#13','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C4',4,'sa','auto','⟨2/9⟩, ⟨1/3⟩, ⟨5/6⟩를 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-1-u3-C4","difficulty":4,"kind":"sa","stem":"⟨2/9⟩, ⟨1/3⟩, ⟨5/6⟩를 세 분모의 최소공배수로 통분했을 때 세 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["세 분모 9, 3, 6의 최소공배수는 18이에요.","⟨2/9⟩ = ⟨4/18⟩, ⟨1/3⟩ = ⟨6/18⟩, ⟨5/6⟩ = ⟨15/18⟩예요.","분자의 합은 4 + 6 + 15 = 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#14','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C5',1,'mc','auto','⟨1/2⟩과 ⟨1/5⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":14,"concept":"M5-1-u3-C5","difficulty":1,"kind":"mc","stem":"⟨1/2⟩과 ⟨1/5⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"분모가 달라서 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 길이를 2칸과 5칸으로 나누면 칸이 많을수록 한 칸이 작아요.","분모가 작은 쪽의 한 칸이 더 커요.","그래서 ⟨1/2⟩ > ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"label":"⟨1/2⟩"},{"den":5,"num":1,"label":"⟨1/5⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#15','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C5',2,'mc','auto','두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#16','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C5',3,'mc','auto','⟨2/3⟩, ⟨5/7⟩, ⟨3/5⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M5-1-u3-X14','M5-1-u3-X09','M5-1-u3-X13']::text[],false,'{"seq":16,"concept":"M5-1-u3-C5","difficulty":3,"kind":"mc","stem":"⟨2/3⟩, ⟨5/7⟩, ⟨3/5⟩을 큰 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"⟨5/7⟩, ⟨2/3⟩, ⟨3/5⟩","correct":true},{"t":"⟨3/5⟩, ⟨2/3⟩, ⟨5/7⟩","mis":"M5-1-u3-X14"},{"t":"⟨5/7⟩, ⟨3/5⟩, ⟨2/3⟩","mis":"M5-1-u3-X09"},{"t":"⟨2/3⟩, ⟨5/7⟩, ⟨3/5⟩","mis":"M5-1-u3-X13"}],"explanation":["공통분모 105로 나타내면 ⟨2/3⟩ = ⟨70/105⟩, ⟨5/7⟩ = ⟨75/105⟩, ⟨3/5⟩ = ⟨63/105⟩이에요.","견주면 ⟨75/105⟩ > ⟨70/105⟩ > ⟨63/105⟩이에요.","그래서 큰 것부터 쓰면 ⟨5/7⟩, ⟨2/3⟩, ⟨3/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#17','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C5',3,'sa','auto','1부터 9까지의 수 중에서 ⟨□/8⟩ > ⟨5/6⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-1-u3-C5","difficulty":3,"kind":"sa","stem":"1부터 9까지의 수 중에서 ⟨□/8⟩ > ⟨5/6⟩가 되게 하는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["24로 통분하면 ⟨5/6⟩ = ⟨20/24⟩이고, ⟨□/8⟩의 분자는 □ × 3이 돼요.","□ × 3이 20보다 커야 해요 — □는 7, 8, 9.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#18','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C6',1,'mc','auto','⟨4/25⟩를 소수로 나타내면 얼마인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X13']::text[],false,'{"seq":18,"concept":"M5-1-u3-C6","difficulty":1,"kind":"mc","stem":"⟨4/25⟩를 소수로 나타내면 얼마인가요?","options":[{"t":"0.16","correct":true},{"t":"0.425","mis":"M5-1-u3-X12"},{"t":"0.4","mis":"M5-1-u3-X12"},{"t":"0.25","mis":"M5-1-u3-X13"}],"explanation":["분모를 100으로 만들어요 — 분모와 분자에 4를 곱해요.","⟨4/25⟩ = ⟨16/100⟩이에요.","⟨16/100⟩ = 0.16 — 소수로 0.16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#19','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C6',2,'mc','auto','0.24를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-1-u3-X05','M5-1-u3-X12']::text[],false,'{"seq":19,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"0.24를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨6/25⟩","correct":true},{"t":"⟨24/100⟩","mis":"M5-1-u3-X05"},{"t":"⟨24/10⟩","mis":"M5-1-u3-X12"},{"t":"⟨1/24⟩","mis":"M5-1-u3-X12"}],"explanation":["0.24 = ⟨24/100⟩예요 — 소수 두 자리 수라 분모가 100이에요.","24와 100의 최대공약수 4로 약분해요 — 24 ÷ 4 = 6, 100 ÷ 4 = 25.","⟨24/100⟩ = ⟨6/25⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#20','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C6',2,'mc','auto','⟨7/20⟩과 0.3 중 더 큰 수는 어느 것인가요?',ARRAY['M5-1-u3-X12','M5-1-u3-X08']::text[],false,'{"seq":20,"concept":"M5-1-u3-C6","difficulty":2,"kind":"mc","stem":"⟨7/20⟩과 0.3 중 더 큰 수는 어느 것인가요?","options":[{"t":"⟨7/20⟩","correct":true},{"t":"0.3","mis":"M5-1-u3-X12"},{"t":"두 수는 같다","mis":"M5-1-u3-X12"},{"t":"분수와 소수는 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["같은 꼴로 바꾸어 견주어요 — ⟨7/20⟩ = 0.35.","0.35 > 0.3이에요.","그래서 더 큰 수는 ⟨7/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#21','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C6',4,'sa','auto','⟨3/4⟩, 0.7, ⟨18/25⟩, 0.74, ⟨37/50⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M5-1-u3-C6","difficulty":4,"kind":"sa","stem":"⟨3/4⟩, 0.7, ⟨18/25⟩, 0.74, ⟨37/50⟩ 중 가장 큰 수를 소수로 쓰면 0.□□예요. □□에 알맞은 두 자리 수는 얼마인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["분수를 소수로 바꾸어요 — ⟨3/4⟩ = 0.75, ⟨18/25⟩ = 0.72, ⟨37/50⟩ = 0.74.","가장 큰 수는 0.75예요.","□□에 알맞은 수는 75예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#22','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C7',1,'mc','auto','⟨7/12⟩, ⟨5/11⟩, ⟨8/13⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?',ARRAY['M5-1-u3-X10']::text[],false,'{"seq":22,"concept":"M5-1-u3-C7","difficulty":1,"kind":"mc","stem":"⟨7/12⟩, ⟨5/11⟩, ⟨8/13⟩ 중 ⟨1/2⟩보다 작은 분수는 어느 것인가요?","options":[{"t":"⟨5/11⟩","correct":true},{"t":"⟨7/12⟩","mis":"M5-1-u3-X10"},{"t":"⟨8/13⟩","mis":"M5-1-u3-X10"},{"t":"없다","mis":"M5-1-u3-X10"}],"explanation":["분자를 2배 해서 분모와 견주어요.","7 × 2 = 14가 12보다 커서 ⟨7/12⟩ > ⟨1/2⟩ · 5 × 2 = 10이 11보다 작아서 ⟨5/11⟩ < ⟨1/2⟩ · 8 × 2 = 16이 13보다 커서 ⟨8/13⟩ > ⟨1/2⟩.","⟨1/2⟩보다 작은 분수는 ⟨5/11⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#23','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C7',2,'mc','auto','⟨7/11⟩과 ⟨7/9⟩ 중 더 큰 분수는 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X09','M5-1-u3-X08']::text[],false,'{"seq":23,"concept":"M5-1-u3-C7","difficulty":2,"kind":"mc","stem":"⟨7/11⟩과 ⟨7/9⟩ 중 더 큰 분수는 어느 것인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨7/11⟩","mis":"M5-1-u3-X11"},{"t":"분자가 같아서 두 분수는 같다","mis":"M5-1-u3-X09"},{"t":"통분하지 않으면 견줄 수 없다","mis":"M5-1-u3-X08"}],"explanation":["두 분수 모두 조각이 7개로 같아요.","조각 개수가 같으면 조각 하나가 큰 쪽, 곧 분모가 작은 쪽이 커요.","그래서 ⟨7/9⟩ > ⟨7/11⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#24','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C7',3,'mc','auto','세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 이준 ⟨3/5⟩, 소미 ⟨5/8⟩, 한결 ⟨1/4⟩. 가장 많이 마신 사람은 누구인가요?',ARRAY['M5-1-u3-X13','M5-1-u3-X09']::text[],false,'{"seq":24,"concept":"M5-1-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 같은 크기의 물병에서 마신 물의 양이에요. 이준 ⟨3/5⟩, 소미 ⟨5/8⟩, 한결 ⟨1/4⟩. 가장 많이 마신 사람은 누구인가요?","options":[{"t":"소미","correct":true},{"t":"이준","mis":"M5-1-u3-X13"},{"t":"한결","mis":"M5-1-u3-X13"},{"t":"세 사람 모두 같다","mis":"M5-1-u3-X09"}],"explanation":["⟨1/2⟩ 기준·분자 같음으로 먼저 가려 보고, 남은 것은 통분해요.","공통분모 40으로 나타내면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩, ⟨1/4⟩ = ⟨10/40⟩이에요.","⟨5/8⟩ > ⟨3/5⟩ > ⟨1/4⟩ — 가장 많이 마신 사람은 소미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u3_review_d#25','math',5,1,'u3','','g5_1_math_u3_review_d','unit_review','M5-1-u3-C7',4,'mc','auto','충전량이 각각 ⟨5/6⟩, ⟨7/9⟩, ⟨11/12⟩, ⟨8/9⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?',ARRAY['M5-1-u3-X11','M5-1-u3-X13']::text[],false,'{"seq":25,"concept":"M5-1-u3-C7","difficulty":4,"kind":"mc","stem":"충전량이 각각 ⟨5/6⟩, ⟨7/9⟩, ⟨11/12⟩, ⟨8/9⟩인 전기 자동차 네 대가 있어요. 가장 많이 충전된 자동차의 충전량은 어느 것인가요?","options":[{"t":"⟨11/12⟩","correct":true},{"t":"⟨5/6⟩","mis":"M5-1-u3-X11"},{"t":"⟨7/9⟩","mis":"M5-1-u3-X13"},{"t":"⟨8/9⟩","mis":"M5-1-u3-X13"}],"explanation":["네 분수 모두 ⟨1/2⟩의 같은 쪽에 있어 기준으로는 가릴 수 없어요.","공통분모 36으로 나타내면 ⟨5/6⟩ = ⟨30/36⟩, ⟨7/9⟩ = ⟨28/36⟩, ⟨11/12⟩ = ⟨33/36⟩, ⟨8/9⟩ = ⟨32/36⟩예요.","가장 큰 것은 ⟨11/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
